// 9UPPER (瞎掰王) term bank - the merged, de-duplicated, fact-checked bank (built from the n1..n6 shards).
// Shape: default export is an array of
//   { term: string, explain: string (TRUE, Traditional Chinese, <= 90 chars), cat: string, level: 1 | 2 | 3, src: string (https URL) }
// cat   - one of the 16 categories in CATEGORIES (js/games/9upper/game.js)
// level - obscurity: 1 = some people know the term, 3 = almost nobody. Written in Hong Kong Cantonese.
// src   - a page that supports the explanation (percent-encoded URL)
export default [
  // ---------------------------------------------------------- 冷門中文詞語
  { term: '靉靆', explain: '本來形容雲層濃密昏暗嘅樣子，明代起被借嚟指由外地傳入嘅眼鏡。', cat: '冷門中文詞語', level: 3, src: 'https://www.moedict.tw/%E9%9D%89%E9%9D%86' },
  { term: '黑甜鄉', explain: '指睡鄉、夢鄉。「黑甜」出自蘇軾詩句「一枕黑甜餘」，形容睡得又沉又香。', cat: '冷門中文詞語', level: 2, src: 'https://www.moedict.tw/%E9%BB%91%E7%94%9C' },
  { term: '觳觫', explain: '因為驚恐而發抖嘅樣子。《孟子》記齊宣王見有人牽牛去殺嚟釁鐘，牛觳觫發抖，佢於心不忍，下令換羊。', cat: '冷門中文詞語', level: 3, src: 'https://www.moedict.tw/%E8%A7%B3%E8%A7%AB' },
  { term: '饔飧', explain: '饔係早餐、飧係晚餐，合稱泛指日常飲食；「饔飧不繼」就係窮到食唔飽。', cat: '冷門中文詞語', level: 3, src: 'https://www.moedict.tw/%E9%A5%94%E9%A3%A7' },
  { term: '杖朝', explain: '指八十歲。《禮記》話八十歲嘅老人可以拿住拐杖上朝廷，所以八十歲又叫杖朝。', cat: '冷門中文詞語', level: 3, src: 'https://zh.wikisource.org/wiki/%E7%A6%AE%E8%A8%98/%E7%8E%8B%E5%88%B6' },
  { term: '期頤', explain: '指一百歲。人活到百歲，起居飲食要靠後輩奉養，所以《禮記》稱為「期頤」。', cat: '冷門中文詞語', level: 1, src: 'https://www.moedict.tw/%E6%9C%9F%E9%A0%A4' },
  { term: '髫齡', explain: '指兒童時期。髫係小孩子頭上下垂嘅頭髮，所以「垂髫」「髫齡」都借髮型代指幼童。', cat: '冷門中文詞語', level: 3, src: 'https://www.moedict.tw/%E9%AB%AB%E9%BD%A1' },
  { term: '匝月', explain: '指滿一個月、足足一個月。「匝」解環繞一周，例如「匝月之內」就係一個月內。', cat: '冷門中文詞語', level: 2, src: 'https://www.moedict.tw/%E5%8C%9D%E6%9C%88' },
  { term: '彌月', explain: '指嬰兒出生滿一個月。「彌」解作滿、足，所以「彌月之喜」就係賀人家BB滿月。', cat: '冷門中文詞語', level: 1, src: 'https://www.moedict.tw/%E5%BD%8C%E6%9C%88' },
  { term: '孑孓', explain: '蚊嘅幼蟲，喺水入面生活，游水時身體一屈一伸，所以又叫「跟頭蟲」。', cat: '冷門中文詞語', level: 1, src: 'https://www.moedict.tw/%E5%AD%91%E5%AD%93' },
  { term: '枵腹', explain: '枵解作空虛，「枵腹」即係肚子空空、捱住餓；成語「枵腹從公」指餓住肚都照樣辦公事。', cat: '冷門中文詞語', level: 3, src: 'https://www.moedict.tw/%E6%9E%B5%E8%85%B9%E5%BE%9E%E5%85%AC' },
  { term: '斗筲', explain: '斗同筲都係容量好細嘅盛器，古人借嚟形容器量窄、見識淺嘅人，《論語》有「斗筲之人」。', cat: '冷門中文詞語', level: 3, src: 'https://www.moedict.tw/%E6%96%97%E7%AD%B2' },
  { term: '臧否', explain: '「臧」係好、「否」係壞，臧否即係評論好壞。諸葛亮《出師表》有「陟罰臧否」。', cat: '冷門中文詞語', level: 1, src: 'https://www.moedict.tw/%E8%87%A7%E5%90%A6' },
  { term: '睚眥', explain: '本義係瞪大眼睛怒目而視，後來引申為細微嘅怨恨，成語有「睚眥必報」。', cat: '冷門中文詞語', level: 2, src: 'https://www.moedict.tw/%E7%9D%9A%E7%9C%A5%E5%BF%85%E5%A0%B1' },
  { term: '逆旅', explain: '指旅館、客棧。李白寫「夫天地者，萬物之逆旅」，即係話天地好似一間大客棧。', cat: '冷門中文詞語', level: 2, src: 'https://www.moedict.tw/%E9%80%86%E6%97%85' },
  { term: '尺素', explain: '指書信。古人將信寫喺一尺長嘅白絹上，所以書信又叫「尺素」。', cat: '冷門中文詞語', level: 2, src: 'https://www.moedict.tw/%E5%B0%BA%E7%B4%A0' },
  { term: '皕', explain: '一個單字，意思係二百，由兩個「百」字疊埋一齊，普通話讀bì。', cat: '冷門中文詞語', level: 3, src: 'https://www.moedict.tw/%E7%9A%95' },
  { term: '卌', explain: '一個單字，意思係四十，同「廿」（二十）、「卅」（三十）一樣，係數字合寫而成。', cat: '冷門中文詞語', level: 3, src: 'https://www.moedict.tw/%E5%8D%8C' },
  { term: '踽踽', explain: '形容一個人孤零零、冷清清咁獨自行路，例如「踽踽獨行」。', cat: '冷門中文詞語', level: 3, src: 'https://www.moedict.tw/%E8%B8%BD%E8%B8%BD' },
  { term: '齟齬', explain: '本來指牙齒上下排得唔整齊，後來比喻雙方意見不合、互相抵觸。', cat: '冷門中文詞語', level: 3, src: 'https://www.moedict.tw/%E9%BD%9F%E9%BD%AC' },
  { term: '闃寂', explain: '形容靜到一點聲都冇。「闃」字本身已經解作寂靜，《易經》有「闃其無人」。', cat: '冷門中文詞語', level: 3, src: 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%B1%90' },
  { term: '縲絏', explain: '縲同絏都係捆綁犯人嘅黑色粗繩，借指牢獄。《論語》有「雖在縲絏之中，非其罪也」。', cat: '冷門中文詞語', level: 3, src: 'https://www.moedict.tw/%E7%B8%B2%E7%B5%8F' },
  { term: '鷦鷯', explain: '一種體型好細嘅小鳥。《莊子》話牠就算住喺深林，都只不過佔一條樹枝。', cat: '冷門中文詞語', level: 2, src: 'https://zh.wikisource.org/wiki/%E8%8E%8A%E5%AD%90/%E9%80%8D%E9%81%99%E9%81%8A' },
  { term: '螟蛉', explain: '一種青色小蟲。古人誤以為蜾蠃（細腰蜂）會將牠養大做子女，所以「螟蛉」借指養子。', cat: '冷門中文詞語', level: 2, src: 'https://www.moedict.tw/%E8%9E%9F%E8%9B%89' },
  { term: '舳艫', explain: '「舳」係船尾、「艫」係船頭，合稱就係船隻；「舳艫千里」形容船隊首尾相接好長。', cat: '冷門中文詞語', level: 3, src: 'https://www.moedict.tw/%E8%88%B3%E8%89%AB%E5%8D%83%E9%87%8C' },
  { term: '晦日', explain: '農曆每月嘅最後一日，即係月底。初一叫「朔」，月亮完全唔見嗰日就叫「晦」。', cat: '冷門中文詞語', level: 2, src: 'https://www.moedict.tw/%E6%99%A6%E6%97%A5' },
  { term: '蟪蛄', explain: '一種壽命好短嘅小蟬。《莊子》話牠「不知春秋」，因為活唔到一年，見唔齊春季同秋季。', cat: '冷門中文詞語', level: 3, src: 'https://zh.wikisource.org/wiki/%E8%8E%8A%E5%AD%90/%E9%80%8D%E9%81%99%E9%81%8A' },
  { term: '朝菌', explain: '一種朝生暮死嘅菌類。《莊子》話牠「不知晦朔」，因為壽命短過一個月，未見過月初月尾。', cat: '冷門中文詞語', level: 3, src: 'https://zh.wikisource.org/wiki/%E8%8E%8A%E5%AD%90/%E9%80%8D%E9%81%99%E9%81%8A' },
  { term: '簋', explain: '古代用嚟盛載黍稷等熟穀物嘅圓口食器，常見青銅製品，同鼎經常一齊出現。', cat: '冷門中文詞語', level: 3, src: 'https://www.moedict.tw/%E7%B0%8B' },
  { term: '觥', explain: '古代一種酒器，最初用兕牛角做。「觥籌交錯」就係形容酒杯同酒籌交錯嘅熱鬧宴席。', cat: '冷門中文詞語', level: 3, src: 'https://www.moedict.tw/%E8%A7%A5' },
  { term: '甗', explain: '古代蒸煮食物嘅炊具，上半部用嚟蒸、下半部煮水，似古代嘅蒸籠兼煲，讀音似「演」。', cat: '冷門中文詞語', level: 3, src: 'https://www.moedict.tw/%E7%94%97' },
  { term: '笏', explain: '古代大臣上朝時手持嘅長條形板，用嚟記事備忘，質料按官階高低而唔同。', cat: '冷門中文詞語', level: 1, src: 'https://www.moedict.tw/%E7%AC%8F' },
  { term: '葳蕤', explain: '形容草木茂盛、枝葉下垂嘅樣子，張九齡有詩句「蘭葉春葳蕤」。', cat: '冷門中文詞語', level: 3, src: 'https://www.moedict.tw/%E8%91%B3%E8%95%A4' },
  { term: '鬻', explain: '一個單字，解作賣，例如「鬻文為生」就係靠寫文章賣錢過活。', cat: '冷門中文詞語', level: 3, src: 'https://www.moedict.tw/%E9%AC%BB' },
  { term: '鯫生', explain: '「鯫」係小魚，「鯫生」本來係罵人見識淺陋嘅小人，《史記·項羽本紀》有「鯫生說我曰」。', cat: '冷門中文詞語', level: 3, src: 'https://www.moedict.tw/%E9%AF%AB%E7%94%9F' },
  { term: '褦襶', explain: '有兩個意思：一係夏天戴嚟遮日嘅斗笠，二係形容人不懂事、不曉事理。', cat: '冷門中文詞語', level: 3, src: 'https://www.moedict.tw/%E8%A4%A6%E8%A5%B6' },
  { term: '蹀躞', explain: '形容小步行走嘅樣子；另外亦指繫喺衣帶上嘅飾物。', cat: '冷門中文詞語', level: 3, src: 'https://www.moedict.tw/%E8%B9%80%E8%BA%9E' },
  { term: '夤夜', explain: '指深夜。「夤」解作深，《三國演義》有「國舅夤夜至此，必有事故」。', cat: '冷門中文詞語', level: 2, src: 'https://www.moedict.tw/%E5%A4%A4%E5%A4%9C' },
  // ---------------------------------------------------------- 成語典故
  { term: '曲突徙薪', explain: '有客人勸主人將直煙囪改彎、將柴搬遠防火，主人唔聽，後來真係失火，比喻防患於未然。', cat: '成語典故', level: 2, src: 'https://zh.wikisource.org/wiki/%E6%BC%A2%E6%9B%B8/%E5%8D%B7068' },
  { term: '投鼠忌器', explain: '漢代賈誼引民間諺語「欲投鼠而忌器」：想打老鼠，又怕打爛旁邊嘅器皿，比喻想除掉壞人，又顧忌傷及身邊重要嘅人或事。', cat: '成語典故', level: 2, src: 'https://zh.wikisource.org/wiki/%E6%BC%A2%E6%9B%B8/%E5%8D%B7048' },
  { term: '入我彀中', explain: '「彀」係弓箭嘅射程範圍。《唐摭言》記唐太宗見新科進士魚貫而出，笑說天下英雄都入我彀中。', cat: '成語典故', level: 2, src: 'https://zh.wikisource.org/wiki/%E5%94%90%E6%91%AD%E8%A8%80/%E5%8D%B7%E4%B8%80' },
  { term: '焦尾琴', explain: '東漢蔡邕聽到有人燒桐木嘅爆裂聲，知係好木，搶救出嚟造琴，琴尾仍燒焦，故名焦尾。', cat: '成語典故', level: 2, src: 'https://www.moedict.tw/%E7%84%A6%E5%B0%BE%E7%90%B4' },
  { term: '夢筆生花', explain: '相傳李白少年時夢見自己支筆頭開出花，之後文思大進，名聞天下。', cat: '成語典故', level: 2, src: 'https://www.moedict.tw/%E5%A4%A2%E7%AD%86%E7%94%9F%E8%8A%B1' },
  { term: '牛角掛書', explain: '隋末李密騎牛出行，將《漢書》掛喺牛角上，一路行一路睇，後比喻讀書勤奮。', cat: '成語典故', level: 2, src: 'https://www.moedict.tw/%E7%89%9B%E8%A7%92%E6%8E%9B%E6%9B%B8' },
  { term: '銜環', explain: '相傳東漢楊寶救咗隻受傷嘅黃雀，黃雀後來化作童子，獻上四枚白玉環報恩。', cat: '成語典故', level: 2, src: 'https://www.moedict.tw/%E9%8A%9C%E7%92%B0' },
  { term: '咄咄怪事', explain: '東晉殷浩被貶後，成日用手指喺空中寫字，旁人偷睇，原來寫嘅只係「咄咄怪事」四字。', cat: '成語典故', level: 2, src: 'https://zh.wikisource.org/wiki/%E4%B8%96%E8%AA%AA%E6%96%B0%E8%AA%9E/%E9%BB%9C%E5%85%8D' },
  { term: '染指', explain: '春秋時鄭靈公請大臣食大鱉，偏偏冇畀公子宋，佢一怒之下將手指伸入鼎中嘗一嘗，「染指」由此而來。', cat: '成語典故', level: 2, src: 'https://www.moedict.tw/%E6%9F%93%E6%8C%87' },
  { term: '郢書燕說', explain: '楚人寫信時叫人「舉燭」，順手寫咗入信，燕相誤解成「舉賢」，照住做反而治好國家，比喻曲解原意。', cat: '成語典故', level: 3, src: 'https://www.moedict.tw/%E9%83%A2%E6%9B%B8%E7%87%95%E8%AA%AA' },
  { term: '千金市骨', explain: '燕昭王求賢，郭隗講古：有君王花五百金買死千里馬嘅頭，結果一年內有三匹千里馬送上門。', cat: '成語典故', level: 3, src: 'https://www.moedict.tw/%E5%8D%83%E9%87%91%E5%B8%82%E9%AA%A8' },
  { term: '南柯一夢', explain: '唐代小說裡，淳于棼夢見去咗大槐安國做官，醒嚟發現所謂「國」，原來係大槐樹下嘅蟻穴。', cat: '成語典故', level: 1, src: 'https://www.moedict.tw/%E5%8D%97%E6%9F%AF%E4%B8%80%E5%A4%A2' },
  { term: '尸位素餐', explain: '「尸」係古代祭祀時代表死者受拜、坐喺度唔使做嘢嘅人，尸位素餐比喻佔住職位唔做事白拿俸祿。', cat: '成語典故', level: 2, src: 'https://www.moedict.tw/%E5%B0%B8%E4%BD%8D%E7%B4%A0%E9%A4%90' },
  { term: '脫穎而出', explain: '「穎」指錐尖。毛遂話如果早啲將佢放入袋裡，就會好似錐尖咁整個露出嚟，「脫穎而出」由此而來。', cat: '成語典故', level: 1, src: 'https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98/%E5%8D%B7076' },
  { term: '楚弓楚得', explain: '楚王出遊遺失咗弓，左右想去尋，佢話「楚王失弓，楚人得之」，唔使搵，比喻失去嘅仍留喺自己人手上。', cat: '成語典故', level: 3, src: 'https://zh.wikisource.org/wiki/%E5%AD%94%E5%AD%90%E5%AE%B6%E8%AA%9E/%E5%8D%B7%E4%BA%8C' },
  { term: '捉襟見肘', explain: '《莊子》記載曾子窮到穿爛衣，拉一拉衣襟就露出手肘，整理帽子連帽帶都斷咗。', cat: '成語典故', level: 1, src: 'https://zh.wikisource.org/wiki/%E8%8E%8A%E5%AD%90/%E8%AE%93%E7%8E%8B' },
  { term: '沐猴而冠', explain: '沐猴係獼猴。有人譏諷項羽燒咸陽後急於東歸，話楚人好似猴子戴帽，徒有外表。', cat: '成語典故', level: 2, src: 'https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98/%E5%8D%B7007' },
  { term: '退避三舍', explain: '晉文公流亡時受楚王款待，承諾日後交戰會退兵「三舍」。一舍係三十里，即退九十里。', cat: '成語典故', level: 1, src: 'https://www.moedict.tw/%E8%BE%9F%E5%90%9B%E4%B8%89%E8%88%8D' },
  { term: '莫逆之交', explain: '《莊子》記四個人相視而笑，心意相通、毫無違逆，就成為朋友，「莫逆之交」由此而來。', cat: '成語典故', level: 1, src: 'https://zh.wikisource.org/wiki/%E8%8E%8A%E5%AD%90/%E5%A4%A7%E5%AE%97%E5%B8%AB' },
  { term: '越俎代庖', explain: '祭祀時就算廚師唔煮餸，主祭嘅人都唔會跨過祭器去代做，比喻越權或多管閒事。', cat: '成語典故', level: 1, src: 'https://www.moedict.tw/%E8%B6%8A%E4%BF%8E%E4%BB%A3%E5%BA%96' },
  { term: '箭在弦上', explain: '《三國演義》寫陳琳替袁紹作檄文，連曹操祖宗都罵，被曹操質問時答「箭在弦上，不得不發」。', cat: '成語典故', level: 1, src: 'https://zh.wikisource.org/wiki/%E4%B8%89%E5%9C%8B%E6%BC%94%E7%BE%A9/%E7%AC%AC032%E5%9B%9E' },
  { term: '揮汗成雨', explain: '晏子形容齊國都城臨淄人多，話大家張開衣袖就成陰涼，揮一揮汗就似落雨。', cat: '成語典故', level: 2, src: 'https://www.moedict.tw/%E6%8F%AE%E6%B1%97%E6%88%90%E9%9B%A8' },
  { term: '管窺蠡測', explain: '「管」係竹管，「蠡」係瓠瓢，用竹管望天、用瓢量海，比喻見識淺窄。', cat: '成語典故', level: 3, src: 'https://www.moedict.tw/%E7%AE%A1%E7%AA%BA%E8%A0%A1%E6%B8%AC' },
  { term: '望洋興嘆', explain: '「望洋」唔係望住海洋，而係仰頭看嘅樣子。《莊子》寫河伯見到北海之大，仰望慨嘆自己渺小。', cat: '成語典故', level: 1, src: 'https://dict.idioms.moe.edu.tw/idiomView.jsp?ID=-920&webMd=1&la=1' },
  { term: '管寧割席', explain: '管寧同華歆同席讀書，見華歆放低書出去睇官員車馬經過，就將蓆割開，話「子非吾友也」。', cat: '成語典故', level: 2, src: 'https://zh.wikisource.org/wiki/%E4%B8%96%E8%AA%AA%E6%96%B0%E8%AA%9E/%E5%BE%B7%E8%A1%8C' },
  { term: '登龍門', explain: '傳說黃河鯉魚跳過龍門就化龍。東漢李膺名重一時，士人得到佢接見，就叫「登龍門」。', cat: '成語典故', level: 2, src: 'https://www.moedict.tw/%E7%99%BB%E9%BE%8D%E9%96%80' },
  { term: '倒屣相迎', explain: '東漢蔡邕聽到年輕嘅王粲嚟訪，急到鞋都穿反就衝出去迎接。', cat: '成語典故', level: 3, src: 'https://www.moedict.tw/%E5%80%92%E5%B1%A3%E8%BF%8E%E4%B9%8B' },
  { term: '下里巴人', explain: '宋玉對楚王講：有人喺郢都唱《下里巴人》，幾千人跟住唱；唱《陽春白雪》，就得幾十人和。', cat: '成語典故', level: 2, src: 'https://zh.wikisource.org/wiki/%E5%B0%8D%E6%A5%9A%E7%8E%8B%E5%95%8F' },
  { term: '雞犬升天', explain: '傳說淮南王劉安煉丹成仙，連家中食過剩丹藥嘅雞同狗都跟住升咗天。', cat: '成語典故', level: 2, src: 'https://www.moedict.tw/%E9%9B%9E%E7%8A%AC%E5%8D%87%E5%A4%A9' },
  { term: '羝羊觸藩', explain: '出自《易經》，公羊用角撞籬笆，角被卡住，進退唔得，比喻進退兩難。', cat: '成語典故', level: 3, src: 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%A4%A7%E5%A3%AF' },
  { term: '首鼠兩端', explain: '《史記》記田蚡罵韓安國「何為首鼠兩端」。「首鼠」係遲疑不決，傳統講法係老鼠出洞時一進一退。', cat: '成語典故', level: 2, src: 'https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98/%E5%8D%B7107' },
  { term: '篳路藍縷', explain: '「篳路」係用荊竹編成嘅簡陋柴車，「藍縷」係破爛衣服，形容開創事業時條件艱苦。', cat: '成語典故', level: 3, src: 'https://www.moedict.tw/%E7%AF%B3%E8%B7%AF%E8%97%8D%E7%B8%B7' },
  { term: '一字千金', explain: '呂不韋門客編成《呂氏春秋》，將書懸掛喺城門，話有人能增減一字就賞千金。', cat: '成語典故', level: 1, src: 'https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98/%E5%8D%B7085' },
  { term: '汗牛充棟', explain: '柳宗元形容有關《春秋》嘅著作多到：放喺屋入面就堆到頂樑，搬運時令牛馬流汗。', cat: '成語典故', level: 1, src: 'https://zh.wikisource.org/wiki/%E6%96%87%E9%80%9A%E5%85%88%E7%94%9F%E9%99%B8%E7%B5%A6%E4%BA%8B%E5%A2%93%E8%A1%A8' },
  { term: '畫餅充饑', explain: '三國時魏明帝話選人唔好只睇名氣，因為「名如畫地作餅，不可啖也」，成語由此而來。', cat: '成語典故', level: 1, src: 'https://zh.wikisource.org/wiki/%E4%B8%89%E5%9C%8B%E5%BF%97/%E5%8D%B722' },
  { term: '孺子可教', explain: '張良喺橋上幫老人執鞋、穿鞋，老人讚佢「孺子可教」，之後授佢《太公兵法》。', cat: '成語典故', level: 2, src: 'https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98/%E5%8D%B7055' },
  { term: '東床快婿', explain: '東晉郗鑒派人去王家選女婿，王家子弟都拘謹作態，獨有王羲之坦腹躺喺東床，若無其事，結果被選中。', cat: '成語典故', level: 2, src: 'https://zh.wikisource.org/wiki/%E4%B8%96%E8%AA%AA%E6%96%B0%E8%AA%9E/%E9%9B%85%E9%87%8F' },
  { term: '才高八斗', explain: '南朝謝靈運自誇，話天下嘅才華有一石，曹植獨佔八斗，自己得一斗，其餘人共分一斗。', cat: '成語典故', level: 1, src: 'https://www.moedict.tw/%E5%85%AB%E6%96%97%E4%B9%8B%E6%89%8D' },
  { term: '鞭長莫及', explain: '春秋時宋國向晉國求救，大夫伯宗勸晉侯唔好出兵，話「雖鞭之長，不及馬腹」：鞭再長都打唔到馬肚。', cat: '成語典故', level: 2, src: 'https://www.moedict.tw/%E9%9E%AD%E9%95%B7%E8%8E%AB%E5%8F%8A' },
  { term: '五日京兆', explain: '漢代京兆尹張敞嘅下屬絮舜以為佢快被免職，話「五日京兆耳」（做唔到五日），就唔肯再替佢辦案。', cat: '成語典故', level: 2, src: 'https://zh.wikisource.org/wiki/%E8%B3%87%E6%B2%BB%E9%80%9A%E9%91%91/%E5%8D%B7027' },
  { term: '懸羊頭賣狗肉', explain: '《晏子春秋》原句係「懸牛首於門，而賣馬肉於內」，後來《五燈會元》先寫成「懸羊頭賣狗肉」。', cat: '成語典故', level: 1, src: 'https://www.moedict.tw/%E6%87%B8%E7%BE%8A%E9%A0%AD%E8%B3%A3%E7%8B%97%E8%82%89' },
  { term: '請君入甕', explain: '武則天時酷吏來俊臣奉命審周興，問佢點樣令犯人招供，周興教「用大甕四周燒炭，叫犯人入去」，俊臣即請佢入甕。', cat: '成語典故', level: 1, src: 'https://zh.wikisource.org/wiki/%E8%B3%87%E6%B2%BB%E9%80%9A%E9%91%91/%E5%8D%B7204' },
  { term: '病入膏肓', explain: '「膏」係心下脂肪、「肓」係橫膈膜上嘅薄膜，古人話藥力去唔到。晉景公夢見病魔化作兩個小孩躲入嗰度。', cat: '成語典故', level: 1, src: 'https://www.moedict.tw/%E7%97%85%E5%85%A5%E8%86%8F%E8%82%93' },
  { term: '江郎才盡', explain: '南朝文人江淹晚年夢見郭璞向佢索還五色筆，自此作詩再冇佳句，時人話佢「才盡」。', cat: '成語典故', level: 1, src: 'https://zh.wikisource.org/wiki/%E5%8D%97%E5%8F%B2/%E5%8D%B759' },
  // ---------------------------------------------------------- 粵語俚語由來
  { term: '開天窗', explain: '原指報刊、雜誌因為被審查、作者欠稿或抗議等原因，版面留一片空白。', cat: '粵語俚語由來', level: 1, src: 'https://words.hk/zidin/%E9%96%8B%E5%A4%A9%E7%AA%97' },
  { term: '唔使問阿貴', explain: '相傳「阿貴」係清末廣東巡撫柏貴，佢被視為無能，下屬遇事唔會問佢，直接問上司葉名琛。', cat: '粵語俚語由來', level: 2, src: 'https://yue.wiktionary.org/wiki/%E5%94%94%E4%BD%BF%E5%95%8F%E9%98%BF%E8%B2%B4' },
  { term: '斗零', explain: '係五仙硬幣嘅舊稱。舊時商行用暗碼報數，「斗」代表三、「零」代表六，而五仙銀幣重三分六厘，所以叫「斗零」。', cat: '粵語俚語由來', level: 2, src: 'https://zh.wikipedia.org/wiki/%E9%A6%99%E6%B8%AF%E4%BA%94%E4%BB%99%E7%A1%AC%E5%B9%A3' },
  { term: '拍拖', explain: '原指珠江三角洲嘅小艇綁喺大船旁邊，由大船拖住行；後來借嚟形容兩個人談戀愛。', cat: '粵語俚語由來', level: 1, src: 'https://zh.wiktionary.org/wiki/%E6%8B%8D%E6%8B%96' },
  { term: '黐線', explain: '據講源於六十年代，電話線路共用或接駁不良，通話時會串到第二條線，所以叫「黐線」，後來借嚟形容人腦筋短路。', cat: '粵語俚語由來', level: 1, src: 'https://zh.wiktionary.org/wiki/%E9%BB%90%E7%B7%9A' },
  { term: '著草', explain: '黑社會暗語，指逃走；可能係「著草鞋」嘅簡化，因為舊時人出遠門都著草鞋。', cat: '粵語俚語由來', level: 2, src: 'https://yue.wiktionary.org/wiki/%E8%91%97%E8%8D%89' },
  { term: '沙塵白霍', explain: '形容人囂張愛炫耀。相傳廣州舊西關有闊佬陳沙同愛著白衫嘅霍氏，街頭鬥炫耀時撞正大風，雙雙跌低。', cat: '粵語俚語由來', level: 3, src: 'https://yue.wiktionary.org/wiki/%E6%B2%99%E5%A1%B5%E7%99%BD%E9%9C%8D' },
  { term: '二五仔', explain: '指告密、出賣同伴嘅人。相傳少林俗家弟子馬寧兒（排行第七）引清兵上山，會社就用「二加五等如七」暗指叛徒。', cat: '粵語俚語由來', level: 2, src: 'https://www.ourchinastory.com/zh/6491/%E4%BA%8C%E4%BA%94%E4%BB%94' },
  { term: '食白果', explain: '粵語俚語，指白忙一場、冇收穫。「白果」唔係銀杏，古時指雞蛋，食白果即係食蛋，同「零蛋」意思相近。', cat: '粵語俚語由來', level: 2, src: 'https://www.ourchinastory.com/zh/1338/%E9%A3%9F%E7%99%BD%E6%9E%9C' },
  { term: '事急馬行田', explain: '源自象棋：馬本來要行「日」字，「田」字係象嘅行法。事急時馬行田係犯規，比喻情況緊急就唔拘常規。', cat: '粵語俚語由來', level: 2, src: 'https://yue.wiktionary.org/wiki/%E4%BA%8B%E6%80%A5%E9%A6%AC%E8%A1%8C%E7%94%B0' },
  { term: '通勝', explain: '即係老黃曆。本來叫「通書」，因為「書」同「輸」同音，廣東人避諱，改用「勝」字。', cat: '粵語俚語由來', level: 1, src: 'https://zh.wiktionary.org/wiki/%E9%80%9A%E5%8B%9D' },
  { term: '燕梳', explain: '「燕梳」係英文insurance嘅粵語音譯，即係保險；「保險」就係意譯。', cat: '粵語俚語由來', level: 1, src: 'https://yue.wiktionary.org/wiki/%E7%87%95%E6%A2%B3' },
  { term: '大班', explain: '原指十九世紀中國同香港嘅外國大商人、洋行大老闆。英文「taipan」就係由粵語「大班」音譯。', cat: '粵語俚語由來', level: 2, src: 'https://zh.wikipedia.org/wiki/%E5%A4%A7%E7%8F%AD' },
  { term: '墟冚', explain: '形容人山人海、場面混亂。「墟」係舊時鄉村嘅市集，「冚」係借字，本字據講係「陷」，引申人馬沓雜。', cat: '粵語俚語由來', level: 2, src: 'https://www.wenweipo.com/a/202202/15/AP620abc6ee4b0a1098fd4ee3c.html' },
  { term: '三唔識七', explain: '粵語，形容素不相識、互不相干。源自天九牌：兩牌點數和只計個位，三加七成十即零點，係最差嘅組合。', cat: '粵語俚語由來', level: 2, src: 'https://www.ourchinastory.com/zh/6505/%E4%B8%89%E5%94%94%E8%AD%98%E4%B8%83---' },
  { term: '依撈七', explain: '舊粵語俚語，源自天九牌：「依」係「二」嘅諧音，二加七成九點，係最大嘅組合，比喻十拿九穩。', cat: '粵語俚語由來', level: 2, src: 'https://www.ourchinastory.com/zh/6504/%E4%BE%9D%E6%92%88%E4%B8%83' },
  { term: '膝頭哥唔食辣椒醬', explain: '粵語俗語，意思係「唔會畀你呃到」。「膝頭哥」即係膝蓋，本來叫「膝頭髁」，髁係膝蓋骨，同「哥」讀音相近。', cat: '粵語俚語由來', level: 2, src: 'https://www.ourchinastory.com/zh/1349/%E8%86%9D%E9%A0%AD%E5%93%A5%E5%94%94%E9%A3%9F%E8%BE%A3%E6%A4%92%E9%86%AC' },
  { term: '錢七', explain: '用嚟形容老舊、常出毛病嘅汽車或機器。「錢七」其實係船隻內燃機運作時發出嘅摩擦聲，同金錢無關。', cat: '粵語俚語由來', level: 3, src: 'https://www.ourchinastory.com/zh/6503' },
  { term: '一戙都無', explain: '粵語，指輸到清光。「戙」係疊起嘅天九牌，每兩隻疊成一戙，共十六戙，輸晒每戙牌就係「一戙都無」。', cat: '粵語俚語由來', level: 3, src: 'https://www.ourchinastory.com/zh/6519' },
  { term: '摸門釘', explain: '指探人但撲空。據講同石岐關帝廟有關：童工喺廟前等工作，閒到摸門釘，後來就指白行一轉。', cat: '粵語俚語由來', level: 2, src: 'https://www.ourchinastory.com/zh/1172' },
  { term: '食碗面反碗底', explain: '指忘恩負義。「食碗面」係食碗入面嘅飯，「反碗底」係拜祭先人時先會將碗反轉倒飯，所以暗指詛咒恩人。', cat: '粵語俚語由來', level: 2, src: 'https://www.ourchinastory.com/zh/1174' },
  { term: '刀仔鋸大樹', explain: '指以小博大。1970年代後期一齣電視劇嘅主題曲有「一把刀仔可以鋸大樹」嘅歌詞，令呢句話街知巷聞。', cat: '粵語俚語由來', level: 2, src: 'https://www.ourchinastory.com/zh/1155' },
  // ---------------------------------------------------------- 外語怪詞
  { term: '積読', explain: '日文詞語，指買咗書返嚟但一直冇睇，任由佢喺屋企越堆越高。', cat: '外語怪詞', level: 1, src: 'https://en.wikipedia.org/wiki/Tsundoku' },
  { term: '木漏れ日', explain: '日文詞語，指陽光穿過樹葉縫隙，喺地面或空氣中灑落嘅斑駁光影。', cat: '外語怪詞', level: 1, src: 'https://en.wiktionary.org/wiki/%E6%9C%A8%E6%BC%8F%E3%82%8C%E6%97%A5' },
  { term: '口寂しい', explain: '日文形容詞，指其實唔肚餓，但嘴巴悶悶地，忍唔住想食啲嘢。', cat: '外語怪詞', level: 2, src: 'https://en.wiktionary.org/wiki/%E3%81%8F%E3%81%A1%E3%81%95%E3%81%B3%E3%81%97%E3%81%84' },
  { term: '物の哀れ', explain: '江戶學者本居宣長提倡嘅文學概念，指見到事物短暫無常，心中湧起嘅淡淡感觸。', cat: '外語怪詞', level: 3, src: 'https://en.wikipedia.org/wiki/Mono_no_aware' },
  { term: '幽玄', explain: '日本中世藝術同能樂嘅審美觀，指含蓄、深奧、說不盡嘅餘韻之美。', cat: '外語怪詞', level: 2, src: 'https://en.wikipedia.org/wiki/Y%C5%ABgen' },
  { term: '微睡み', explain: '日文詞語，指半夢半醒、似睡未睡嘅輕輕淺眠狀態。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/%E3%81%BE%E3%81%A9%E3%82%8D%E3%81%BF' },
  { term: '木枯らし', explain: '日文詞語，指晚秋至初冬吹嚟、將樹葉吹散嘅冷北風，亦係冬天嚟臨嘅訊號。', cat: '外語怪詞', level: 2, src: 'https://ja.wikipedia.org/wiki/%E6%9C%A8%E6%9E%AF%E3%82%89%E3%81%97' },
  { term: '小春日和', explain: '日文詞語，指晚秋至初冬之間，天氣暖和得好似春天嘅晴朗日子。', cat: '外語怪詞', level: 2, src: 'https://en.wiktionary.org/wiki/%E5%B0%8F%E6%98%A5%E6%97%A5%E5%92%8C' },
  { term: '夕凪', explain: '日文詞語，指傍晚時海風同陸風交替，海邊一時風平浪靜、一絲風都冇嘅狀態。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/%E5%A4%95%E5%87%AA' },
  { term: '蝉時雨', explain: '日文詞語，形容好多蟬同時鳴叫，聲音好似驟雨咁傾瀉落嚟。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/%E8%9D%89%E6%99%82%E9%9B%A8' },
  { term: '夏バテ', explain: '日文詞語，指因為天氣太熱，食慾差同冇精神，身體疲倦嘅夏季不適。', cat: '外語怪詞', level: 1, src: 'https://ja.wikipedia.org/wiki/%E5%A4%8F%E3%83%90%E3%83%86' },
  { term: '逢魔が時', explain: '日文詞語，指黃昏時分；傳說呢個光暗交錯嘅時間，最易撞見妖怪。', cat: '外語怪詞', level: 2, src: 'https://ja.wikipedia.org/wiki/%E9%80%A2%E9%AD%94%E6%99%82' },
  { term: '一富士二鷹三茄子', explain: '日本諺語，指新年初夢夢到富士山、老鷹同茄子，係最吉利嘅三樣東西。', cat: '外語怪詞', level: 3, src: 'https://ja.wikipedia.org/wiki/%E4%B8%80%E5%AF%8C%E5%A3%AB%E4%BA%8C%E9%B7%B9%E4%B8%89%E8%8C%84%E5%AD%90' },
  { term: '付喪神', explain: '日本傳說，指用咗好耐（相傳過百年）嘅器物，會生出靈魂變成妖怪。', cat: '外語怪詞', level: 1, src: 'https://en.wikipedia.org/wiki/Tsukumogami' },
  { term: '座敷童子', explain: '日本東北地方傳說，指住喺屋入面、細路外形嘅精靈，據講有佢喺度家運會旺。', cat: '外語怪詞', level: 1, src: 'https://en.wikipedia.org/wiki/Zashiki-warashi' },
  { term: '天邪鬼', explain: '日本民間傳說中好鍾意同人作對嘅小鬼；今日亦指故意唱反調嘅人。', cat: '外語怪詞', level: 2, src: 'https://en.wikipedia.org/wiki/Amanojaku' },
  { term: '駄洒落', explain: '日本人愛講嘅諧音冷笑話，例如「布団が吹っ飛んだ」（棉被飛走咗）。', cat: '外語怪詞', level: 1, src: 'https://en.wiktionary.org/wiki/%E9%A7%84%E6%B4%92%E8%90%BD' },
  { term: '大喜利', explain: '日本綜藝節目常見嘅玩法，主持出題，參加者要即場用幽默方式作答。', cat: '外語怪詞', level: 1, src: 'https://ja.wikipedia.org/wiki/%E5%A4%A7%E5%96%9C%E5%88%A9' },
  { term: '梯子酒', explain: '日文詞語，指一晚之內轉幾間酒吧或居酒屋，每間只飲一兩杯。', cat: '外語怪詞', level: 2, src: 'https://ja.wikipedia.org/wiki/%E6%A2%AF%E5%AD%90%E9%85%92' },
  { term: '赤提灯', explain: '日本居酒屋門口常掛嘅紅燈籠，後來亦用嚟指平民風格嘅小居酒屋。', cat: '外語怪詞', level: 2, src: 'https://en.wiktionary.org/wiki/%E8%B5%A4%E6%8F%90%E7%81%AF' },
  { term: '箱推し', explain: '日文追星用語，指唔係只支持其中一個成員，而係成個組合或團體都支持。', cat: '外語怪詞', level: 2, src: 'https://en.wiktionary.org/wiki/%E3%81%AF%E3%81%93%E3%81%8A%E3%81%97' },
  { term: '沼', explain: '日文網絡用語，指迷上某樣嘢（例如動漫、偶像）迷到好似跌入泥沼，一入就好難爬返出嚟。', cat: '外語怪詞', level: 2, src: 'https://en.wiktionary.org/wiki/%E6%B2%BC' },
  { term: '蛙化現象', explain: '日文網絡用語，指本來好鍾意一個人，一知道對方都鍾意自己，就突然覺得反感。', cat: '外語怪詞', level: 2, src: 'https://ja.wikipedia.org/wiki/%E8%9B%99%E5%8C%96%E7%8F%BE%E8%B1%A1' },
  { term: '空耳', explain: '日文詞語，指將外語歌詞或其他聲音，聽成另一句意思完全唔同嘅日文。', cat: '外語怪詞', level: 2, src: 'https://en.wiktionary.org/wiki/%E7%A9%BA%E8%80%B3' },
  { term: '湯治', explain: '日本傳統做法，指留喺溫泉地方一段較長時間，用泡溫泉嚟調理身體。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/%E6%B9%AF%E6%B2%BB' },
  { term: '寝落ち', explain: '日文網絡用語，指傾住電話或睇住片，唔知唔覺就瞓著咗。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/%E5%AF%9D%E8%90%BD%E3%81%A1' },
  { term: '手持ち無沙汰', explain: '日文詞語，指手上冇嘢做，唔知點打發時間嘅尷尬感覺。', cat: '外語怪詞', level: 3, src: 'https://www.weblio.jp/content/%E6%89%8B%E6%8C%81%E3%81%A1%E7%84%A1%E6%B2%99%E6%B1%B0' },
  { term: '居留守', explain: '日文詞語，指明明喺屋企，卻扮冇人，唔應門口嘅訪客或推銷。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/%E5%B1%85%E7%95%99%E5%AE%88' },
  { term: 'ドヤ顔', explain: '日文網絡用語，指做完一件事之後，一臉「我好叻」嘅得意表情。', cat: '外語怪詞', level: 2, src: 'https://en.wiktionary.org/wiki/%E3%83%89%E3%83%A4%E9%A1%94' },
  { term: 'ダメ元', explain: '日文詞語，指反正唔成功都冇損失，所以抱住姑且一試嘅心態去做。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/%E9%A7%84%E7%9B%AE%E3%81%A7%E5%85%83%E3%80%85' },
  { term: '食い倒れ', explain: '日文詞語，指為咗食好嘢而食到傾家蕩產；常用嚟形容大阪人好識食。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/%E9%A3%9F%E3%81%84%E5%80%92%E3%82%8C' },
  { term: '縁側', explain: '日式木造房屋向庭園外伸出嘅一條木走廊，可以坐喺度乘涼、飲茶。', cat: '外語怪詞', level: 2, src: 'https://en.wikipedia.org/wiki/Engawa' },
  { term: '床の間', explain: '日式和室入面一個凹入或抬高嘅位置，用嚟掛畫同擺花。', cat: '外語怪詞', level: 2, src: 'https://en.wikipedia.org/wiki/Tokonoma' },
  { term: '五月病', explain: '日本社會現象，指新人入職或入學後約五月，開始提唔起勁、疲倦嘅情況。', cat: '外語怪詞', level: 2, src: 'https://en.wiktionary.org/wiki/%E4%BA%94%E6%9C%88%E7%97%85' },
  { term: '渋い', explain: '日文形容詞，指低調、樸素而耐看，又帶沉穩味道嘅美感。', cat: '外語怪詞', level: 2, src: 'https://en.wiktionary.org/wiki/%E6%B8%8B%E3%81%84' },
  { term: '粋', explain: '日本江戶時代流行嘅審美觀，指灑脫、利落、唔炫耀嘅品味。', cat: '外語怪詞', level: 2, src: 'https://en.wikipedia.org/wiki/Iki_(aesthetic_ideal)' },
  { term: '狐の嫁入り', explain: '日本民間說法，指一邊出太陽、一邊落雨嘅天氣，傳說係狐狸出嫁嘅日子。', cat: '外語怪詞', level: 2, src: 'https://en.wiktionary.org/wiki/%E7%8B%90%E3%81%AE%E5%AB%81%E5%85%A5%E3%82%8A' },
  { term: '暖簾に腕押し', explain: '日本諺語，字面係「用手臂推門簾」，比喻無論點出力都冇反應、冇效果。', cat: '外語怪詞', level: 3, src: 'https://www.weblio.jp/content/%E6%9A%96%E7%B0%BE%E3%81%AB%E8%85%95%E6%8A%BC%E3%81%97' },
  { term: '犬も歩けば棒に当たる', explain: '日本諺語，字面係「狗行路都會撞到棒」，原指多事多禍，今日亦解作肯行動就會撞到好運。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/%E7%8A%AC%E3%82%82%E6%AD%A9%E3%81%91%E3%81%B0%E6%A3%92%E3%81%AB%E5%BD%93%E3%81%9F%E3%82%8B' },
  { term: '無礼講', explain: '日文詞語，指宴會上暫時唔理職位高低同禮節，大家可以放鬆暢談嘅聚會。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/%E7%84%A1%E7%A4%BC%E8%AC%9B' },
  { term: '蚊帳の外', explain: '日文慣用語，字面係「喺蚊帳外面」，指被排除喺圈子外，冇份參與或唔知內情。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/%E8%9A%8A%E5%B8%B3%E3%81%AE%E5%A4%96' },
  { term: '馬が合う', explain: '日文慣用語，字面係「馬匹合拍」，指兩個人性格合得來、好夾。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/%E9%A6%AC%E3%81%8C%E5%90%88%E3%81%86' },
  { term: '飲みニケーション', explain: '日文混成詞，由「飲む」（飲酒）同「コミュニケーション」合成，指同事朋友藉飲酒增進感情。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/%E9%A3%B2%E3%81%BF%E3%83%8B%E3%82%B1%E3%83%BC%E3%82%B7%E3%83%A7%E3%83%B3' },
  { term: '甘え', explain: '日本精神分析學家土居健郎 1971 年提出嘅概念，指期望依賴對方、被對方包容寵愛嘅心理。', cat: '外語怪詞', level: 3, src: 'https://en.wikipedia.org/wiki/Amae' },
  { term: '間（ma）', explain: '日本美學概念，指事物之間嘅空白、停頓或距離，被視為同實物一樣有意義。', cat: '外語怪詞', level: 3, src: 'https://en.wikipedia.org/wiki/Ma_(negative_space)' },
  { term: '一反木綿', explain: '日本鹿兒島縣傳說嘅妖怪，外形係一幅長約十米、會喺半空飄動嘅布。', cat: '外語怪詞', level: 2, src: 'https://en.wikipedia.org/wiki/Ittan-momen' },
  { term: '小豆洗い', explain: '日本妖怪傳說，指喺河邊聽到好似洗紅豆嘅沙沙聲，但通常只聞其聲、唔見其人。', cat: '外語怪詞', level: 3, src: 'https://en.wikipedia.org/wiki/Azukiarai' },
  { term: 'lagom', explain: '瑞典語，指「唔多唔少、剛剛好」嘅適中程度，係瑞典人推崇嘅生活態度。', cat: '外語怪詞', level: 1, src: 'https://en.wikipedia.org/wiki/Lagom' },
  { term: 'fika', explain: '瑞典語，指放低手上嘅工作，同人一齊飲咖啡、食點心嘅休息時間。', cat: '外語怪詞', level: 1, src: 'https://en.wikipedia.org/wiki/Fika_(Sweden)' },
  { term: 'friluftsliv', explain: '挪威語，字面係「戶外生活」，指喺大自然入面活動、親近自然嘅生活方式。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/friluftsliv' },
  { term: 'smultronställe', explain: '瑞典語，字面係「野生士多啤梨生長之處」，指只屬於自己、令人開心嘅秘密好去處。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/smultronst%C3%A4lle' },
  { term: 'mångata', explain: '瑞典語，指月光倒映喺水面上，形成一條閃閃發光嘅光路。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/m%C3%A5ngata' },
  { term: 'gökotta', explain: '瑞典傳統，指春天大清早出門，帶住乾糧去郊外聽雀鳥啼叫，傳統上係等布穀鳥開聲。', cat: '外語怪詞', level: 3, src: 'https://sv.wikipedia.org/wiki/G%C3%B6kotta' },
  { term: 'sisu', explain: '芬蘭語，指面對困境時，展現出嘅堅毅、不輕易放棄嘅精神。', cat: '外語怪詞', level: 1, src: 'https://en.wikipedia.org/wiki/Sisu' },
  { term: 'kalsarikännit', explain: '芬蘭語，指淨係著住內褲，留喺屋企通常獨自一個飲到有啲醉，並冇打算出街。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/kalsarik%C3%A4nni' },
  { term: 'löyly', explain: '芬蘭桑拿嘅術語，指熱石淋上水之後升起嘅蒸氣同熱氣。', cat: '外語怪詞', level: 3, src: 'https://en.wikipedia.org/wiki/L%C3%B6yly' },
  { term: 'poronkusema', explain: '薩米人傳統嘅距離單位，指馴鹿未需要停低小便之前可以行嘅距離，約 7.5 公里。', cat: '外語怪詞', level: 3, src: 'https://en.wikipedia.org/wiki/Obsolete_Finnish_units_of_measurement' },
  { term: 'pyt', explain: '丹麥語，一個字就可以表達「算啦、冇所謂」，用嚟放低細小嘅挫折。', cat: '外語怪詞', level: 3, src: 'https://www.voguescandinavia.com/articles/pyt' },
  { term: 'dugnad', explain: '挪威語，指鄰里或社區成員一齊義務出力，做清潔、維修等公共事務。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/dugnad' },
  { term: 'gluggaveður', explain: '冰島語，指由窗口望出去天氣好靚，但行出街先發現冷到震嘅天氣。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/gluggave%C3%B0ur' },
  { term: 'niksen', explain: '荷蘭語，指刻意咩都唔做，淨係放空發呆，唔需要有任何目的。', cat: '外語怪詞', level: 2, src: 'https://en.wikipedia.org/wiki/Niksen' },
  { term: 'gezellig', explain: '荷蘭語，形容溫馨、舒服又熱鬧融洽嘅氣氛，好難用一個字翻譯。', cat: '外語怪詞', level: 2, src: 'https://en.wiktionary.org/wiki/gezellig' },
  { term: 'uitwaaien', explain: '荷蘭語，指喺風大嘅地方，例如海邊行下，用嚟令頭腦清醒。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/uitwaaien' },
  { term: 'utepils', explain: '挪威語，指喺戶外飲嘅啤酒，例如坐喺露天座位享受陽光嗰杯。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/utepils' },
  { term: 'tretår', explain: '瑞典語，指第三杯咖啡，即係同一個杯已經添咗兩次嘅嗰一杯。', cat: '外語怪詞', level: 3, src: 'https://sv.wiktionary.org/wiki/tret%C3%A5r' },
  { term: 'kaamos', explain: '芬蘭語，指北極圈內，太陽成日都唔出現嘅極夜時期。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/kaamos' },
  { term: 'hiraeth', explain: '威爾斯語，指對家鄉威爾斯、或對已失去事物嘅一種帶懷舊哀傷嘅深切思念。', cat: '外語怪詞', level: 2, src: 'https://en.wikipedia.org/wiki/Hiraeth' },
  { term: 'cwtch', explain: '威爾斯語，指溫暖嘅擁抱，亦可以指一個舒適安全、用嚟依偎嘅小角落。', cat: '外語怪詞', level: 2, src: 'https://en.wikipedia.org/wiki/Cwtch' },
  { term: 'craic', explain: '愛爾蘭用語，指好玩、熱鬧嘅氣氛同愉快嘅傾偈；「What\'s the craic?」即係問你近況點。', cat: '外語怪詞', level: 3, src: 'https://en.wikipedia.org/wiki/Craic' },
  { term: 'dreich', explain: '蘇格蘭語，形容天氣陰沉、潮濕又悶嘅日子。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/dreich' },
  { term: 'tartle', explain: '蘇格蘭語，指因為記唔起對方個名、或者一時認唔出人，而猶豫停頓嘅一刻。', cat: '外語怪詞', level: 3, src: 'https://www.omniglot.com/bloggle/?p=18394' },
  { term: 'fankle', explain: '蘇格蘭語，指線、電線或魚絲亂成一團，纏結難解嘅狀態。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/fankle' },
  { term: 'petrichor', explain: '英文詞語，指久旱之後落雨，泥土散發出嚟嘅獨特氣味。', cat: '外語怪詞', level: 1, src: 'https://en.wikipedia.org/wiki/Petrichor' },
  { term: 'defenestration', explain: '源自拉丁文「窗」，英文指將人或物件由窗口拋出去嘅行為。', cat: '外語怪詞', level: 2, src: 'https://en.wikipedia.org/wiki/Defenestration' },
  { term: 'sonder', explain: '由 John Koenig 創造嘅字，指突然意識到身邊每個路人，都有同自己一樣複雜豐富嘅人生。', cat: '外語怪詞', level: 2, src: 'https://en.wiktionary.org/wiki/sonder' },
  { term: 'vellichor', explain: '同樣係 John Koenig 創造嘅字，指舊書店嗰種帶點憂傷、又好迷人嘅獨特氣氛。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/vellichor' },
  { term: 'kenopsia', explain: '同樣係 John Koenig 創造嘅字，指原本應該好熱鬧嘅地方，變得空蕩蕩時嘅詭異感覺。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/kenopsia' },
  { term: 'limerence', explain: '心理學家 Dorothy Tennov 1979 年提出，指迷戀到極點、渴望對方都同樣回應嘅狀態。', cat: '外語怪詞', level: 2, src: 'https://en.wikipedia.org/wiki/Limerence' },
  { term: 'lethologica', explain: '英文詞語，指明明知道想講嗰個字，卻一時間點都記唔起嘅現象。', cat: '外語怪詞', level: 2, src: 'https://en.wiktionary.org/wiki/lethologica' },
  { term: 'ultracrepidarian', explain: '英文詞語，指對自己唔懂嘅嘢，都要亂發表意見嘅人。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/ultracrepidarian' },
  { term: 'floccinaucinihilipilification', explain: '英文詞語，指將某樣嘢看成毫無價值嘅習慣；常被視為英文最長嘅日常用字（29 個字母）。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/floccinaucinihilipilification' },
  { term: 'apricity', explain: '英文古語，指冬日陽光照落身上嗰種溫暖感覺。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/apricity' },
  { term: 'sesquipedalian', explain: '英文詞語，形容人或文章喜歡用又長又深嘅字；字面意思係「一尺半長」。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/sesquipedalian' },
  { term: 'mondegreen', explain: '美國作家 Sylvia Wright 1954 年創造嘅字，指將歌詞或詩句聽錯，變成另一句有意思嘅說話。', cat: '外語怪詞', level: 2, src: 'https://en.wikipedia.org/wiki/Mondegreen' },
  { term: 'Fernweh', explain: '德語，指對遠方嘅渴望、好想去旅行，常被形容為同思鄉（Heimweh）相反嘅感覺。', cat: '外語怪詞', level: 1, src: 'https://en.wiktionary.org/wiki/Fernweh' },
  { term: 'Kummerspeck', explain: '德語，字面係「悲傷嘅煙肉」，指因為情緒低落或壓力大而食多咗，長出嚟嘅肥肉。', cat: '外語怪詞', level: 2, src: 'https://en.wiktionary.org/wiki/Kummerspeck' },
  { term: 'Torschlusspanik', explain: '德語，字面係「閘門快閂嘅恐慌」，指擔心時間唔夠、機會就快冇晒嘅焦慮。', cat: '外語怪詞', level: 2, src: 'https://en.wiktionary.org/wiki/Torschlusspanik' },
  { term: 'Weltschmerz', explain: '德語，指覺得現實世界同理想差距太大，而生嘅憂鬱同厭世感。', cat: '外語怪詞', level: 2, src: 'https://en.wikipedia.org/wiki/Weltschmerz' },
  { term: 'Fingerspitzengefühl', explain: '德語，字面係「指尖感覺」，指處理事情時嘅敏銳觸覺同拿捏分寸嘅本事。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/Fingerspitzengef%C3%BChl' },
  { term: 'Treppenwitz', explain: '德語，字面係「樓梯笑話」，今日多指令人啼笑皆非嘅諷刺巧合；舊義指事後先諗到嘅妙答。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/Treppenwitz' },
  { term: 'Kopfkino', explain: '德語，字面係「腦入面嘅戲院」，指腦海自動播放想像出嚟嘅畫面或劇情。', cat: '外語怪詞', level: 2, src: 'https://en.wiktionary.org/wiki/Kopfkino' },
  { term: 'Ohrwurm', explain: '德語，字面係「耳蟲」，指一首歌鑽入腦入面，成日揮之不去。', cat: '外語怪詞', level: 1, src: 'https://en.wikipedia.org/wiki/Earworm' },
  { term: 'Fremdschämen', explain: '德語，指睇到別人出醜或做錯嘢，自己都替佢覺得尷尬。', cat: '外語怪詞', level: 2, src: 'https://en.wiktionary.org/wiki/fremdsch%C3%A4men' },
  { term: 'innerer Schweinehund', explain: '德語，字面係「內心嘅豬狗」，指你心入面叫你懶惰、唔想行動嘅惰性。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/innerer_Schweinehund' },
  { term: 'verschlimmbessern', explain: '德語，指本來想改善，結果卻越改越差。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/verschlimmbessern' },
  { term: 'Dreikäsehoch', explain: '德語，字面係「三個芝士咁高」，用嚟戲稱個子細細嘅小朋友。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/Dreik%C3%A4sehoch' },
  { term: 'Eselsbrücke', explain: '德語，字面係「驢子橋」，指幫手記嘢嘅口訣或記憶小竅門。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/Eselsbr%C3%BCcke' },
  { term: 'Schnapsidee', explain: '德語，字面係「烈酒主意」，指乍聽好似好妙、細諗先發現好蠢嘅主意。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/Schnapsidee' },
  { term: 'sturmfrei', explain: '德語口語，字面係「冇風暴嘅」，指父母或室友唔喺度，自己獨佔成間屋嘅狀態。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/sturmfrei' },
  { term: 'saudade', explain: '葡萄牙語，指對已經離開或遠方嘅人與事物，帶點甜美又帶點傷感嘅思念。', cat: '外語怪詞', level: 1, src: 'https://en.wikipedia.org/wiki/Saudade' },
  { term: 'cafuné', explain: '巴西葡萄牙語，指溫柔咁撫摸所愛之人嘅頭髮同頭。', cat: '外語怪詞', level: 2, src: 'https://en.wiktionary.org/wiki/cafun%C3%A9' },
  { term: 'desenrascanço', explain: '葡萄牙語，指喺冇準備、資源不足嘅情況下，臨場想辦法搞掂問題嘅本事。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/desenrascan%C3%A7o' },
  { term: 'sobremesa', explain: '西班牙語，指食完飯之後，仍然坐喺枱邊慢慢傾偈嘅悠閒時光。', cat: '外語怪詞', level: 2, src: 'https://en.wiktionary.org/wiki/sobremesa' },
  { term: 'duende', explain: '西班牙語，指一種強烈、真摯投入嘅情感狀態，尤其見於弗拉明高表演，由詩人洛爾迦推廣。', cat: '外語怪詞', level: 2, src: 'https://en.wikipedia.org/wiki/Duende_(art)' },
  { term: 'querencia', explain: '西班牙語，本來指鬥牛場上牛感到最安全、會返去企定嘅位置，引申指令人感到安心自在嘅地方。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/querencia' },
  { term: 'tertulia', explain: '西班牙語，指一班人定期聚埋傾偈、討論嘅社交聚會，傳統上多圍繞文學、藝術同時事。', cat: '外語怪詞', level: 3, src: 'https://en.wikipedia.org/wiki/Tertulia' },
  { term: 'culaccino', explain: '意大利語，指凍杯放喺枱面之後，杯底留低嘅水印。', cat: '外語怪詞', level: 2, src: 'https://en.wiktionary.org/wiki/culaccino' },
  { term: 'abbiocco', explain: '意大利語，指食完豐富嘅一餐之後，令人想瞓覺嘅睏倦感覺。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/abbiocco' },
  { term: 'sprezzatura', explain: '意大利語，指做事舉重若輕、毫不費力嘅優雅，好似完全唔使花心思。', cat: '外語怪詞', level: 3, src: 'https://en.wikipedia.org/wiki/Sprezzatura' },
  { term: 'passeggiata', explain: '意大利語，指傍晚時分，街坊出街慢慢散步、見面傾偈嘅傳統。', cat: '外語怪詞', level: 3, src: 'https://www.tourissimo.travel/blog/what-is-la-passeggiata' },
  { term: 'pantofolaio', explain: '意大利語，指鍾意著住拖鞋留喺屋企，唔愛出街嘅人。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/pantofolaio' },
  { term: 'dépaysement', explain: '法語，指去到陌生環境，所產生嘅新鮮、抽離，又有啲迷失嘅感覺。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/d%C3%A9paysement' },
  { term: 'flâneur', explain: '法語，指冇目的地喺城市街頭漫步、觀察市井生活嘅人。', cat: '外語怪詞', level: 1, src: 'https://en.wikipedia.org/wiki/Fl%C3%A2neur' },
  { term: 'bouquiniste', explain: '法語，指喺巴黎塞納河邊擺攤賣舊書嘅書販。', cat: '外語怪詞', level: 3, src: 'https://en.wikipedia.org/wiki/Bouquinistes' },
  { term: 'jolie laide', explain: '法語，字面係「靚醜」，指五官未必標準，但就獨具魅力嘅人。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/jolie_laide' },
  { term: 'bella figura', explain: '意大利語，字面係「靚形象」，指重視外表同儀態，要喺人前留下好印象嘅處世態度。', cat: '外語怪詞', level: 2, src: 'https://en.wiktionary.org/wiki/bella_figura' },
  { term: 'métro, boulot, dodo', explain: '法語順口溜，指搭地鐵、返工、瞓覺，日復一日千篇一律嘅都市打工生活。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/m%C3%A9tro%2C_boulot%2C_dodo' },
  { term: 'campanilismo', explain: '意大利語，源自「鐘樓」（家鄉嘅象徵），指一心偏愛自己家鄉、地域觀念好重嘅心態。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/campanilismo' },
  { term: 'nefelibata', explain: '葡萄牙語同西班牙語，字面源自希臘文「行喺雲上面嘅人」，指成日活喺幻想入面嘅白日夢者。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/nefelibata' },
  { term: 'pochemuchka', explain: '俄語，指好奇心極重、成日問「點解」問個不停嘅人，多數係小朋友。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/%D0%BF%D0%BE%D1%87%D0%B5%D0%BC%D1%83%D1%87%D0%BA%D0%B0' },
  { term: 'prozvonit', explain: '捷克語，指打電話俾人但響一兩聲就收線，等對方打返俾自己。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/prozvonit' },
  { term: 'balagan', explain: '希伯來語，指一團糟、亂成一片嘅局面。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/%D7%91%D7%9C%D7%92%D7%9F' },
  { term: 'fjaka', explain: '克羅地亞達爾馬提亞海岸地區嘅詞語，指午後懶洋洋、乜都唔想做嘅甜蜜倦意。', cat: '外語怪詞', level: 3, src: 'https://www.croatiaweek.com/the-ultimate-dalmatian-state-of-fjaka/' },
  { term: 'kvell', explain: '意第緒語，指為子女或後輩嘅成就而感到驕傲、開心到不得了。', cat: '外語怪詞', level: 3, src: 'https://www.jta.org/2020/02/12/culture/using-this-yiddish-word-is-an-art-that-anyone-can-master' },
  { term: 'wasta', explain: '阿拉伯語地區嘅詞語，指靠人情同關係，幫人辦成事情嘅影響力。', cat: '外語怪詞', level: 3, src: 'https://en.wikipedia.org/wiki/Wasta' },
  { term: 'ta\'arof', explain: '波斯語，指伊朗人之間互相推讓、過分客套嘅禮儀，例如明明想要都先拒絕。', cat: '外語怪詞', level: 3, src: 'https://en.wikipedia.org/wiki/Taarof' },
  { term: 'yakamoz', explain: '土耳其語，指海面上因為浮游生物或者月光，閃閃發亮嘅光。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/yakamoz' },
  { term: 'meraki', explain: '希臘語，指帶住熱情同心思，全心全意投入去做一件事。', cat: '外語怪詞', level: 2, src: 'https://en.wiktionary.org/wiki/%CE%BC%CE%B5%CF%81%CE%AC%CE%BA%CE%B9' },
  { term: 'kefi', explain: '希臘語，指精神高昂、興致勃勃嘅狀態，多喺朋友聚會、唱歌跳舞時出現。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/kefi' },
  { term: '눈치（nunchi）', explain: '韓語，指睇人面色、察言觀色嘅能力，喺韓國社交好重要。', cat: '外語怪詞', level: 1, src: 'https://en.wikipedia.org/wiki/Nunchi' },
  { term: '찜질방（jjimjilbang）', explain: '韓國嘅大型公眾桑拿澡堂，設有多種桑拿房同休息空間，部分容許客人留低過夜。', cat: '外語怪詞', level: 1, src: 'https://en.wikipedia.org/wiki/Jjimjilbang' },
  { term: '혼족（honjok）', explain: '韓語，指習慣獨自食飯、旅行、生活嘅人。', cat: '外語怪詞', level: 2, src: 'https://en.wikipedia.org/wiki/Honjok' },
  { term: '애교（aegyo）', explain: '韓語，指用可愛嘅聲線同表情撒嬌嘅行為。', cat: '外語怪詞', level: 1, src: 'https://en.wikipedia.org/wiki/Aegyo' },
  { term: '썸（sseom）', explain: '韓語，指雙方互有好感，但仲未正式拍拖嘅曖昧階段。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/%EC%8D%B8' },
  { term: 'เกรงใจ（greng jai）', explain: '泰語，指因為怕麻煩、唔想令人為難，所以唔好意思開口求人或拒絕人。', cat: '外語怪詞', level: 3, src: 'https://www.thethailandlife.com/kreng-jai' },
  { term: 'สนุก（sanuk）', explain: '泰語，意思係「好玩、開心」，亦係泰國文化入面強調做事要搵到樂趣嘅態度。', cat: '外語怪詞', level: 2, src: 'https://en.wiktionary.org/wiki/%E0%B8%AA%E0%B8%99%E0%B8%B8%E0%B8%81' },
  { term: 'jam karet', explain: '印尼語，字面係「橡筋時間」，指時間可以伸縮、遲到係平常事嘅觀念。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/jam_karet' },
  { term: 'mudik', explain: '印尼語，指節日前後，大批人返鄉探親嘅大遷徙。', cat: '外語怪詞', level: 3, src: 'https://en.wikipedia.org/wiki/Mudik' },
  { term: 'pasalubong', explain: '菲律賓語，指旅行或出差返嚟時，帶俾親友嘅手信。', cat: '外語怪詞', level: 2, src: 'https://en.wikipedia.org/wiki/Pasalubong' },
  { term: 'gigil', explain: '菲律賓語，指見到好可愛嘅人或事物，忍唔住想捏實、攬實佢嘅衝動。', cat: '外語怪詞', level: 2, src: 'https://en.wiktionary.org/wiki/gigil' },
  { term: 'kilig', explain: '菲律賓語，指因為浪漫而心跳加速、全身起雞皮嘅甜蜜興奮感。', cat: '外語怪詞', level: 2, src: 'https://en.wiktionary.org/wiki/kilig' },
  { term: 'bayanihan', explain: '菲律賓語，指街坊互相幫手、合力完成一件事嘅精神，經典畫面係眾人合力抬起成間屋搬走。', cat: '外語怪詞', level: 3, src: 'https://en.wikipedia.org/wiki/Communal_work' },
  { term: 'jugaad', explain: '印度語詞彙，指用有限資源，臨場想出嘅創意應急辦法。', cat: '外語怪詞', level: 3, src: 'https://en.wikipedia.org/wiki/Jugaad' },
  { term: 'jayus', explain: '印尼語俚語，指講得好冷、一啲都唔好笑嘅笑話。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/jayus' },
  { term: 'ubuntu', explain: '源自南部非洲嘅哲學，意思係「我之所以係我，因為有你哋」，強調人與人相連。', cat: '外語怪詞', level: 1, src: 'https://en.wikipedia.org/wiki/Ubuntu_philosophy' },
  { term: 'sawubona', explain: '祖魯語嘅問候語，源自 siyakubona，字面意思係「我哋睇見你」。', cat: '外語怪詞', level: 2, src: 'https://en.wiktionary.org/wiki/sawubona' },
  { term: 'ilunga', explain: '剛果 Tshiluba 語，指肯原諒同容忍別人第一次、第二次，但絕不容許第三次嘅人；曾被票選為最難翻譯嘅詞。', cat: '外語怪詞', level: 3, src: 'https://www.todaytranslations.com/news/most-untranslatable-word/' },
  { term: 'kuleana', explain: '夏威夷語，指同某些權利並行嘅責任或義務。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/kuleana' },
  { term: 'iktsuarpok', explain: '因紐特語，指期待有人到訪，不斷行出門口張望對方到咗未。', cat: '外語怪詞', level: 3, src: 'https://en.wiktionary.org/wiki/iktsuarpok' },
  { term: 'mamihlapinatapai', explain: '火地島原住民亞甘語，指兩個人四目交投，各自希望對方先開口或先行動嘅微妙眼神。', cat: '外語怪詞', level: 2, src: 'https://en.wikipedia.org/wiki/Mamihlapinatapai' },
  { term: 'プリクラ（purikura）', explain: '日本大頭貼，名字係 Print Club（プリント倶楽部）嘅縮寫，1995年由 Atlus 同 Sega 推出。', cat: '外語怪詞', level: 2, src: 'https://en.wikipedia.org/wiki/Purikura' },
  // ---------------------------------------------------------- 天文與太空
  { term: '柯伊伯帶', explain: '海王星軌道外嘅冰質小天體環帶，冥王星係其中成員之一。', cat: '天文與太空', level: 2, src: 'https://en.wikipedia.org/wiki/Kuiper_belt' },
  { term: '奧爾特雲', explain: '理論上包圍太陽系最外圍、由冰質天體組成嘅巨大球殼，被認為係長週期彗星嘅來源。', cat: '天文與太空', level: 2, src: 'https://en.wikipedia.org/wiki/Oort_cloud' },
  { term: '拉格朗日點', explain: '兩個大天體嘅引力同公轉效應互相平衡嘅位置，細物體喺度可以大致保持相對位置，韋伯望遠鏡就繞住日地L2點運行。', cat: '天文與太空', level: 2, src: 'https://en.wikipedia.org/wiki/Lagrange_point' },
  { term: '洛希極限', explain: '只靠自身引力維繫嘅天體，靠近大天體到呢個距離之內，就會被潮汐力撕碎。', cat: '天文與太空', level: 3, src: 'https://en.wikipedia.org/wiki/Roche_limit' },
  { term: '日球層頂', explain: '太陽風同星際介質之間嘅邊界，航行者1號喺2012年穿越咗呢個邊界。', cat: '天文與太空', level: 3, src: 'https://en.wikipedia.org/wiki/Heliosphere' },
  { term: '日行跡', explain: '每日同一時間、同一地點拍攝太陽位置，一年下來連成嘅8字形軌跡。', cat: '天文與太空', level: 3, src: 'https://en.wikipedia.org/wiki/Analemma' },
  { term: '均時差', explain: '日晷顯示嘅時間同時鐘時間之間嘅差，一年之中最多可以差約16分鐘。', cat: '天文與太空', level: 3, src: 'https://en.wikipedia.org/wiki/Equation_of_time' },
  { term: '黃道光', explain: '日出前或日落後見到、沿黃道向上伸展嘅錐形微光，由行星際塵埃反射陽光而成。', cat: '天文與太空', level: 3, src: 'https://en.wikipedia.org/wiki/Zodiacal_light' },
  { term: '地球反照', explain: '新月前後月亮暗面隱約發光，係因為地球反射嘅陽光照亮咗佢，達文西亦曾嘗試解釋呢個現象。', cat: '天文與太空', level: 2, src: 'https://en.wikipedia.org/wiki/Earthlight' },
  { term: '金星凌日', explain: '金星行過太陽表面前方，成對出現，上一次係2012年，下一次要等到2117年。', cat: '天文與太空', level: 1, src: 'https://en.wikipedia.org/wiki/Transit_of_Venus' },
  { term: '暗淡藍點', explain: '1990年航行者1號由約60億公里外回望拍到嘅地球相片，地球只係一粒細小光點。', cat: '天文與太空', level: 1, src: 'https://en.wikipedia.org/wiki/Pale_Blue_Dot' },
  { term: '磁星', explain: '磁場極端強嘅中子星，強度約為地球磁場嘅萬億倍或以上。', cat: '天文與太空', level: 2, src: 'https://en.wikipedia.org/wiki/Magnetar' },
  { term: '脈衝星', explain: '高速自轉嘅中子星，會定時向地球發出無線電脈衝，首次發現時曾被戲稱為「小綠人」訊號。', cat: '天文與太空', level: 2, src: 'https://en.wikipedia.org/wiki/Pulsar' },
  { term: '千新星', explain: '兩粒中子星相撞產生嘅爆發，被認為係金同鉑等重元素嘅重要來源之一。', cat: '天文與太空', level: 3, src: 'https://en.wikipedia.org/wiki/Kilonova' },
  { term: '耀變體', explain: '噴流剛好正對地球方向嘅活躍星系核，亮度變化極之劇烈。', cat: '天文與太空', level: 3, src: 'https://en.wikipedia.org/wiki/Blazar' },
  { term: '類星體', explain: '星系中心嘅超大質量黑洞吞噬物質時發出極強光芒嘅天體，亮度可以超過整個星系。', cat: '天文與太空', level: 2, src: 'https://en.wikipedia.org/wiki/Quasar' },
  { term: '快速射電暴', explain: '來自遙遠星系、只持續幾毫秒但能量極大嘅無線電訊號，成因仍未完全清楚。', cat: '天文與太空', level: 3, src: 'https://en.wikipedia.org/wiki/Fast_radio_burst' },
  { term: '伽瑪射線暴', explain: '宇宙中最猛烈嘅爆發之一，典型嘅一次喺幾秒內釋放嘅能量，等如太陽一百億年壽命嘅總輸出。', cat: '天文與太空', level: 2, src: 'https://en.wikipedia.org/wiki/Gamma-ray_burst' },
  { term: 'Wow! 訊號', explain: '1977年大耳朵電波望遠鏡收到一段來源不明嘅窄頻訊號，研究員喺列印紙上圈起並寫低「Wow!」。', cat: '天文與太空', level: 3, src: 'https://en.wikipedia.org/wiki/Wow!_signal' },
  { term: '阿雷西博訊息', explain: '1974年向球狀星團M13發送嘅二進制無線電訊息，內含人類同太陽系嘅簡單圖像。', cat: '天文與太空', level: 3, src: 'https://en.wikipedia.org/wiki/Arecibo_message' },
  { term: '航行者金唱片', explain: '隨航行者號升空嘅鍍金唱片，載有55種語言嘅問候，其中包括廣東話。', cat: '天文與太空', level: 2, src: 'https://science.nasa.gov/mission/voyager/golden-record-contents/greetings/' },
  { term: '錢德拉塞卡極限', explain: '白矮星可以維持穩定嘅最大質量，約為太陽質量嘅1.4倍。', cat: '天文與太空', level: 3, src: 'https://en.wikipedia.org/wiki/Chandrasekhar_limit' },
  { term: '史瓦西半徑', explain: '任何質量壓縮到呢個半徑之內就會變成黑洞，地球嘅史瓦西半徑只有約9毫米。', cat: '天文與太空', level: 3, src: 'https://en.wikipedia.org/wiki/Schwarzschild_radius' },
  { term: '奧伯斯悖論', explain: '一個疑問：如果宇宙無限大、永恒不變而且恒星無數，夜空理應處處光亮，但現實中夜空係黑嘅。', cat: '天文與太空', level: 3, src: 'https://en.wikipedia.org/wiki/Olbers%27_paradox' },
  { term: '巨引源', explain: '引力異常強嘅區域，將包括銀河系喺內嘅大量星系向同一方向拉去。', cat: '天文與太空', level: 3, src: 'https://en.wikipedia.org/wiki/Great_Attractor' },
  { term: '拉尼亞凱亞超星系團', explain: '包含銀河系嘅超星系團，夏威夷語名字意思係「無法估量嘅天堂」。', cat: '天文與太空', level: 3, src: 'https://en.wikipedia.org/wiki/Laniakea_Supercluster' },
  { term: '牧夫座空洞', explain: '直徑約3至4億光年嘅巨大空洞，入面嘅星系數量遠少過正常區域。', cat: '天文與太空', level: 3, src: 'https://en.wikipedia.org/wiki/Bo%C3%B6tes_Void' },
  { term: '宇宙微波背景', explain: '大爆炸遺留嘅微弱輻射，舊式模擬電視雪花畫面入面有一小部分就係佢。', cat: '天文與太空', level: 2, src: 'https://en.wikipedia.org/wiki/Cosmic_microwave_background' },
  { term: '造父變星', explain: '亮度會有規律咁漲落嘅恒星，周期越長本身越光，可以用嚟量度星系距離。', cat: '天文與太空', level: 2, src: 'https://en.wikipedia.org/wiki/Cepheid_variable' },
  { term: '秒差距', explain: '天文距離單位，約等於3.26光年。', cat: '天文與太空', level: 2, src: 'https://en.wikipedia.org/wiki/Parsec' },
  { term: '天平動', explain: '月亮因為軌道同自轉嘅微小搖擺，令我哋喺地球上睇到嘅月面多過一半，約59%。', cat: '天文與太空', level: 3, src: 'https://en.wikipedia.org/wiki/Libration' },
  { term: '潮汐鎖定', explain: '天體自轉一圈嘅時間同公轉一圈相同，所以永遠用同一面對住中心天體，例如月亮。', cat: '天文與太空', level: 1, src: 'https://en.wikipedia.org/wiki/Tidal_locking' },
  { term: '收穫月', explain: '最接近秋分嘅滿月，嗰幾晚月亮升起嘅時間每日只遲少少，所以月光連續幾晚都好早出現。', cat: '天文與太空', level: 2, src: 'https://en.wikipedia.org/wiki/Full_moon' },
  { term: '月亮錯覺', explain: '月亮喺近地平線時睇落比高掛天空時大，但用相機量度大小其實一樣。', cat: '天文與太空', level: 1, src: 'https://en.wikipedia.org/wiki/Moon_illusion' },
  { term: '綠閃光', explain: '日出或日落一刻，太陽邊緣偶爾閃現一抹綠光，係大氣折射同散射造成。', cat: '天文與太空', level: 2, src: 'https://en.wikipedia.org/wiki/Green_flash' },
  { term: '卡門線', explain: '通常被視為大氣層同太空分界嘅高度，位於海拔100公里。', cat: '天文與太空', level: 2, src: 'https://en.wikipedia.org/wiki/K%C3%A1rm%C3%A1n_line' },
  { term: '引力彈弓', explain: '太空船飛近行星，借行星嘅引力同公轉動能加速或者轉向，可以慳燃料。', cat: '天文與太空', level: 2, src: 'https://en.wikipedia.org/wiki/Gravity_assist' },
  { term: '霍曼轉移軌道', explain: '兩條圓形軌道之間通常最慳燃料嘅雙脈衝轉移方法，用一條橢圓軌道連接兩者。', cat: '天文與太空', level: 3, src: 'https://en.wikipedia.org/wiki/Hohmann_transfer_orbit' },
  { term: '凱斯勒效應', explain: '一個假設情景：軌道上嘅太空垃圾密度高到互相碰撞，產生更多碎片，引發連鎖反應。', cat: '天文與太空', level: 3, src: 'https://en.wikipedia.org/wiki/Kessler_syndrome' },
  { term: '總觀效應', explain: '太空人由太空望返地球，對地球同人類產生強烈敬畏同一體感嘅心理體驗。', cat: '天文與太空', level: 3, src: 'https://en.wikipedia.org/wiki/Overview_effect' },
  { term: '地出', explain: '1968年阿波羅8號太空人喺繞月軌道拍到地球由月球地平線上升嘅相片。', cat: '天文與太空', level: 2, src: 'https://en.wikipedia.org/wiki/Earthrise' },
  { term: '月震', explain: '月球上發生嘅地震，阿波羅任務留低嘅地震儀曾偵測到，部分同地球嘅潮汐力有關。', cat: '天文與太空', level: 2, src: 'https://en.wikipedia.org/wiki/Lunar_seismology' },
  { term: '質量瘤', explain: '月球某啲區域質量特別集中，會拖扯繞月衛星，令軌道逐漸偏離。', cat: '天文與太空', level: 3, src: 'https://en.wikipedia.org/wiki/Mass_concentration_(astronomy)' },
  { term: '鑽石雨', explain: '理論推測天王星同海王星內部壓力極高，足以將碳壓成鑽石並向下沉。', cat: '天文與太空', level: 3, src: 'https://en.wikipedia.org/wiki/Extraterrestrial_diamonds' },
  { term: '土衛二', explain: '土星嘅衛星，南極噴出冰粒同水汽，探測器證實冰層下面有液態水海洋。', cat: '天文與太空', level: 2, src: 'https://en.wikipedia.org/wiki/Enceladus' },
  { term: '海衛一', explain: '海王星最大嘅衛星，公轉方向同海王星自轉相反，相信係被俘獲嘅柯伊伯帶天體。', cat: '天文與太空', level: 3, src: 'https://en.wikipedia.org/wiki/Triton_(moon)' },
  { term: '創生之柱', explain: '老鷹星雲入面一組由氣體同塵埃構成嘅柱狀結構，係哈勃望遠鏡最著名嘅相之一。', cat: '天文與太空', level: 1, src: 'https://en.wikipedia.org/wiki/Pillars_of_Creation' },
  { term: '蟹狀星雲', explain: '1054年超新星爆發嘅遺跡，當時中國天文學家將呢顆星記錄為「客星」。', cat: '天文與太空', level: 1, src: 'https://en.wikipedia.org/wiki/Crab_Nebula' },
  { term: '參宿四', explain: '獵戶座嘅紅超巨星，預期將來會以超新星爆發結束一生。', cat: '天文與太空', level: 1, src: 'https://en.wikipedia.org/wiki/Betelgeuse' },
  { term: '塔比星', explain: '亮度曾出現不規則大幅下跌嘅恒星，一度引起外星巨型建築嘅猜測，後來多數研究認為係塵埃。', cat: '天文與太空', level: 3, src: 'https://en.wikipedia.org/wiki/Tabby%27s_Star' },
  { term: '奧陌陌', explain: '2017年發現、首個被確認飛經太陽系嘅星際天體，夏威夷語名字意思係「遠方嚟嘅先行信使」。', cat: '天文與太空', level: 2, src: 'https://en.wikipedia.org/wiki/1I/%CA%BBOumuamua' },
  { term: '賽德娜', explain: '太陽系邊緣一個細小嘅天體，一般被視為矮行星，繞太陽一周要約一萬一千四百年。', cat: '天文與太空', level: 3, src: 'https://en.wikipedia.org/wiki/Sedna_(dwarf_planet)' },
  { term: '穀神星', explain: '火星同木星之間小行星帶入面最大嘅天體，屬於矮行星。', cat: '天文與太空', level: 2, src: 'https://en.wikipedia.org/wiki/Ceres_(dwarf_planet)' },
  { term: '玻隕石', explain: '隕石撞擊地球時，熔融嘅地球岩石噴上半空冷卻而成嘅天然玻璃。', cat: '天文與太空', level: 3, src: 'https://en.wikipedia.org/wiki/Tektite' },
  { term: '沙羅週期', explain: '日食同月食大約每隔18年11日會以相似形式重複出現。', cat: '天文與太空', level: 3, src: 'https://en.wikipedia.org/wiki/Saros_(astronomy)' },
  { term: '貝利珠', explain: '日全食前後，陽光穿過月球邊緣嘅山谷，變成一串發亮嘅珠子。', cat: '天文與太空', level: 3, src: 'https://en.wikipedia.org/wiki/Baily%27s_beads' },
  { term: '日冕加熱問題', explain: '日冕溫度高達百萬度以上，遠高過太陽表面嘅約五千多度，原因至今仍未完全弄清楚。', cat: '天文與太空', level: 3, src: 'https://en.wikipedia.org/wiki/Solar_corona' },
  { term: '蒙德極小期', explain: '約1645至1715年間太陽黑子極少出現嘅時期，同歐洲嘅小冰河期大致重疊。', cat: '天文與太空', level: 3, src: 'https://en.wikipedia.org/wiki/Maunder_Minimum' },
  { term: 'STEVE', explain: '一條紫色同綠色嘅天空光帶，名稱由業餘攝影師借自動畫《Over the Hedge》入面一堵一夜之間出現嘅樹籬。', cat: '天文與太空', level: 3, src: 'https://en.wikipedia.org/wiki/STEVE' },
  { term: '貝爾卡與斯特列爾卡', explain: '1960年隨蘇聯衛星升空嘅兩隻狗，環繞地球一日後安全返回地面。', cat: '天文與太空', level: 3, src: 'https://en.wikipedia.org/wiki/Belka_and_Strelka' },
  { term: '月塵', explain: '月球表面嘅細塵又尖又黏，好多阿波羅太空人帶返艙內後，都形容佢嘅氣味似燒完嘅火藥。', cat: '天文與太空', level: 2, src: 'https://en.wikipedia.org/wiki/Lunar_regolith' },
  { term: '穹頂艙', explain: '國際太空站上有七扇窗嘅觀景模組，太空人可以直接望到地球。', cat: '天文與太空', level: 3, src: 'https://en.wikipedia.org/wiki/Cupola_(ISS_module)' },
  { term: '隼鳥2號', explain: '日本探測器，2020年從小行星龍宮帶回樣本，樣本入面驗出20幾種胺基酸。', cat: '天文與太空', level: 2, src: 'https://www.space.com/asteroid-ryugu-samples-analysis-hyabusa2' },
  { term: '輝夜姬號', explain: '日本2007年發射嘅月球探測器，用高清電視攝影機拍到地球由月球地平線升起嘅片段。', cat: '天文與太空', level: 3, src: 'https://global.jaxa.jp/press/2008/04/20080411_kaguya_e.html' },
  { term: '希望號實驗艙', explain: '國際太空站上日本嘅實驗艙，以體積計係站上最大嘅單一加壓艙段。', cat: '天文與太空', level: 3, src: 'https://en.wikipedia.org/wiki/Kib%C5%8D_(ISS_module)' },
  { term: 'Milkomeda', explain: '假如銀河系同仙女座星系相撞合併，新星系嘅暱稱；舊預測約45億年後，2025年新研究話百億年內只有約一半機會。', cat: '天文與太空', level: 3, src: 'https://en.wikipedia.org/wiki/Andromeda%E2%80%93Milky_Way_collision' },
  { term: '銀河年', explain: '太陽系環繞銀河系中心公轉一周所需嘅時間，約為2億幾年。', cat: '天文與太空', level: 3, src: 'https://en.wikipedia.org/wiki/Galactic_year' },
  { term: '戴森球', explain: '一個假想嘅巨型結構，將整粒恒星包住，以收集佢發出嘅全部能量。', cat: '天文與太空', level: 1, src: 'https://en.wikipedia.org/wiki/Dyson_sphere' },
  { term: '卡爾達肖夫指數', explain: '以能源使用量衡量文明發展程度嘅假想等級，一級用盡行星能源，三級用盡整個星系。', cat: '天文與太空', level: 3, src: 'https://en.wikipedia.org/wiki/Kardashev_scale' },
  { term: '德雷克方程', explain: '估算銀河系內可通訊外星文明數量嘅公式，但好多參數至今仍然未知。', cat: '天文與太空', level: 2, src: 'https://en.wikipedia.org/wiki/Drake_equation' },
  { term: '大過濾器', explain: '一個假說：生命由出現到發展成星際文明之間有道極難跨過嘅關卡，或者可以解釋點解未見到外星人。', cat: '天文與太空', level: 2, src: 'https://en.wikipedia.org/wiki/Great_Filter' },
  { term: '動物園假說', explain: '假說指外星文明其實存在，但刻意避免接觸人類，好似我哋保護自然保護區咁。', cat: '天文與太空', level: 2, src: 'https://en.wikipedia.org/wiki/Zoo_hypothesis' },
  { term: '胚種論', explain: '生命可能以微生物形式附喺彗星或者隕石上面，喺行星之間傳播。', cat: '天文與太空', level: 3, src: 'https://en.wikipedia.org/wiki/Panspermia' },
  { term: '費米氣泡', explain: '銀河系中心上下兩側各一個巨大嘅伽瑪射線氣泡，各伸展約2萬5千光年，2010年被費米望遠鏡嘅數據發現。', cat: '天文與太空', level: 3, src: 'https://en.wikipedia.org/wiki/Fermi_Gamma-ray_Space_Telescope' },
  { term: '梅西爾星表', explain: '法國天文學家梅西爾編嘅天體目錄，初衷係列出睇落似彗星嘅星雲同星團，等自己搵彗星時唔使誤認。', cat: '天文與太空', level: 2, src: 'https://en.wikipedia.org/wiki/Messier_object' },
  { term: '卡林頓事件', explain: '1859年嘅超強太陽風暴，令歐洲同北美嘅電報系統失靈，連近赤道地區都見到極光。', cat: '天文與太空', level: 2, src: 'https://en.wikipedia.org/wiki/Carrington_Event' },
  { term: '舒梅克-李維9號彗星', explain: '1992年被木星潮汐力撕成21塊碎片嘅彗星，1994年碎片接連撞入木星。', cat: '天文與太空', level: 3, src: 'https://en.wikipedia.org/wiki/Comet_Shoemaker%E2%80%93Levy_9' },
  { term: '哈勃深空視場', explain: '1995年哈勃望遠鏡對準一小片睇落乜都冇嘅天空，連續曝光約十日，結果拍到約3000個星系。', cat: '天文與太空', level: 2, src: 'https://en.wikipedia.org/wiki/Hubble_Deep_Field' },
  { term: '天鵝座X-1', explain: '首個被廣泛接受係黑洞嘅天體，霍金曾同索恩打賭佢唔係黑洞，1990年認輸。', cat: '天文與太空', level: 3, src: 'https://en.wikipedia.org/wiki/Cygnus_X-1' },
  // ---------------------------------------------------------- 科學與醫學名詞
  { term: '光幻視', explain: '閉上眼用手揉眼睛時見到嘅光點同圖案，係視網膜受壓力刺激，而唔係真係有光。', cat: '科學與醫學名詞', level: 1, src: 'https://en.wikipedia.org/wiki/Phosphene' },
  { term: '土臭素', explain: '由土壤細菌產生、令泥土有獨特氣味嘅化學物質，人類鼻子對佢極敏感，微量都聞得出。', cat: '科學與醫學名詞', level: 2, src: 'https://en.wikipedia.org/wiki/Geosmin' },
  { term: '群體感應', explain: '細菌釋放化學訊號偵測周圍同類嘅數量，夠多先集體行動，例如一齊發光。', cat: '科學與醫學名詞', level: 3, src: 'https://en.wikipedia.org/wiki/Quorum_sensing' },
  { term: '朊病毒', explain: '冇核酸、純由摺錯咗嘅蛋白質構成，卻可以傳染並令腦部出現海綿狀病變。', cat: '科學與醫學名詞', level: 1, src: 'https://en.wikipedia.org/wiki/Prion' },
  { term: '細胞凋亡', explain: '細胞按基因程式有序咁自我了斷，例如胚胎期手指之間嘅蹼就係咁消失。', cat: '科學與醫學名詞', level: 2, src: 'https://en.wikipedia.org/wiki/Apoptosis' },
  { term: '端粒', explain: '染色體兩端嘅保護帽，細胞每分裂一次就縮短少少，好似鞋帶尾嘅塑膠頭。', cat: '科學與醫學名詞', level: 1, src: 'https://en.wikipedia.org/wiki/Telomere' },
  { term: '表觀遺傳學', explain: '研究唔改變DNA序列、但會影響基因開關嘅機制，飲食同環境都可能留下印記。', cat: '科學與醫學名詞', level: 2, src: 'https://en.wikipedia.org/wiki/Epigenetics' },
  { term: '水平基因轉移', explain: '生物之間唔經繁殖就直接交換基因，喺細菌之間好常見，係抗藥性擴散嘅原因之一。', cat: '科學與醫學名詞', level: 3, src: 'https://en.wikipedia.org/wiki/Horizontal_gene_transfer' },
  { term: '內共生學說', explain: '指線粒體同葉綠體源自被古老細胞吞入、之後長期共生嘅細菌。', cat: '科學與醫學名詞', level: 3, src: 'https://en.wikipedia.org/wiki/Symbiogenesis' },
  { term: '趨同演化', explain: '親緣好遠嘅物種因為環境相似，各自演化出類似特徵，例如海豚同鯊魚嘅流線體形。', cat: '科學與醫學名詞', level: 2, src: 'https://en.wikipedia.org/wiki/Convergent_evolution' },
  { term: '本體感覺', explain: '閉住眼都知道自己手腳擺喺邊，係靠肌肉同關節入面嘅感受器回報位置。', cat: '科學與醫學名詞', level: 2, src: 'https://en.wikipedia.org/wiki/Proprioception' },
  { term: '內感受', explain: '感知身體內部狀態嘅能力，例如心跳、肚餓同尿急。', cat: '科學與醫學名詞', level: 3, src: 'https://en.wikipedia.org/wiki/Interoception' },
  { term: '入睡幻覺', explain: '半夢半醒、快要入睡嗰陣出現嘅影像或者聲音，並唔係真實存在。', cat: '科學與醫學名詞', level: 2, src: 'https://en.wikipedia.org/wiki/Hypnagogia' },
  { term: '皮膚劃痕症', explain: '皮膚輕輕刮一下就浮現紅腫條痕，好似喺皮膚上面寫字。', cat: '科學與醫學名詞', level: 3, src: 'https://en.wikipedia.org/wiki/Dermatographic_urticaria' },
  { term: '四色視覺', explain: '擁有四種視錐細胞，理論上可以分辨嘅顏色比一般人嘅三種視錐多好多。', cat: '科學與醫學名詞', level: 2, src: 'https://en.wikipedia.org/wiki/Tetrachromacy' },
  { term: '虹膜異色症', explain: '兩隻眼嘅虹膜顏色唔同，或者同一隻眼入面有兩種顏色。', cat: '科學與醫學名詞', level: 2, src: 'https://en.wikipedia.org/wiki/Heterochromia' },
  { term: '內臟逆位', explain: '內臟排列同常人成鏡像，例如心臟喺右邊，大約一萬人先有一個。', cat: '科學與醫學名詞', level: 2, src: 'https://en.wikipedia.org/wiki/Situs_inversus' },
  { term: 'Zugunruhe', explain: '候鳥喺遷徙季節，就算關喺籠入面都會變得焦躁，並朝住遷徙嘅方向亂撲。', cat: '科學與醫學名詞', level: 3, src: 'https://en.wikipedia.org/wiki/Zugunruhe' },
  { term: '菌根', explain: '真菌同植物根部共生嘅結構，真菌幫植物吸水同養分，植物則提供糖分。', cat: '科學與醫學名詞', level: 3, src: 'https://en.wikipedia.org/wiki/Mycorrhiza' },
  { term: '壓電效應', explain: '某啲晶體受壓時會產生電壓，部分打火機嘅點火裝置就係用呢個原理。', cat: '科學與醫學名詞', level: 2, src: 'https://en.wikipedia.org/wiki/Piezoelectricity' },
  { term: '摩擦發光', explain: '撕開膠紙、壓碎糖或晶體等動作，可以令物質發出微弱光，過程唔需要加熱。', cat: '科學與醫學名詞', level: 3, src: 'https://en.wikipedia.org/wiki/Triboluminescence' },
  { term: '姆潘巴效應', explain: '有人觀察到某啲條件下熱水比冷水更快結冰，但係咪真實存在、成因係乜，至今仍有爭論。', cat: '科學與醫學名詞', level: 3, src: 'https://en.wikipedia.org/wiki/Mpemba_effect' },
  { term: '萊頓弗羅斯特效應', explain: '水珠落喺遠高過沸點嘅熱鑊上，底部形成蒸氣層，令水珠滑嚟滑去好耐都唔蒸發。', cat: '科學與醫學名詞', level: 3, src: 'https://en.wikipedia.org/wiki/Leidenfrost_effect' },
  { term: '巴西果效應', explain: '搖動大細唔同嘅顆粒，最大嗰啲會升到面頭，例如一盒早餐麥片搖完，面頭多提子乾，底部淨係碎片。', cat: '科學與醫學名詞', level: 3, src: 'https://en.wikipedia.org/wiki/Granular_convection' },
  { term: '克拉德尼圖形', explain: '喺薄金屬板撒沙再用琴弓拉動板邊，沙粒會因為振動排成對稱嘅圖案。', cat: '科學與醫學名詞', level: 3, src: 'https://en.wikipedia.org/wiki/Ernst_Chladni' },
  { term: '丁達爾效應', explain: '光線穿過霧、煙或者膠體時，光路變得清晰可見，例如樹林間嘅一道道光束。', cat: '科學與醫學名詞', level: 2, src: 'https://en.wikipedia.org/wiki/Tyndall_effect' },
  { term: '切倫科夫輻射', explain: '帶電粒子喺水中跑得比光喺水中更快時發出嘅藍光，核反應堆水池嘅藍光就係咁嚟。', cat: '科學與醫學名詞', level: 3, src: 'https://en.wikipedia.org/wiki/Cherenkov_radiation' },
  { term: '氣凝膠', explain: '體積九成以上係空氣嘅固體，係世上最輕嘅材料之一，隔熱效果極好。', cat: '科學與醫學名詞', level: 1, src: 'https://en.wikipedia.org/wiki/Aerogel' },
  { term: '準晶體', explain: '結構有規律但唔會周期性重複嘅晶體，發現者獲2011年諾貝爾化學獎。', cat: '科學與醫學名詞', level: 3, src: 'https://en.wikipedia.org/wiki/Quasicrystal' },
  { term: '毒物興奮效應', explain: '少量有害物質反而對生物有益，劑量一高就變返有害。', cat: '科學與醫學名詞', level: 3, src: 'https://en.wikipedia.org/wiki/Hormesis' },
  { term: '生物膜', explain: '細菌聚集喺表面並分泌黏液包住自己，牙菌斑就係常見例子。', cat: '科學與醫學名詞', level: 2, src: 'https://en.wikipedia.org/wiki/Biofilm' },
  { term: '返祖現象', explain: '後代突然出現祖先擁有、但已消失好耐嘅特徵，例如鯨魚偶爾長出細小後肢。', cat: '科學與醫學名詞', level: 3, src: 'https://en.wikipedia.org/wiki/Atavism' },
  { term: '化感作用', explain: '植物釋放化學物質去抑制附近其他植物生長，黑胡桃樹係常被引用嘅例子。', cat: '科學與醫學名詞', level: 3, src: 'https://en.wikipedia.org/wiki/Allelopathy' },
  { term: '胃石', explain: '喺胃入面由毛髮或者植物纖維積聚而成嘅硬塊，古時被當成萬能解毒藥。', cat: '科學與醫學名詞', level: 3, src: 'https://en.wikipedia.org/wiki/Bezoar' },
  { term: '龍涎香', explain: '抹香鯨腸道內形成嘅蠟狀物質，經海水漂浮日曬後可以用作香水嘅定香劑。', cat: '科學與醫學名詞', level: 1, src: 'https://en.wikipedia.org/wiki/Ambergris' },
  { term: '授時因子', explain: '外界用嚟校準生理時鐘嘅線索，最主要嘅就係光線。', cat: '科學與醫學名詞', level: 3, src: 'https://en.wikipedia.org/wiki/Zeitgeber' },
  { term: '腸腦軸', explain: '腸道同大腦之間，經神經、荷爾蒙同免疫系統進行雙向溝通嘅渠道。', cat: '科學與醫學名詞', level: 2, src: 'https://en.wikipedia.org/wiki/Gut%E2%80%93brain_axis' },
  { term: '迷走神經', explain: '由腦幹延伸到腹部嘅最長腦神經，參與控制心跳同消化。', cat: '科學與醫學名詞', level: 2, src: 'https://en.wikipedia.org/wiki/Vagus_nerve' },
  { term: '鏡像神經元', explain: '猴子自己拎起食物同睇人拎起食物時，部分相同嘅神經元都會活躍。', cat: '科學與醫學名詞', level: 2, src: 'https://en.wikipedia.org/wiki/Mirror_neuron' },
  { term: '外國口音症候群', explain: '腦部受損後，說話口音突然變得似另一個地方嘅人，患者自己可能從未去過嗰度。', cat: '科學與醫學名詞', level: 3, src: 'https://en.wikipedia.org/wiki/Foreign_accent_syndrome' },
  { term: '異形手症候群', explain: '其中一隻手會唔受控制咁自行動作，患者覺得佢好似唔屬於自己。', cat: '科學與醫學名詞', level: 3, src: 'https://en.wikipedia.org/wiki/Alien_hand_syndrome' },
  { term: '聯覺', explain: '刺激一種感官時會自動引起另一種感覺，例如睇到數字就見到特定顏色。', cat: '科學與醫學名詞', level: 1, src: 'https://en.wikipedia.org/wiki/Synesthesia' },
  { term: 'Aphantasia', explain: '腦海中無法浮現視覺畫面，叫佢閉上眼諗一個蘋果都見唔到。', cat: '科學與醫學名詞', level: 2, src: 'https://en.wikipedia.org/wiki/Aphantasia' },
  { term: '超憶症', explain: '能夠詳細記起自己人生中幾乎每一日發生過嘅事，包括當日日期同天氣。', cat: '科學與醫學名詞', level: 2, src: 'https://en.wikipedia.org/wiki/Hyperthymesia' },
  { term: '恐音症', explain: '對特定細微聲音，例如咀嚼聲，產生強烈厭惡甚至憤怒嘅反應。', cat: '科學與醫學名詞', level: 2, src: 'https://en.wikipedia.org/wiki/Misophonia' },
  { term: '卡普格拉斯綜合症', explain: '患者堅信身邊嘅親人被長得一模一樣嘅冒充者取代，但仍然認得出佢哋嘅樣貌。', cat: '科學與醫學名詞', level: 3, src: 'https://en.wikipedia.org/wiki/Capgras_delusion' },
  { term: '掃視', explain: '眼睛由一點跳到另一點嘅極快動作，期間大腦會壓抑視覺訊號，所以你唔覺得畫面喺度郁。', cat: '科學與醫學名詞', level: 3, src: 'https://en.wikipedia.org/wiki/Saccade' },
  { term: '紅色精靈', explain: '雷暴雲頂上方高空出現嘅短暫紅色閃光，同一般閃電唔同。', cat: '科學與醫學名詞', level: 2, src: 'https://en.wikipedia.org/wiki/Sprite_(lightning)' },
  { term: '夜光雲', explain: '夏季黃昏喺高緯度地區見到、高度約76至85公里嘅發光薄雲，比其他任何雲都高。', cat: '科學與醫學名詞', level: 3, src: 'https://en.wikipedia.org/wiki/Noctilucent_cloud' },
  { term: '瑞利散射', explain: '空氣分子散射藍光比紅光強得多，所以天空係藍色，日落先會偏紅。', cat: '科學與醫學名詞', level: 2, src: 'https://en.wikipedia.org/wiki/Rayleigh_scattering' },
  { term: '紅皇后假說', explain: '物種要不斷演化先可以保持原有嘅生存機會，因為對手同天敵都喺度演化；名稱取自《愛麗絲鏡中奇遇》。', cat: '科學與醫學名詞', level: 2, src: 'https://en.wikipedia.org/wiki/Red_Queen_hypothesis' },
  { term: '康達效應', explain: '流體會傾向貼住附近嘅曲面流動，例如水流會沿住匙羹背面彎曲；唔係飛機升力嘅主要成因。', cat: '科學與醫學名詞', level: 3, src: 'https://en.wikipedia.org/wiki/Coand%C4%83_effect' },
  { term: '趨磁細菌', explain: '體內有磁性晶體嘅細菌，會順住地球磁場方向游動，幫佢哋搵到含氧量適合嘅水層。', cat: '科學與醫學名詞', level: 3, src: 'https://en.wikipedia.org/wiki/Magnetotactic_bacteria' },
  { term: '馬格努斯效應', explain: '旋轉緊嘅球飛行時會受側向力而偏離直線，所以足球先踢得出弧線嘅香蕉球。', cat: '科學與醫學名詞', level: 2, src: 'https://en.wikipedia.org/wiki/Magnus_effect' },
  { term: 'philtrum', explain: '鼻同上唇之間嗰條直向小凹槽，即係人中；字源係希臘文，原意係「愛情符咒」。', cat: '科學與醫學名詞', level: 2, src: 'https://en.wikipedia.org/wiki/Philtrum' },
  { term: 'lunula', explain: '手指甲底部嗰個半月形白色部分，拉丁文原意係「小月亮」，胎兒大約十四週大時已經出現。', cat: '科學與醫學名詞', level: 3, src: 'https://en.wikipedia.org/wiki/Lunula_(anatomy)' },
  { term: 'tragus', explain: '耳洞前面嗰粒突出嘅小軟骨；字源係希臘文「山羊」，因為上面嘅毛似山羊鬚。', cat: '科學與醫學名詞', level: 3, src: 'https://en.wikipedia.org/wiki/Tragus_(ear)' },
  { term: 'glabella', explain: '兩條眉毛中間、鼻樑上面嗰塊皮膚，亦指皮膚下面微微凹入、連住兩邊眉骨嘅骨位。', cat: '科學與醫學名詞', level: 3, src: 'https://en.wikipedia.org/wiki/Glabella' },
  { term: 'lacrimal caruncle', explain: '眼睛內側眼角嗰粒粉紅色嘅小肉粒，由鄰近眼部結構嘅幾種組織組成。', cat: '科學與醫學名詞', level: 3, src: 'https://en.wikipedia.org/wiki/Lacrimal_caruncle' },
  // ---------------------------------------------------------- 心理學效應
  { term: '蔡格尼克效應', explain: '1920年代研究提出，人對未完成或者被打斷嘅事記得更清楚，但近年嘅綜合分析發現記憶優勢並不明顯。', cat: '心理學效應', level: 2, src: 'https://en.wikipedia.org/wiki/Zeigarnik_effect' },
  { term: '巴德爾-邁因霍夫現象', explain: '剛留意到某樣嘢之後，就覺得佢突然到處出現，其實佢出現嘅頻率冇變，只係你而家先開始留意。', cat: '心理學效應', level: 1, src: 'https://en.wikipedia.org/wiki/Frequency_illusion' },
  { term: '宜家效應', explain: '人對自己親手砌過、整過嘅嘢特別有感情，會高估佢嘅價值，就算成品好普通。', cat: '心理學效應', level: 1, src: 'https://en.wikipedia.org/wiki/IKEA_effect' },
  { term: '皮格馬利翁效應', explain: '有研究指，別人對你期望越高，你嘅表現越傾向貼近期望，1960年代嘅學校班房實驗令呢個說法出名。', cat: '心理學效應', level: 1, src: 'https://en.wikipedia.org/wiki/Pygmalion_effect' },
  { term: '霍桑效應', explain: '人知道自己被觀察嗰陣會改變行為，名稱源自1920年代西方電氣工廠嘅生產力研究，後來有人質疑當年結論。', cat: '心理學效應', level: 1, src: 'https://en.wikipedia.org/wiki/Hawthorne_effect' },
  { term: '反安慰劑效應', explain: '人因為預期藥會有副作用，結果食咗冇藥效嘅糖丸都真係出現不適。', cat: '心理學效應', level: 2, src: 'https://en.wikipedia.org/wiki/Nocebo' },
  { term: '富蘭克林效應', explain: '你請某人幫過你一次忙，佢往往反而會更鍾意你，因為佢需要合理化自己點解肯幫手。', cat: '心理學效應', level: 2, src: 'https://en.wikipedia.org/wiki/Benjamin_Franklin_effect' },
  { term: '巴納姆效應', explain: '人會覺得一段籠統、幾乎乜人都啱用嘅性格描述，好似度身訂造咁準確。', cat: '心理學效應', level: 1, src: 'https://en.wikipedia.org/wiki/Barnum_effect' },
  { term: '史楚普效應', explain: '當字義同字體顏色互相矛盾，例如用紅色寫「藍」字，要讀出顏色就會明顯慢啲。', cat: '心理學效應', level: 1, src: 'https://en.wikipedia.org/wiki/Stroop_effect' },
  { term: '麥格克效應', explain: '聽到嘅聲音會受你睇到嘅口形影響，同一段聲音配唔同口形，可以聽成另一個音。', cat: '心理學效應', level: 2, src: 'https://en.wikipedia.org/wiki/McGurk_effect' },
  { term: '馮·雷斯托夫效應', explain: '一列相似嘅項目入面，同其他明顯唔同嗰個最容易被記住，例如一堆黑字入面嘅紅字。', cat: '心理學效應', level: 3, src: 'https://en.wikipedia.org/wiki/Von_Restorff_effect' },
  { term: '雞尾酒會效應', explain: '喺嘈雜環境入面，人可以專心聽一個人講嘢，而且一有人叫自己個名就即刻留意到。', cat: '心理學效應', level: 1, src: 'https://en.wikipedia.org/wiki/Cocktail_party_effect' },
  { term: '聚光燈效應', explain: '人傾向高估其他人留意到自己嘅程度，例如以為人人都見到你件衫上面嘅污糟印。', cat: '心理學效應', level: 1, src: 'https://en.wikipedia.org/wiki/Spotlight_effect' },
  { term: '單純曝光效應', explain: '對一樣嘢接觸得越多，就越傾向鍾意佢，就算起初完全冇特別感覺。', cat: '心理學效應', level: 1, src: 'https://en.wikipedia.org/wiki/Mere-exposure_effect' },
  { term: '奧夫相基娜效應', explain: '做到一半被打斷嘅工作，人一有機會就會好想返去繼續完成佢。', cat: '心理學效應', level: 3, src: 'https://en.wikipedia.org/wiki/Ovsiankina_effect' },
  { term: '過度辯證效應', explain: '本來出於興趣去做嘅事，一旦開始俾獎勵，內在動機反而會下降。', cat: '心理學效應', level: 3, src: 'https://en.wikipedia.org/wiki/Overjustification_effect' },
  { term: '林格曼效應', explain: '集體做事時，人數越多，每個人平均付出嘅力氣就越少，最初係喺拉繩實驗中發現。', cat: '心理學效應', level: 3, src: 'https://en.wikipedia.org/wiki/Ringelmann_effect' },
  { term: '佩爾茲曼效應', explain: '安全措施增加之後，人反而傾向冒更大風險，令保護效果被抵銷咗一部分。', cat: '心理學效應', level: 3, src: 'https://en.wikipedia.org/wiki/Risk_compensation' },
  { term: '沃比岡湖效應', explain: '大部分人都相信自己嘅能力高過平均，名稱取自一個電台節目入面「所有小朋友都高於平均」嘅虛構小鎮。', cat: '心理學效應', level: 3, src: 'https://en.wikipedia.org/wiki/Illusory_superiority' },
  { term: '出醜效應', explain: '能力出眾嘅人偶爾出啲小差錯，例如打翻咖啡，反而會令人覺得佢更可愛。', cat: '心理學效應', level: 2, src: 'https://en.wikipedia.org/wiki/Pratfall_effect' },
  { term: '俄羅斯方塊效應', explain: '長時間專注做同一樣嘢之後，腦海同夢境都會不斷重複出現相關畫面。', cat: '心理學效應', level: 2, src: 'https://en.wikipedia.org/wiki/Tetris_effect' },
  { term: '啦啦隊效應', explain: '有研究提出，同一個人喺人群入面睇落會比單獨出現時更吸引，但後續研究嘅結果有分歧。', cat: '心理學效應', level: 2, src: 'https://en.wikipedia.org/wiki/Cheerleader_effect' },
  { term: '熱手謬誤', explain: '相信連續命中嘅球員下一球更易命中，名稱源自籃球；1985年研究話係錯覺，近年有研究質疑呢個結論。', cat: '心理學效應', level: 2, src: 'https://en.wikipedia.org/wiki/Hot_hand' },
  { term: '塞麥爾維斯反射', explain: '下意識拒絕同自己原有信念相衝突嘅新證據，名稱取自一位因主張洗手而被同行排斥嘅醫生。', cat: '心理學效應', level: 3, src: 'https://en.wikipedia.org/wiki/Semmelweis_reflex' },
  { term: '間隔效應', explain: '分幾次、隔開時間重複溫習，比一次過密集死記更能長久記住。', cat: '心理學效應', level: 2, src: 'https://en.wikipedia.org/wiki/Spacing_effect' },
  { term: '測試效應', explain: '主動考自己，比起單純重讀教材，更有助長期記憶。', cat: '心理學效應', level: 2, src: 'https://en.wikipedia.org/wiki/Testing_effect' },
  { term: '生成效應', explain: '自己諗出或者寫出嚟嘅資料，比單純睇別人提供嘅更容易記住。', cat: '心理學效應', level: 3, src: 'https://en.wikipedia.org/wiki/Generation_effect' },
  { term: '門口效應', explain: '研究發現，行過一道門之後人更容易忘記剛才打算做嘅事，例如入咗房就唔記得想攞乜。', cat: '心理學效應', level: 2, src: 'https://en.wikipedia.org/wiki/Event_perception' },
  { term: '谷歌效應', explain: '2011年有研究提出，知道隨時可以上網搵到資料，人就傾向唔去記內容，只記得去邊度搵；後來嘅重複實驗結果有爭議。', cat: '心理學效應', level: 2, src: 'https://en.wikipedia.org/wiki/Google_effect' },
  { term: '鄧巴數', explain: '人類能夠維持穩定社交關係嘅人數上限，估計約為150人。', cat: '心理學效應', level: 1, src: 'https://en.wikipedia.org/wiki/Dunbar%27s_number' },
  { term: 'Bouba/Kiki 效應', explain: '多數人會將「bouba」呢個音配圓滑形狀，將「kiki」配尖角形狀，喺唔同語言文化入面都見到類似傾向。', cat: '心理學效應', level: 2, src: 'https://en.wikipedia.org/wiki/Bouba/kiki_effect' },
  { term: '弗林效應', explain: '二十世紀大半時間，好多國家嘅智商測驗平均分數每十年約升3分，近年部分國家已經停滯甚至回落。', cat: '心理學效應', level: 3, src: 'https://en.wikipedia.org/wiki/Flynn_effect' },
  { term: '耶克斯-多德森定律', explain: '壓力或者緊張程度適中嘅時候表現最好，太低會悶，太高就會失準。', cat: '心理學效應', level: 3, src: 'https://en.wikipedia.org/wiki/Yerkes%E2%80%93Dodson_law' },
  { term: '空想性錯視', explain: '喺雲、牆身或者燒焦嘅麵包等隨機圖案入面，睇到面孔等熟悉形狀。', cat: '心理學效應', level: 1, src: 'https://en.wikipedia.org/wiki/Pareidolia' },
  { term: '幽靈震動症候群', explain: '明明冇人搵你，卻覺得電話喺褲袋震咗一下，研究發現好多手機用家都試過。', cat: '心理學效應', level: 1, src: 'https://en.wikipedia.org/wiki/Phantom_vibration_syndrome' },
  { term: '喬哈里窗', explain: '一個將「自己知唔知」同「別人知唔知」交叉成四格嘅人際溝通模型。', cat: '心理學效應', level: 2, src: 'https://en.wikipedia.org/wiki/Johari_window' },
  { term: '基本歸因謬誤', explain: '解釋別人嘅行為時，傾向歸咎於佢嘅性格，而忽略當時環境嘅影響。', cat: '心理學效應', level: 1, src: 'https://en.wikipedia.org/wiki/Fundamental_attribution_error' },
  { term: '不注意視盲', explain: '專注做緊某件事時，對眼前明顯嘅事物視而不見，例如傳球實驗中約一半人冇留意到走過嘅大猩猩。', cat: '心理學效應', level: 2, src: 'https://en.wikipedia.org/wiki/Inattentional_blindness' },
  { term: '變化盲視', explain: '畫面出現明顯改變，人卻察覺唔到，尤其當改變發生喺眨眼或者鏡頭切換之間。', cat: '心理學效應', level: 2, src: 'https://en.wikipedia.org/wiki/Change_blindness' },
  { term: '稟賦效應', explain: '人一旦擁有某樣嘢，就覺得佢更值錢，所以賣出價往往高過願意買入嘅價錢。', cat: '心理學效應', level: 1, src: 'https://en.wikipedia.org/wiki/Endowment_effect' },
  { term: '透明度錯覺', explain: '以為自己嘅情緒同心思好容易被人睇穿，其實別人未必察覺到。', cat: '心理學效應', level: 3, src: 'https://en.wikipedia.org/wiki/Illusion_of_transparency' },
  { term: '知識詛咒', explain: '一旦識咗某樣嘢，就好難想像唔識嘅人點諗，所以講解時往往太深太快。', cat: '心理學效應', level: 1, src: 'https://en.wikipedia.org/wiki/Curse_of_knowledge' },
  { term: '語義飽和', explain: '一個字重複唸或者望好多次之後，會暫時失去意思，變成淨係一串無意義嘅聲音。', cat: '心理學效應', level: 2, src: 'https://en.wikipedia.org/wiki/Semantic_satiation' },
  { term: '睡眠者效應', explain: '來源冇咩公信力嘅訊息，起初冇乜說服力，一段時間後人哋記得內容卻忘記來源，說服力反而上升。', cat: '心理學效應', level: 3, src: 'https://en.wikipedia.org/wiki/Sleeper_effect' },
  { term: '狄德羅效應', explain: '買咗一件新嘢之後，覺得身邊其他嘢都唔襯，結果不斷追加購買；名稱源自哲學家狄德羅一件紅色睡袍嘅故事。', cat: '心理學效應', level: 2, src: 'https://en.wikipedia.org/wiki/Diderot_effect' },
  { term: '誤導資訊效應', explain: '事發之後接收到嘅誤導資訊，會扭曲人對事件本身嘅記憶，例如問車「撞毀」定「撞到」會令人估計車速更高。', cat: '心理學效應', level: 2, src: 'https://en.wikipedia.org/wiki/Misinformation_effect' },
  { term: '錯誤共識效應', explain: '人傾向高估其他人同自己有相同想法或者做法嘅比例，以為「大家都咁諗」。', cat: '心理學效應', level: 2, src: 'https://en.wikipedia.org/wiki/False_consensus_effect' },
  { term: '信念固著', explain: '就算支持原有信念嘅證據已經被證實係假，人仍然傾向繼續相信原有嘅信念。', cat: '心理學效應', level: 2, src: 'https://en.wikipedia.org/wiki/Belief_perseverance' },
  // ---------------------------------------------------------- 自然現象
  { term: '球狀閃電', explain: '雷暴期間偶爾見到嘅發光球體，可以飄浮幾秒，至今科學界都未有公認嘅成因解釋。', cat: '自然現象', level: 1, src: 'https://en.wikipedia.org/wiki/Ball_lightning' },
  { term: '冰火山', explain: '噴出嘅唔係熔岩，而係水、氨或者甲烷等冰冷物質，土衛二同海衛一等天體上有類似嘅噴發。', cat: '自然現象', level: 3, src: 'https://en.wikipedia.org/wiki/Cryovolcano' },
  { term: '聖艾爾摩之火', explain: '雷雨天氣下，船桅、機翼等尖端位置出現嘅藍紫色放電光芒，以前水手視為吉兆。', cat: '自然現象', level: 1, src: 'https://en.wikipedia.org/wiki/St._Elmo%27s_fire' },
  { term: '死亡冰柱', explain: '極地海冰底部向下長嘅冰管，由極冷極鹹嘅鹽水下沉結冰而成，碰到海床會凍死海星、海膽。', cat: '自然現象', level: 3, src: 'https://en.wikipedia.org/wiki/Brinicle' },
  { term: '光柱', explain: '喺極寒嘅夜晚，空氣中嘅冰晶反射地面燈光，喺夜空形成一條條垂直向上嘅光線。', cat: '自然現象', level: 1, src: 'https://en.wikipedia.org/wiki/Light_pillar' },
  { term: '幻日', explain: '太陽兩旁出現嘅明亮光點，睇落似多咗兩個太陽，由空中嘅冰晶折射陽光而成。', cat: '自然現象', level: 1, src: 'https://en.wikipedia.org/wiki/Sun_dog' },
  { term: '環天頂弧', explain: '天空頂部出現嘅彩色弧線，形似倒轉嘅彩虹，同樣由空中嘅冰晶折射陽光形成。', cat: '自然現象', level: 3, src: 'https://en.wikipedia.org/wiki/Circumzenithal_arc' },
  { term: '布羅肯現象', explain: '喺山上背向太陽，自己嘅巨大影子投到雲霧上，影子四周仲圍住一圈彩色光環。', cat: '自然現象', level: 2, src: 'https://en.wikipedia.org/wiki/Brocken_spectre' },
  { term: '法塔摩根納（Fata Morgana）', explain: '一種複雜嘅蜃景，令遠處嘅船或者海岸線睇落被拉長、疊高，似座城堡咁。', cat: '自然現象', level: 2, src: 'https://en.wikipedia.org/wiki/Fata_Morgana_(mirage)' },
  { term: '笠雲', explain: '喺山頂形成、似戴咗頂斗笠嘅雲，富士山經常出現，日本人傳統上視為快將轉天氣嘅預兆。', cat: '自然現象', level: 1, src: 'https://ja.wikipedia.org/wiki/%E7%AC%A0%E9%9B%B2' },
  { term: '乳狀雲', explain: '雷暴雲底部垂落嘅一個個袋形雲塊，樣子好特別，通常同強烈雷暴有關。', cat: '自然現象', level: 2, src: 'https://en.wikipedia.org/wiki/Mammatus_cloud' },
  { term: '開爾文-亥姆霍茲雲', explain: '雲層頂部排成一列列似海浪翻捲嘅形狀，成因係上下兩層空氣嘅流速唔同。', cat: '自然現象', level: 3, src: 'https://en.wikipedia.org/wiki/Kelvin%E2%80%93Helmholtz_instability' },
  { term: '冰圓盤', explain: '慢流河面上出現嘅圓形冰盤，冇人推都會慢慢自轉，成因同水流嘅旋渦有關。', cat: '自然現象', level: 3, src: 'https://en.wikipedia.org/wiki/Ice_disc' },
  { term: '海火', explain: '夜晚海浪或者船隻經過時發出藍色光芒嘅現象，由會發光嘅浮游生物造成。', cat: '自然現象', level: 1, src: 'https://en.wikipedia.org/wiki/Noctiluca_scintillans' },
  { term: '乳白海', explain: '喺印度洋等海域，整片海水喺夜晚持續發出均勻嘅乳白色光，面積最大可以去到十萬平方公里。', cat: '自然現象', level: 3, src: 'https://en.wikipedia.org/wiki/Milky_seas_effect' },
  { term: '鳴門漩渦', explain: '日本德島同淡路島之間嘅海峽，大潮時水流湧過形成嘅大漩渦，直徑最大可以達到二十米。', cat: '自然現象', level: 1, src: 'https://en.wikipedia.org/wiki/Naruto_whirlpools' },
  { term: '藍火', explain: '印尼伊真火山夜裡出現嘅藍色火焰，唔係熔岩，而係燃燒緊嘅硫磺氣體。', cat: '自然現象', level: 2, src: 'https://en.wikipedia.org/wiki/Kawah_Ijen' },
  { term: '佩雷之髮', explain: '熔岩噴泉拋到半空時被拉成嘅金黃色玻璃細絲，似一把頭髮，名字來自夏威夷火山女神。', cat: '自然現象', level: 3, src: 'https://en.wikipedia.org/wiki/Pele%27s_hair' },
  { term: '鳴沙', explain: '喺某啲沙丘上，沙粒隨風或者有人行過而滑落時，會發出低沉嘅轟鳴聲，可以持續幾分鐘。', cat: '自然現象', level: 2, src: 'https://en.wikipedia.org/wiki/Singing_sand' },
  { term: '迷蹤石', explain: '美國死亡谷乾湖上嘅石頭，冇人推都會喺泥地留下長長軌跡，2014年研究證實係薄冰碎裂後被微風推動。', cat: '自然現象', level: 3, src: 'https://en.wikipedia.org/wiki/Sailing_stones' },
  { term: '黑煙囪', explain: '深海海床噴出攝氏三四百度黑色熱水嘅煙囪狀構造，水因為壓力極大而唔會沸騰。', cat: '自然現象', level: 2, src: 'https://en.wikipedia.org/wiki/Hydrothermal_vent' },
  { term: '鯨落', explain: '鯨魚死後沉到海底，屍體成為深海生物嘅食物同家園，可以養活一個生態系統幾十年。', cat: '自然現象', level: 1, src: 'https://en.wikipedia.org/wiki/Whale_fall' },
  { term: '環水平弧', explain: '卷雲入面嘅六角形冰晶折射陽光形成嘅水平彩色光帶，俗稱「火彩虹」，但同彩虹冇關。', cat: '自然現象', level: 3, src: 'https://en.wikipedia.org/wiki/Circumhorizontal_arc' },
  { term: '蓮葉冰', explain: '海水或者湖水開始結冰時，形成嘅圓形冰塊，邊緣因為互相碰撞而翹起，樣似一塊塊荷葉。', cat: '自然現象', level: 3, src: 'https://en.wikipedia.org/wiki/Pancake_ice' },
  { term: '西瓜雪', explain: '高山或者極地嘅雪地因為耐寒藻類而變成粉紅色，據說仲帶有淡淡嘅西瓜味。', cat: '自然現象', level: 2, src: 'https://en.wikipedia.org/wiki/Watermelon_snow' },
  { term: '地球嗡鳴', explain: '就算冇地震，地球都不停發出人耳聽唔到嘅極低頻震動，一般認為同海浪有關。', cat: '自然現象', level: 3, src: 'https://en.wikipedia.org/wiki/Earth%27s_hum' },
  { term: '血瀑布', explain: '南極泰勒冰川流出嘅紅色鹹水，紅色係因為水中嘅鐵質接觸空氣而氧化。', cat: '自然現象', level: 2, src: 'https://en.wikipedia.org/wiki/Blood_Falls' },
  { term: '氣輝', explain: '夜空中大氣層高處嘅分子釋放出嘅微弱光芒，就算冇月亮同城市燈光都存在。', cat: '自然現象', level: 3, src: 'https://en.wikipedia.org/wiki/Airglow' },
  { term: '仙女圈', explain: '納米比亞草原上出現嘅圓形光禿地帶，直徑約二至十二米，成因有白蟻同植物自我組織兩種說法。', cat: '自然現象', level: 3, src: 'https://en.wikipedia.org/wiki/Fairy_circle_(arid_grass_formation)' },
  { term: '蒸汽霧', explain: '冬天極冷空氣吹過較暖嘅水面，水面好似冒煙咁嘅霧，日本北海道一帶叫做「氣嵐」。', cat: '自然現象', level: 3, src: 'https://ja.wikipedia.org/wiki/%E8%92%B8%E6%B0%97%E9%9C%A7' },
  { term: '鑽石塵', explain: '極寒而晴朗嘅早上，空氣中嘅水氣凝成微細冰晶，喺陽光下閃閃發光，北海道可以見到。', cat: '自然現象', level: 1, src: 'https://en.wikipedia.org/wiki/Diamond_dust' },
  { term: '雷雪', explain: '落雪期間打雷嘅罕見天氣，日本海沿岸嘅冬天比較常見，日文叫「雪起こし」，被視為大雪前兆。', cat: '自然現象', level: 2, src: 'https://hp.otenki.com/367/' },
  { term: '御神渡', explain: '長野縣諏訪湖結冰後，冰面因熱脹冷縮裂開隆起成一條脊，傳統視為神明行過嘅路，近年好少出現。', cat: '自然現象', level: 3, src: 'https://www.pref.nagano.lg.jp/suwachi/suwachi-shokan/kanko/omiwatari.html' },
  { term: '樹冰', explain: '山形藏王嘅冷杉被風吹嚟嘅過冷卻水滴同雪層層包住，結成一隻隻白色怪物咁嘅冰雪塊，俗稱雪怪。', cat: '自然現象', level: 2, src: 'https://www.pref.yamagata.jp/020026/kensei/shoukai/yamagatamonogatari/shizen/juhyou.html' },
  // ---------------------------------------------------------- 奇怪動物
  { term: '盲鰻', explain: '冇下頷嘅原始魚類，受驚時會噴出大量黏液，可以令周圍嘅海水變成啫喱狀。', cat: '奇怪動物', level: 2, src: 'https://en.wikipedia.org/wiki/Hagfish' },
  { term: '皇帶魚', explain: '身體扁長似條帶嘅深海魚，可以長達八米，係世上最長嘅硬骨魚，日本人叫佢做「龍宮使者」。', cat: '奇怪動物', level: 1, src: 'https://en.wikipedia.org/wiki/Oarfish' },
  { term: '針鼴', explain: '會下蛋嘅哺乳動物，全身長滿硬刺，用長舌頭舔食螞蟻同白蟻，只喺澳洲同新幾內亞出現。', cat: '奇怪動物', level: 1, src: 'https://en.wikipedia.org/wiki/Echidna' },
  { term: '巨型管蟲', explain: '住喺深海熱泉附近，成年後冇嘴冇腸，要靠體內嘅共生細菌將硫化物變成養分。', cat: '奇怪動物', level: 3, src: 'https://en.wikipedia.org/wiki/Riftia_pachyptila' },
  { term: '海豬', explain: '深海嘅海參，用一對對管狀嘅足喺海底慢慢行，因為外形似小豬而得名。', cat: '奇怪動物', level: 3, src: 'https://en.wikipedia.org/wiki/Scotoplanes' },
  { term: '吸血鬼烏賊', explain: '住喺深海缺氧層嘅細小生物，唔係烏賊亦唔係八爪魚，遇襲時會噴出發光黏液而唔係墨汁。', cat: '奇怪動物', level: 3, src: 'https://en.wikipedia.org/wiki/Vampire_squid' },
  { term: '玻璃蛙', explain: '中南美洲嘅細小青蛙，有啲品種腹部皮膚係透明嘅，可以直接望到心臟喺入面跳動。', cat: '奇怪動物', level: 1, src: 'https://en.wikipedia.org/wiki/Glass_frog' },
  { term: '蚓螈', explain: '冇腳、外形似大蚯蚓嘅兩棲動物，有啲品種嘅BB會食媽媽嘅皮膚表層嚟長大。', cat: '奇怪動物', level: 3, src: 'https://en.wikipedia.org/wiki/Caecilian' },
  { term: '洞螈', explain: '住喺東南歐洞穴嘅盲眼兩棲動物，皮膚蒼白，最長可以十年唔食嘢都生存到。', cat: '奇怪動物', level: 2, src: 'https://en.wikipedia.org/wiki/Olm' },
  { term: '指猴', explain: '馬達加斯加嘅夜行靈長類，有條特別幼長嘅中指，會用嚟敲樹幹，聽蟲喺邊度。', cat: '奇怪動物', level: 2, src: 'https://en.wikipedia.org/wiki/Aye-aye' },
  { term: '鯨頭鸛', explain: '非洲濕地嘅大型水鳥，嘴巴似隻木鞋，可以企喺水邊一動不動，等魚浮上嚟先出手。', cat: '奇怪動物', level: 1, src: 'https://en.wikipedia.org/wiki/Shoebill' },
  { term: '藍龍海蛞蝓', explain: '喺海面倒轉浮住嘅細小海蛞蝓，會食有毒嘅僧帽水母，再將佢嘅刺細胞儲起嚟自己用。', cat: '奇怪動物', level: 1, src: 'https://en.wikipedia.org/wiki/Glaucus_atlanticus' },
  { term: '叩頭蟲', explain: '甲蟲嘅一種，仰臥時會借前胸嘅關節彈動，「嗒」一聲跳上半空，翻返正身。', cat: '奇怪動物', level: 2, src: 'https://en.wikipedia.org/wiki/Click_beetle' },
  { term: '蟻獅', explain: '幼蟲會喺沙地挖個漏斗形嘅陷阱，自己躲喺底部，等螞蟻滑落去先食。', cat: '奇怪動物', level: 2, src: 'https://en.wikipedia.org/wiki/Antlion' },
  { term: '炮甲蟲', explain: '受威脅時會喺尾部噴出接近沸騰嘅化學液體，仲伴隨住啪啪聲，似細細粒大炮。', cat: '奇怪動物', level: 2, src: 'https://en.wikipedia.org/wiki/Bombardier_beetle' },
  { term: '大王具足蟲', explain: '深海嘅巨型等足類，似放大版嘅潮蟲，日本鳥羽水族館有一隻五年冇食嘢都生存到。', cat: '奇怪動物', level: 1, src: 'https://en.wikipedia.org/wiki/Giant_isopod' },
  { term: '弓頭鯨', explain: '生活喺北極嘅鬚鯨，有個體被估計活過兩百歲，係已知最長壽嘅哺乳動物。', cat: '奇怪動物', level: 2, src: 'https://en.wikipedia.org/wiki/Bowhead_whale' },
  { term: '格陵蘭睡鯊', explain: '游得極慢嘅北大西洋同北冰洋鯊魚，估計壽命至少過兩百歲，要到大約一百五十歲先成熟。', cat: '奇怪動物', level: 2, src: 'https://en.wikipedia.org/wiki/Greenland_shark' },
  { term: '燈塔水母', explain: '細小嘅水母，受傷或者老化時可以將身體變返做幼體，所以有「不死水母」之稱。', cat: '奇怪動物', level: 1, src: 'https://en.wikipedia.org/wiki/Turritopsis_dohrnii' },
  { term: '裸鼴鼠', explain: '群居喺地下、只有一隻「女王」負責生育嘅哺乳動物，壽命可以超過三十年。', cat: '奇怪動物', level: 1, src: 'https://en.wikipedia.org/wiki/Naked_mole-rat' },
  { term: '芋螺', explain: '海螺嘅一種，會射出似魚叉嘅毒牙獵魚，部分品種嘅毒性強到可以危及人命。', cat: '奇怪動物', level: 2, src: 'https://en.wikipedia.org/wiki/Cone_snail' },
  { term: '軍艦鳥', explain: '大型海鳥，衛星追蹤發現有隻可以喺空中連續飛兩個月都唔落地，飛行時仲會一邊飛一邊瞓。', cat: '奇怪動物', level: 2, src: 'https://en.wikipedia.org/wiki/Frigatebird' },
  { term: '食火雞', explain: '新幾內亞同澳洲東北部嘅大型不飛鳥，腳趾有長約十二厘米嘅利爪，常被稱為世上最危險嘅鳥。', cat: '奇怪動物', level: 1, src: 'https://en.wikipedia.org/wiki/Cassowary' },
  { term: '魔蜥', explain: '澳洲沙漠嘅細小蜥蜴，渾身尖刺，皮膚有細小溝槽，可以將露水引到嘴角飲用。', cat: '奇怪動物', level: 2, src: 'https://en.wikipedia.org/wiki/Thorny_devil' },
  { term: '槍蝦', explain: '一邊大螯可以極速合上，射出氣泡爆破，聲音同衝擊波足以震暈甚至殺死細小嘅魚。', cat: '奇怪動物', level: 2, src: 'https://en.wikipedia.org/wiki/Pistol_shrimp' },
  { term: '桶眼魚', explain: '深海魚，頭部有個透明嘅頭罩，眼睛就喺罩入面，可以向上轉動去睇獵物。', cat: '奇怪動物', level: 3, src: 'https://en.wikipedia.org/wiki/Barreleye' },
  { term: '喙頭蜥', explain: '紐西蘭獨有嘅爬行動物，唔係真正嘅蜥蜴，頭頂有個可以感光嘅「第三隻眼」。', cat: '奇怪動物', level: 3, src: 'https://en.wikipedia.org/wiki/Tuatara' },
  { term: '藍環章魚', explain: '細到放得入手掌嘅八爪魚，受驚時身上會出現藍色圓環，唾液含有同河豚一樣嘅劇毒。', cat: '奇怪動物', level: 1, src: 'https://en.wikipedia.org/wiki/Blue-ringed_octopus' },
  { term: '水蛛', explain: '用蛛絲喺水下織成鐘形氣室、再搬空氣入去嘅蜘蛛，幾乎一生都喺水入面生活。', cat: '奇怪動物', level: 3, src: 'https://en.wikipedia.org/wiki/Diving_bell_spider' },
  { term: '長頸鹿象鼻蟲', explain: '馬達加斯加嘅甲蟲，雄蟲嘅頸比雌蟲長兩三倍，用嚟同對手較量、求偶同築巢。', cat: '奇怪動物', level: 3, src: 'https://en.wikipedia.org/wiki/Giraffe_weevil' },
  { term: '花園鰻', explain: '半條身插入沙底、豎起上半身隨水流擺動嘅鰻魚，一有危險就縮返入洞。', cat: '奇怪動物', level: 2, src: 'https://en.wikipedia.org/wiki/Garden_eel' },
  { term: '海天使', explain: '細小、身體透明嘅海蝸牛，喺冷水海域拍動翼狀嘅足游泳，日本叫佢做「流冰天使」。', cat: '奇怪動物', level: 2, src: 'https://en.wikipedia.org/wiki/Clione_limacina' },
  { term: '雪人蟹', explain: '住喺深海熱泉同冷泉附近嘅白色蟹，螯上長滿毛，毛上養住可以處理硫化物嘅細菌。', cat: '奇怪動物', level: 3, src: 'https://en.wikipedia.org/wiki/Yeti_crab' },
  { term: '皺鰓鯊', explain: '外形似鰻嘅深海鯊魚，口入面約有三百隻牙，被視為「活化石」。', cat: '奇怪動物', level: 2, src: 'https://en.wikipedia.org/wiki/Frilled_shark' },
  { term: '綠葉海蛞蝓', explain: '會食藻類，再將藻嘅葉綠體偷偷留喺自己體內，之後可以用嚟光合作用長達幾個月。', cat: '奇怪動物', level: 3, src: 'https://en.wikipedia.org/wiki/Elysia_chlorotica' },
  { term: '劍嘴蜂鳥', explain: '南美安第斯山脈嘅蜂鳥，係已知唯一嘴巴長過身體（唔計尾）嘅鳥，要用腳嚟梳理羽毛。', cat: '奇怪動物', level: 3, src: 'https://en.wikipedia.org/wiki/Sword-billed_hummingbird' },
  { term: '日本大鯢', explain: '日本嘅特別天然紀念物，最長可以去到一米半，日文叫「大山椒魚」，住喺西日本清涼嘅河川。', cat: '奇怪動物', level: 2, src: 'https://en.wikipedia.org/wiki/Japanese_giant_salamander' },
  { term: '高足蟹', explain: '日本近海嘅深海巨蟹，兩隻螯張開可以闊達三米半以上，係腳展最闊嘅節肢動物。', cat: '奇怪動物', level: 2, src: 'https://en.wikipedia.org/wiki/Japanese_spider_crab' },
  // ---------------------------------------------------------- 奇怪植物
  { term: '貉藻', explain: '冇根、浮喺水中嘅食蟲植物，葉片似捕蠅草咁會夾埋，專門捕捉水中嘅細小生物。', cat: '奇怪植物', level: 3, src: 'https://en.wikipedia.org/wiki/Aldrovanda' },
  { term: '狸藻', explain: '食蟲植物，細小嘅捕蟲囊可以喺十幾毫秒內吸入獵物，係植物界最快嘅陷阱之一。', cat: '奇怪植物', level: 3, src: 'https://en.wikipedia.org/wiki/Utricularia' },
  { term: '生石花', explain: '南非嘅多肉植物，外形似一粒粒圓石仔，靠偽裝成石頭嚟避開被動物食。', cat: '奇怪植物', level: 1, src: 'https://en.wikipedia.org/wiki/Lithops' },
  { term: '千歲蘭', explain: '納米比亞同安哥拉沿岸沙漠嘅植物，一生只長兩塊會不斷生長嘅葉，有估計壽命過千年。', cat: '奇怪植物', level: 3, src: 'https://en.wikipedia.org/wiki/Welwitschia' },
  { term: '索科特拉龍血樹', explain: '只喺也門索科特拉群島生長嘅樹，樹冠密實似把撐開嘅傘，樹脂係暗紅色，叫做龍血。', cat: '奇怪植物', level: 3, src: 'https://en.wikipedia.org/wiki/Dracaena_cinnabari' },
  { term: '沙盒樹', explain: '美洲熱帶嘅樹，果實成熟後會「嘭」一聲爆開，將種子以時速約二百五十公里射走，又叫炸藥樹。', cat: '奇怪植物', level: 2, src: 'https://en.wikipedia.org/wiki/Hura_crepitans' },
  { term: '噴瓜', explain: '地中海一帶嘅野生植物，果實成熟後會連汁帶種子噴射出去，種子可以射到七八米遠。', cat: '奇怪植物', level: 2, src: 'https://en.wikipedia.org/wiki/Ecballium_elaterium' },
  { term: '跳舞草', explain: '豆科植物，日間氣溫高過二十二度時，細小嘅側葉會自己不停轉動，睇落好似喺度跳舞。', cat: '奇怪植物', level: 1, src: 'https://en.wikipedia.org/wiki/Codariocalyx_motorius' },
  { term: '菟絲子', explain: '葉綠素極少嘅纏繞藤蔓，會用吸器插入其他植物吸取養分，種子亦係一種中藥材。', cat: '奇怪植物', level: 2, src: 'https://en.wikipedia.org/wiki/Cuscuta' },
  { term: '蜂蘭', explain: '蘭花嘅一屬，花形同氣味模仿雌蜂，誘使雄蜂飛嚟停留，藉此幫自己授粉。', cat: '奇怪植物', level: 2, src: 'https://en.wikipedia.org/wiki/Ophrys' },
  { term: '潘多顫楊林', explain: '美國猶他州嘅一大片顫楊林，其實全部係同一株，靠根部相連，估計重達六千噸。', cat: '奇怪植物', level: 2, src: 'https://en.wikipedia.org/wiki/Pando_(tree)' },
  { term: '神秘果', explain: '西非嘅小紅果，食完之後酸嘢會變甜，因為果肉嘅蛋白質令味蕾將酸味當成甜味。', cat: '奇怪植物', level: 1, src: 'https://en.wikipedia.org/wiki/Synsepalum_dulcificum' },
  { term: '王蓮', explain: '亞馬遜嘅水生植物，浮葉直徑可近三米，葉底長滿細刺，有紀錄一片葉承托過超過一百公斤嘅重量。', cat: '奇怪植物', level: 1, src: 'https://en.wikipedia.org/wiki/Victoria_amazonica' },
  { term: '復活草', explain: '遇旱會捲成一團乾枯嘅球，一落水就喺幾個鐘內舒展返綠色，所以有「復活」之名。', cat: '奇怪植物', level: 2, src: 'https://en.wikipedia.org/wiki/Selaginella_lepidophylla' },
  { term: '牛角金合歡', explain: '中美洲嘅樹，長有空心大刺俾螞蟻居住，螞蟻就負責攻擊想食樹葉嘅動物。', cat: '奇怪植物', level: 3, src: 'https://en.wikipedia.org/wiki/Vachellia_cornigera' },
  { term: '水晶蘭', explain: '全身白色、冇葉綠素嘅植物，唔靠光合作用，而係透過地下嘅真菌攝取養分。', cat: '奇怪植物', level: 3, src: 'https://en.wikipedia.org/wiki/Monotropa_uniflora' },
  { term: '彩虹桉', explain: '樹皮會逐塊剝落，露出綠、藍、紫、橙色嘅新樹皮，似畫咗彩色圖案嘅樹。', cat: '奇怪植物', level: 1, src: 'https://en.wikipedia.org/wiki/Eucalyptus_deglupta' },
  { term: '無根萍', explain: '浮喺水面、細過一粒米嘅植物，係世上最細嘅開花植物之一，冇根亦冇分明嘅莖葉。', cat: '奇怪植物', level: 3, src: 'https://en.wikipedia.org/wiki/Wolffia' },
  { term: '猴面蘭', explain: '花形似猴子面孔嘅蘭花，產於厄瓜多爾嘅雲霧林，據說聞落有熟橙嘅味道。', cat: '奇怪植物', level: 3, src: 'https://en.wikipedia.org/wiki/Dracula_simia' },
  { term: '海椰子', explain: '塞舌爾獨有嘅棕櫚，種子係世上最大最重嘅種子，單粒可以重達十幾二十公斤。', cat: '奇怪植物', level: 1, src: 'https://en.wikipedia.org/wiki/Coco_de_mer' },
  { term: '幽靈蘭', explain: '佛羅里達同古巴濕地嘅無葉蘭花，靠扁平嘅綠色氣根進行光合作用，花形似跳緊嘅青蛙。', cat: '奇怪植物', level: 3, src: 'https://en.wikipedia.org/wiki/Dendrophylax_lindenii' },
  { term: '屋久杉', explain: '日本屋久島樹齡過千年嘅杉樹，島民將較年輕嘅叫小杉，最著名嘅繩文杉估計有二千多歲。', cat: '奇怪植物', level: 2, src: 'https://ja.wikipedia.org/wiki/%E5%B1%8B%E4%B9%85%E6%9D%89' },
  // ---------------------------------------------------------- 歷史冷知識
  { term: '豬戰爭', explain: '1859年英美兩國為爭奪聖胡安群島差啲開戰，導火線係一頭闖入菜園被射死嘅豬，全場冇人死，淨係死咗豬。', cat: '歷史冷知識', level: 1, src: 'https://en.wikipedia.org/wiki/Pig_War_(1859)' },
  { term: '糕點戰爭', explain: '1838年法國出兵墨西哥，其中一個藉口，係一位法籍糕點師傅投訴自己間舖頭曾被墨西哥軍官洗劫。', cat: '歷史冷知識', level: 1, src: 'https://en.wikipedia.org/wiki/Pastry_War' },
  { term: '鴯鶓戰爭', explain: '1932年澳洲派軍人帶機關槍對付農田裏成千上萬隻鴯鶓（一種大型走禽），軍人撤走後，鴯鶓照樣破壞農作物。', cat: '歷史冷知識', level: 1, src: 'https://en.wikipedia.org/wiki/Emu_War' },
  { term: '威士忌戰爭', explain: '加拿大同丹麥爭奪一個北極小島，加方上島會插旗兼留低一瓶加拿大威士忌，到2022年兩國同意平分個島。', cat: '歷史冷知識', level: 2, src: 'https://en.wikipedia.org/wiki/Hans_Island' },
  { term: '托萊多戰爭', explain: '1835年美國俄亥俄州同密歇根準州為咗一條土地帶對峙，雙方出動民兵，冇人死亡，密歇根最後獲補償上半島。', cat: '歷史冷知識', level: 3, src: 'https://en.wikipedia.org/wiki/Toledo_War' },
  { term: '鱈魚戰爭', explain: '冰島同英國為咗捕魚範圍多次對峙，冰島海岸警衛隊會用特製工具，割斷英國漁船嘅拖網鋼纜。', cat: '歷史冷知識', level: 2, src: 'https://en.wikipedia.org/wiki/Cod_Wars' },
  { term: '西蘭公國', explain: '1967年一個英國人佔據北海一座二戰海上炮台，自行宣佈立國，仲印過護照同貨幣，但冇國家正式承認。', cat: '歷史冷知識', level: 1, src: 'https://en.wikipedia.org/wiki/Principality_of_Sealand' },
  { term: '窗戶稅', explain: '英國由1696年到1851年按屋企窗口數量徵稅，有屋主因此封窗慳稅，不過今日見到嘅封窗，唔一定同呢個稅有關。', cat: '歷史冷知識', level: 1, src: 'https://en.wikipedia.org/wiki/Window_tax' },
  { term: '鬍鬚稅', explain: '俄國沙皇彼得一世推行鬍鬚稅，留鬍鬚嘅人交咗稅，會獲發一個銅或銀嘅「鬍鬚牌」，要隨身攜帶。', cat: '歷史冷知識', level: 1, src: 'https://en.wikipedia.org/wiki/Beard_tax' },
  { term: '尿液稅', explain: '古羅馬皇帝韋斯巴薌重新徵收尿液稅，向收集公廁尿液嘅人徵稅；據記載佢仲話：錢唔臭。', cat: '歷史冷知識', level: 1, src: 'https://en.wikipedia.org/wiki/Vespasian' },
  { term: '倫島', explain: '1667年荷蘭同英國簽約，英國保住曼哈頓，荷蘭就得到印尼一個盛產肉豆蔻嘅細島，即係倫島。', cat: '歷史冷知識', level: 2, src: 'https://en.wikipedia.org/wiki/Run_(island)' },
  { term: '雅浦島石幣', explain: '密克羅尼西亞雅浦島用巨大嘅圓形石頭做貨幣，有啲大到搬唔郁，買賣後只靠口頭記錄轉換擁有人，石頭通常原地不動。', cat: '歷史冷知識', level: 2, src: 'https://en.wikipedia.org/wiki/Rai_stones' },
  { term: '1712年2月30日', explain: '瑞典真係出現過嘅日子：1700年佢哋跳過閏日，1712年為咗調返用舊曆，二月加多一日變成30日。', cat: '歷史冷知識', level: 3, src: 'https://en.wikipedia.org/wiki/Swedish_calendar' },
  { term: '消失嘅十一日', explain: '1752年英國同殖民地改用新曆，9月2日之後直接係9月14日，中間十一日喺曆法上消失。', cat: '歷史冷知識', level: 2, src: 'https://en.wikipedia.org/wiki/Calendar_(New_Style)_Act_1750' },
  { term: '黑便士', explain: '世上第一款公共郵政使用嘅黏貼式郵票，1840年5月英國發行，面額一便士，圖案係維多利亞女王嘅側面像。', cat: '歷史冷知識', level: 2, src: 'https://en.wikipedia.org/wiki/Penny_Black' },
  { term: '奧運水中障礙賽', explain: '1900年巴黎奧運有過游泳障礙賽，選手要喺塞納河爬過一枝竿同一排船，再由另一排船下面游過，之後冇再出現。', cat: '歷史冷知識', level: 3, src: 'https://en.wikipedia.org/wiki/Swimming_at_the_1900_Summer_Olympics_%E2%80%93_Men%27s_200_metre_obstacle_event' },
  { term: '1904年奧運馬拉松', explain: '1904年聖路易斯奧運馬拉松，有選手跑到一半搭咗一段車，一度被當成冠軍，後來被取消資格。', cat: '歷史冷知識', level: 2, src: 'https://en.wikipedia.org/wiki/Athletics_at_the_1904_Summer_Olympics_%E2%80%93_Men%27s_marathon' },
  { term: '犬公方', explain: '江戶幕府第五代將軍德川綱吉嘅外號，因為佢頒布法令嚴格保護動物，尤其係狗，惹來好多爭議。', cat: '歷史冷知識', level: 3, src: 'https://en.wikipedia.org/wiki/Tokugawa_Tsunayoshi' },
  { term: '參勤交代', explain: '江戶幕府規定大名要定期輪流住喺江戶同領地，妻兒仲要長期留喺江戶做人質，開支令各藩好吃力。', cat: '歷史冷知識', level: 2, src: 'https://en.wikipedia.org/wiki/Sankin-k%C5%8Dtai' },
  { term: '刀狩', explain: '1588年豐臣秀吉下令向農民收繳刀劍同武器，官方話法係拎去熔咗做京都大佛殿嘅釘同扣件。', cat: '歷史冷知識', level: 2, src: 'https://en.wikipedia.org/wiki/Sword_hunt' },
  { term: '倫敦大惡臭', explain: '1858年夏天泰晤士河污水臭氣熏天，國會窗簾要浸石灰氯水遮臭，之後促成倫敦興建新下水道系統。', cat: '歷史冷知識', level: 2, src: 'https://en.wikipedia.org/wiki/Great_Stink' },
  { term: '鐵路時間', explain: '19世紀英國各地時間唔同，1840年大西部鐵路率先統一採用倫敦時間，叫鐵路時間。', cat: '歷史冷知識', level: 3, src: 'https://en.wikipedia.org/wiki/Railway_time' },
  { term: '法國十進制時間', explain: '法國大革命期間曾規定一日有十個鐘頭、一個鐘頭有一百分鐘，1795年暫停咗強制使用。', cat: '歷史冷知識', level: 2, src: 'https://en.wikipedia.org/wiki/Decimal_time' },
  { term: '特諾奇提特蘭', explain: '阿茲特克帝國嘅首都，傳統上話1325年建喺湖中島上，今日嘅墨西哥城市中心就係佢嘅舊址。', cat: '歷史冷知識', level: 2, src: 'https://en.wikipedia.org/wiki/Tenochtitlan' },
  { term: '維克多·拉斯提格', explain: '20世紀初嘅騙徒，1925年喺巴黎冒充政府官員，將艾菲爾鐵塔當廢鐵賣俾商人，之後仲回頭再試多次。', cat: '歷史冷知識', level: 2, src: 'https://en.wikipedia.org/wiki/Victor_Lustig' },
  { term: '諾頓一世', explain: '19世紀舊金山有人自封「美國皇帝」，市民好包容佢，有餐廳仲肯收佢自己發行嘅「鈔票」。', cat: '歷史冷知識', level: 2, src: 'https://en.wikipedia.org/wiki/Emperor_Norton' },
  { term: '溫尼辟黑熊', explain: '一戰時一位加拿大軍隊獸醫買咗隻小黑熊做吉祥物，後來養喺倫敦動物園，啟發咗《小熊維尼》嘅名。', cat: '歷史冷知識', level: 1, src: 'https://en.wikipedia.org/wiki/Winnipeg_(bear)' },
  { term: '特洛伊房咖啡壺', explain: '劍橋大學電腦系1991年架設攝影機對住咖啡壺，等同事唔使白行一轉，成為世上第一個網絡攝影機。', cat: '歷史冷知識', level: 2, src: 'https://en.wikipedia.org/wiki/Trojan_Room_coffee_pot' },
  { term: '月球大騙局', explain: '1835年《紐約太陽報》連載文章，聲稱喺月球發現長翼人形生物同獨角獸，同年9月承認係虛構。', cat: '歷史冷知識', level: 1, src: 'https://en.wikipedia.org/wiki/Great_Moon_Hoax' },
  { term: '皮爾當人', explain: '1912年英國公佈發現嘅「史前人類」頭骨，到1953年先揭穿係假貨，原來係人類頭骨配紅毛猩猩下顎。', cat: '歷史冷知識', level: 2, src: 'https://en.wikipedia.org/wiki/Piltdown_Man' },
  { term: '科廷利仙子', explain: '1917年兩個英國表姊妹影到「仙子」相片，連柯南道爾都信，1980年代先承認係用紙剪貼影出嚟。', cat: '歷史冷知識', level: 2, src: 'https://en.wikipedia.org/wiki/Cottingley_Fairies' },
  { term: '薯仔戰爭', explain: '1778至1779年奧地利同普魯士為咗巴伐利亞繼承權開戰，冇大型戰役，雙方主要突襲同就地搵糧，後世戲稱薯仔戰爭。', cat: '歷史冷知識', level: 3, src: 'https://en.wikipedia.org/wiki/War_of_the_Bavarian_Succession' },
  { term: '比爾泰維勒', explain: '埃及同蘇丹邊境有塊約2000平方公里嘅土地，因為兩國對邊界嘅定義唔同，雙方都唔要，變成冇國家認領嘅地方。', cat: '歷史冷知識', level: 3, src: 'https://en.wikipedia.org/wiki/Bir_Tawil' },
  { term: '自由蘭', explain: '2015年有人喺多瑙河畔一塊約七平方公里嘅荒地宣佈立國，聲稱因克羅地亞同塞爾維亞邊界爭議而無主，但冇聯合國成員國承認。', cat: '歷史冷知識', level: 3, src: 'https://en.wikipedia.org/wiki/Liberland' },
  { term: '牛津比阿茲特克老', explain: '牛津大學早喺1096年已有教學活動，比阿茲特克人建立都城特諾奇提特蘭（傳統話1325年）仲要早。', cat: '歷史冷知識', level: 2, src: 'https://en.wikipedia.org/wiki/University_of_Oxford' },
  // ---------------------------------------------------------- 世界怪習俗與節日
  { term: '啼哭相撲', explain: '日本神社活動，力士抱住嬰兒做鬼臉扮聲嚇佢，邊個嬰兒先喊就贏，傳統相信大聲喊可驅走邪靈。', cat: '世界怪習俗與節日', level: 2, src: 'https://en.wikipedia.org/wiki/Naki_Sumo_Crying_Baby_Festival' },
  { term: '生剝鬼', explain: '日本秋田縣男鹿半島大除夕習俗，村民扮鬼拎住木刀逐家逐戶大喊「有冇喊包」，嚇唬細路要乖。', cat: '世界怪習俗與節日', level: 2, src: 'https://en.wikipedia.org/wiki/Namahage' },
  { term: '七草粥', explain: '日本人喺1月7日食用七種春季野菜煮成嘅粥，源自中國習俗，寓意健康長壽同驅邪。', cat: '世界怪習俗與節日', level: 1, src: 'https://en.wikipedia.org/wiki/Nanakusa-no-sekku' },
  { term: '柊鰯', explain: '日本節分習俗，將烤過嘅沙甸魚頭插喺柊樹（葉有尖刺）枝上掛喺門口，用魚腥味同尖刺葉嚇走鬼怪。', cat: '世界怪習俗與節日', level: 2, src: 'https://en.wikipedia.org/wiki/Setsubun' },
  { term: '扮鬼臉大賽', explain: '英格蘭埃格勒蒙特蟹市集嘅傳統比賽，參賽者要將面穿過一個馬頸圈，扮出最扭曲嘅表情。', cat: '世界怪習俗與節日', level: 3, src: 'https://en.wikipedia.org/wiki/Gurn' },
  { term: '泥沼浮潛', explain: '威爾斯小鎮比賽，參賽者戴潛水鏡同蛙鞋，喺泥炭沼澤挖出嘅水溝游兩個長度（共110米），唔准用正常泳姿。', cat: '世界怪習俗與節日', level: 3, src: 'https://en.wikipedia.org/wiki/Bog_snorkelling' },
  { term: '腳趾摔角', explain: '英國比賽，兩人脫鞋後用腳趾互相鉤住壓低對方隻腳，由一班因世界盃失意嘅酒客發明，首屆冠軍竟然係加拿大人。', cat: '世界怪習俗與節日', level: 2, src: 'https://en.wikipedia.org/wiki/Toe_wrestling' },
  { term: '踢小腿比賽', explain: '英格蘭科茨沃爾德傳統比賽，兩人互相揪住對方衣領或肩膀，用腳內側踢對方小腿，現代比賽要塞稻草入褲管保護。', cat: '世界怪習俗與節日', level: 2, src: 'https://en.wikipedia.org/wiki/Shin-kicking' },
  { term: '擲血腸比賽', explain: '英國拉姆斯博頓每年九月舉行，參賽者用下手擲三條血腸，打跌放喺六米高平台上嘅約克夏布甸，跌得最多者勝。', cat: '世界怪習俗與節日', level: 2, src: 'https://en.wikipedia.org/wiki/World_Black_Pudding_Throwing_Championships' },
  { term: '羊毛袋賽跑', explain: '英國泰特伯里小鎮每年五月尾假期舉行，男子組要揹住約27公斤重嘅羊毛袋，沿鎮上最斜嗰條街跑上山。', cat: '世界怪習俗與節日', level: 3, src: 'https://en.wikipedia.org/wiki/Tetbury_Woolsack_Races' },
  { term: '鄧莫鹹肉審判', explain: '英國埃塞克斯大鄧莫小鎮嘅古老傳統：夫婦要證明結婚一年零一日都冇後悔、冇爭執，就可以贏一大塊鹹肉。', cat: '世界怪習俗與節日', level: 3, src: 'https://en.wikipedia.org/wiki/Flitch_of_bacon_custom' },
  { term: '天鵝點算', explain: '每年七月喺泰晤士河進行嘅儀式，專人划小艇點算同檢查天鵝，因為河上未標記嘅疣鼻天鵝傳統上屬君主所有。', cat: '世界怪習俗與節日', level: 3, src: 'https://en.wikipedia.org/wiki/Swan_upping' },
  { term: '倫敦塔鑰匙儀式', explain: '倫敦塔每晚鎖大門嘅儀式，據稱係世上現存最古老嘅軍事儀式，由首席守衛長提住燈籠同鑰匙，帶衛兵完成。', cat: '世界怪習俗與節日', level: 2, src: 'https://en.wikipedia.org/wiki/Ceremony_of_the_Keys_(London)' },
  { term: '倫敦塔渡鴉', explain: '倫敦塔至少養六隻渡鴉，傳說渡鴉一飛走王國就會倒下，仲有專人叫「渡鴉長」負責照顧。', cat: '世界怪習俗與節日', level: 1, src: 'https://en.wikipedia.org/wiki/Ravens_of_the_Tower_of_London' },
  { term: '伯恩斯之夜', explain: '蘇格蘭人每年1月25日前後紀念詩人伯恩斯嘅晚宴，要朗誦一首專為名菜 haggis 而寫嘅詩，仲要拔刀劃開個 haggis。', cat: '世界怪習俗與節日', level: 2, src: 'https://en.wikipedia.org/wiki/Burns_supper' },
  { term: 'First-foot', explain: '蘇格蘭同英國北部新年習俗，新年第一個踏入屋嘅人，最好係高大黑髮男士，仲要帶煤、鹽或威士忌等禮物。', cat: '世界怪習俗與節日', level: 3, src: 'https://en.wikipedia.org/wiki/First-foot' },
  { term: '斯通黑文火球節', explain: '蘇格蘭海邊小鎮除夕活動，村民揮舞住自製嘅燃燒火球行過大街，最後將火球擲入海港。', cat: '世界怪習俗與節日', level: 3, src: 'https://en.wikipedia.org/wiki/Stonehaven' },
  { term: 'Loony Dook', explain: '蘇格蘭南昆斯費里每年元旦，大家着住奇裝異服跳落冰凍嘅福斯灣，1986年由三個人開玩笑提議醒酒。', cat: '世界怪習俗與節日', level: 3, src: 'https://en.wikipedia.org/wiki/Loony_Dook' },
  { term: '設得蘭火祭', explain: '蘇格蘭設得蘭群島每年一月最後一個星期二嘅火祭，成隊人舉火炬遊行，最後將火炬擲入一艘仿製維京長船燒掉。', cat: '世界怪習俗與節日', level: 2, src: 'https://en.wikipedia.org/wiki/Up_Helly_Aa' },
  { term: '哈克西罩帽', explain: '英國林肯郡每年1月6日，一大班人擠成「Sway」互相推撞，要將一個皮筒推去四間酒吧其中一間，酒吧老闆喺門口摸到先算完。', cat: '世界怪習俗與節日', level: 3, src: 'https://en.wikipedia.org/wiki/Haxey_Hood' },
  { term: '引蚯蚓比賽', explain: '英國有人搞嘅比賽，參賽者喺三米見方嘅泥地上，唔准挖泥，只可用震動或音樂引蚯蚓爬出地面，引到最多者勝。', cat: '世界怪習俗與節日', level: 3, src: 'https://en.wikipedia.org/wiki/Worm_charming' },
  { term: '馬栗大賽', explain: '英國北安普敦郡每年10月舉行，兩人輪流用繩穿住嘅馬栗互相擊打，打爛對方嘅就晉級。', cat: '世界怪習俗與節日', level: 2, src: 'https://en.wikipedia.org/wiki/World_Conker_Championships' },
  { term: '撐竿跳溝', explain: '荷蘭弗里斯蘭傳統運動，用長竿撐過運河，要沿桿爬到頂再跳落對岸沙堆，名字意思係「遠跳」。', cat: '世界怪習俗與節日', level: 3, src: 'https://en.wikipedia.org/wiki/Fierljeppen' },
  { term: '賓什吉勒', explain: '比利時賓什狂歡節，戴鴕鳥羽毛大帽嘅「吉勒」會向人群擲橙，收到嘅人要當係禮物，擲返轉頭係無禮。', cat: '世界怪習俗與節日', level: 2, src: 'https://en.wikipedia.org/wiki/Carnival_of_Binche' },
  { term: '伊夫雷亞橙戰', explain: '意大利北部小鎮嘅嘉年華，市民分成步行隊同馬車隊用橙互相狂擲，被稱為意大利最大規模嘅食物大戰。', cat: '世界怪習俗與節日', level: 1, src: 'https://en.wikipedia.org/wiki/Carnival_of_Ivrea' },
  { term: '加泰隆尼亞人塔', explain: '西班牙加泰隆尼亞嘅傳統，一班人踩住肩膀疊成幾層高嘅人塔，2010年仲被聯合國教科文組織列為非遺。', cat: '世界怪習俗與節日', level: 1, src: 'https://en.wikipedia.org/wiki/Castell' },
  { term: '麵粉政變節', explain: '西班牙伊比鎮12月28日，居民扮軍人「奪權」，互擲麵粉同雞蛋，仲向途人「罰款」，唔交就要「坐監」。', cat: '世界怪習俗與節日', level: 3, src: 'https://en.wikipedia.org/wiki/Els_Enfarinats' },
  { term: '蘿蔔之夜', explain: '墨西哥瓦哈卡每年12月23日嘅活動，居民將巨型蘿蔔雕成人物同場景比賽，蘿蔔係西班牙人引入嘅。', cat: '世界怪習俗與節日', level: 2, src: 'https://en.wikipedia.org/wiki/Night_of_the_Radishes' },
  { term: 'Tejo', explain: '哥倫比亞國民運動，玩家擲金屬餅去約18.5米外一塊泥板，擊中放咗火藥嘅小紙包就會爆炸得分。', cat: '世界怪習俗與節日', level: 3, src: 'https://en.wikipedia.org/wiki/Tejo_(sport)' },
  { term: '保寧泥漿節', explain: '南韓大川海灘嘅夏季節慶，1998年起辦，原本係為推廣保寧泥漿化妝品而設。', cat: '世界怪習俗與節日', level: 1, src: 'https://en.wikipedia.org/wiki/Boryeong_Mud_Festival' },
  { term: '黑色情人節', explain: '南韓單身人士嘅非官方節日，4月14日，冇收到情人節同白色情人節禮物嘅人會一齊食黑色嘅炸醬麵。', cat: '世界怪習俗與節日', level: 1, src: 'https://en.wikipedia.org/wiki/Black_Day_(South_Korea)' },
  { term: '寧靜日', explain: '峇里島新年嘅「寧靜日」，全島要靜默一日，唔准出街、唔准去海灘，連唯一嘅機場都關閉。', cat: '世界怪習俗與節日', level: 1, src: 'https://en.wikipedia.org/wiki/Nyepi' },
  { term: '陸上跳水', explain: '瓦努阿圖彭特科斯特島男人喺二三十米高木塔，將藤蔓綁住腳踝跳落地，常被視為蹦極嘅前身。', cat: '世界怪習俗與節日', level: 1, src: 'https://en.wikipedia.org/wiki/Land_diving' },
  { term: '土耳其油摔角', explain: '土耳其艾迪爾內嘅傳統摔角，選手只着皮短褲，賽前將橄欖油淋滿全身，主辦方話自1360年已經舉行。', cat: '世界怪習俗與節日', level: 2, src: 'https://en.wikipedia.org/wiki/K%C4%B1rkp%C4%B1nar' },
  { term: '聖誕書洪流', explain: '冰島聖誕前出版商集中推出新書，平安夜送書成為習俗，書係全國最受歡迎嘅聖誕禮物。', cat: '世界怪習俗與節日', level: 3, src: 'https://en.wikipedia.org/wiki/Icelandic_Christmas_book_flood' },
  { term: '倒錫占卜', explain: '德國等地嘅除夕習俗，將熔化嘅鉛（今多用錫）倒入冷水，再按凝固成嘅形狀預測新一年運勢。', cat: '世界怪習俗與節日', level: 3, src: 'https://en.wikipedia.org/wiki/Molybdomancy' },
  { term: '入學糖果筒', explain: '德國細路第一日返小學，會收到一個大圓錐筒，入面裝滿糖果、玩具同文具，德文叫 Schultüte。', cat: '世界怪習俗與節日', level: 2, src: 'https://en.wikipedia.org/wiki/Schult%C3%BCte' },
  { term: '砸碎瓷器', explain: '德國婚禮前夕嘅習俗，賓客同新人一齊摔碎瓷器（唔摔玻璃），相信「碎片帶嚟好運」，之後新人要自己掃走。', cat: '世界怪習俗與節日', level: 3, src: 'https://en.wikipedia.org/wiki/Polterabend' },
  { term: 'Dinner for One', explain: '1963年喺德國錄製嘅英文喜劇短片，成為好多歐洲國家除夕必播節目，但英國本土反而冇乜人識。', cat: '世界怪習俗與節日', level: 2, src: 'https://en.wikipedia.org/wiki/Dinner_for_One' },
  { term: '蘇黎世六鐘節', explain: '瑞士蘇黎世春季節慶，要燒掉一個雪人木偶，據講木偶個頭爆炸得越快，當年夏天就越暖。', cat: '世界怪習俗與節日', level: 3, src: 'https://en.wikipedia.org/wiki/Sechsel%C3%A4uten' },
  { term: '下山牛', explain: '阿爾卑斯山區秋天將牛群由高山牧場趕落山嘅活動，如果夏天冇意外，牛隻會戴上華麗花飾。', cat: '世界怪習俗與節日', level: 3, src: 'https://en.wikipedia.org/wiki/Almabtrieb' },
  { term: '山羊國王', explain: '愛爾蘭基勒格林每年8月10至12日嘅傳統，由「Puck皇后」為一隻捉嚟嘅野山羊加冕做「國王」，放上高台展示。', cat: '世界怪習俗與節日', level: 3, src: 'https://en.wikipedia.org/wiki/Puck_Fair' },
  { term: '愛爾蘭媒人節', explain: '愛爾蘭利斯杜恩瓦爾納小鎮每年九月舉行，據記載自1857年起已有，現任媒人係第四代，每年吸引數萬單身男女。', cat: '世界怪習俗與節日', level: 3, src: 'https://en.wikipedia.org/wiki/Lisdoonvarna' },
  { term: '艾斯特福德', explain: '威爾斯嘅詩歌音樂節，寫出最佳嚴格格律詩嘅詩人會獲頒「詩人寶座」，並被請上台坐上詩人椅。', cat: '世界怪習俗與節日', level: 3, src: 'https://en.wikipedia.org/wiki/Eisteddfod' },
  { term: '酸鯡魚開罐日', explain: '瑞典曾有法令禁止八月第三個星期四前賣當年嘅酸鯡魚罐頭，法令雖已廢除，商店仍跟呢個日期開賣。', cat: '世界怪習俗與節日', level: 2, src: 'https://en.wikipedia.org/wiki/Surstr%C3%B6mming' },
  { term: 'Kiiking', explain: '愛沙尼亞運動，運動員綁住雙腳喺鋼臂鞦韆上擺盪，要轉足360度過頂，鞦韆臂越長越難，臂最長仲轉到過頂者勝。', cat: '世界怪習俗與節日', level: 3, src: 'https://en.wikipedia.org/wiki/Kiiking' },
  { term: '錫耶納賽馬節', explain: '意大利錫耶納每年7月2日同8月16日舉行，十個區代表喺廣場無鞍策騎跑三圈，馬匹冇咗騎師都可以贏。', cat: '世界怪習俗與節日', level: 2, src: 'https://en.wikipedia.org/wiki/Palio_di_Siena' },
  { term: '巴塞爾晨曲', explain: '瑞士巴塞爾嘉年華星期一凌晨四點開場，全個舊城熄燈，淨係靠燈籠同短笛、軍鼓遊行。', cat: '世界怪習俗與節日', level: 3, src: 'https://en.wikipedia.org/wiki/Basler_Fasnacht' },
  { term: '庫倫特節', explain: '斯洛文尼亞普圖伊嘅傳統，人們穿上厚羊皮、掛住大鈴鐺扮「Kurent」，相信啲鈴聲可以趕走冬天。', cat: '世界怪習俗與節日', level: 3, src: 'https://en.wikipedia.org/wiki/Kurentovanje' },
  { term: '蝦宴', explain: '瑞典八月嘅傳統小龍蝦派對，大家戴紙帽、圍紙圍兜食冷嘅煮小龍蝦，仲會一邊飲酒一邊唱飲酒歌。', cat: '世界怪習俗與節日', level: 3, src: 'https://en.wikipedia.org/wiki/Crayfish_party' },
  { term: '聖誕小子', explain: '冰島有十三個「聖誕小子」，聖誕前十三晚逐個出現，喺細路擺喺窗台嘅鞋入面留禮物，唔乖嘅會收到爛薯仔。', cat: '世界怪習俗與節日', level: 2, src: 'https://en.wikipedia.org/wiki/Yule_Lads' },
  // ---------------------------------------------------------- 奇怪法律
  { term: '印第安納圓周率法案', explain: '1897年美國印第安納州眾議院無異議通過法案，想以立法「解決」化圓為方，條文隱含錯誤圓周率，參議院無限期擱置。', cat: '奇怪法律', level: 3, src: 'https://en.wikipedia.org/wiki/Indiana_pi_bill' },
  { term: '醉酒看管牛隻', explain: '英國喺公眾地方醉酒時照顧牛、馬、馬車或蒸汽機，屬於違法，條文源自1872年酒牌法，至今仍然有效。', cat: '奇怪法律', level: 2, src: 'https://en.wikipedia.org/wiki/Licensing_Act_1872' },
  { term: '處理鮭魚罪', explain: '英國《1986年鮭魚法》有條罪名叫「喺可疑情況下處理鮭魚」，明知或有理由相信魚係非法捕獲仍然經手就犯法。', cat: '奇怪法律', level: 2, src: 'https://en.wikipedia.org/wiki/Salmon_Act_1986' },
  { term: '皇家魚', explain: '英國法律下，鯨魚同鱘魚被稱為「皇家魚」，喺英國海岸被捕獲或擱淺後名義上屬君主，依據係1324年嘅法規。', cat: '奇怪法律', level: 2, src: 'https://en.wikipedia.org/wiki/Royal_fish' },
  { term: '紅旗法', explain: '英國1865年嘅法例，規定路上行駛嘅蒸汽機車要有人揸紅旗行喺前面六十碼開路，市區時速限兩英里。', cat: '奇怪法律', level: 1, src: 'https://en.wikipedia.org/wiki/Locomotive_Acts' },
  { term: '孤獨天竺鼠', explain: '瑞士法律視天竺鼠為群居動物，單獨飼養一隻屬違法，所以有服務出租天竺鼠，俾失去同伴嘅天竺鼠暫時有伴。', cat: '奇怪法律', level: 1, src: 'https://en.wikipedia.org/wiki/Guinea_pig' },
  { term: '植物尊嚴', explain: '瑞士憲法要求處理動物、植物同其他生物時顧及「造物嘅尊嚴」，聯邦倫理委員會仲專門研究過植物嘅尊嚴。', cat: '奇怪法律', level: 3, src: 'https://en.wikipedia.org/wiki/Plant_rights' },
  { term: '冰島啤酒禁令', explain: '冰島曾經禁止酒精度2.25%以上嘅啤酒超過七十年，直到1989年3月1日解禁，呢日之後成為「啤酒日」。', cat: '奇怪法律', level: 2, src: 'https://en.wikipedia.org/wiki/Prohibition_in_Iceland' },
  { term: '冰島姓名委員會', explain: '冰島有委員會審批人名，不在名單上嘅新名要符合冰島語文法同傳統，唔通過就用唔到。', cat: '奇怪法律', level: 1, src: 'https://en.wikipedia.org/wiki/Icelandic_Naming_Committee' },
  { term: '全民通行權', explain: '瑞典、挪威、芬蘭等北歐國家傳統，容許人喺私人土地上行山、露營同採野莓，只要唔騷擾業主。', cat: '奇怪法律', level: 1, src: 'https://en.wikipedia.org/wiki/Freedom_to_roam' },
  { term: '斯瓦爾巴免簽', explain: '斯瓦爾巴受國際條約規管，條約簽署國公民都可以喺度居住同工作，毋須簽證，不過要經挪威本土前往。', cat: '奇怪法律', level: 3, src: 'https://en.wikipedia.org/wiki/Svalbard_Treaty' },
  { term: '禁廣告牌四州', explain: '美國夏威夷、佛蒙特、緬因同阿拉斯加四州禁止戶外廣告牌，夏威夷早於1927年已經立法。', cat: '奇怪法律', level: 3, src: 'https://en.wikipedia.org/wiki/Billboard' },
  { term: '旺加努伊河', explain: '紐西蘭一條河，2017年獲法例賦予法人身份，等同擁有權利同責任，由兩位代表代佢行事。', cat: '奇怪法律', level: 3, src: 'https://en.wikipedia.org/wiki/Whanganui_River' },
  { term: '灰姑娘法', explain: '南韓2011年起實施嘅法律，禁止未滿16歲青少年喺午夜至清晨六點玩網絡遊戲，2021年決定廢除。', cat: '奇怪法律', level: 1, src: 'https://en.wikipedia.org/wiki/Shutdown_law' },
  { term: '紐約夜總會法', explain: '紐約市1926年至2017年有條法例，未領牌照嘅餐廳同酒吧唔准客人跳舞。', cat: '奇怪法律', level: 3, src: 'https://en.wikipedia.org/wiki/New_York_City_Cabaret_Law' },
  { term: '拿坡里薄餅規格', explain: '歐盟規定正宗拿坡里薄餅要用手整形、唔可以用擀麵棍，仲要喺485度柴燒窯烘60至90秒。', cat: '奇怪法律', level: 2, src: 'https://en.wikipedia.org/wiki/Neapolitan_pizza' },
  { term: '摩納哥禁賭', explain: '摩納哥公民唔准入蒙地卡羅賭場嘅賭博廳，亦唔准喺度打工，據講係當年實質攝政嘅卡羅琳公主基於道德理由訂立。', cat: '奇怪法律', level: 3, src: 'https://en.wikipedia.org/wiki/Monte_Carlo_Casino' },
  { term: '愛德華王子島禁車', explain: '加拿大愛德華王子島1908年立法禁止汽車，當時全島只有七架車，原因包括驚嚇馬匹同路況差。', cat: '奇怪法律', level: 3, src: 'https://en.wikipedia.org/wiki/Prince_Edward_Island_automobile_ban' },
  { term: '格勞賓登禁車', explain: '瑞士格勞賓登州1900至1925年禁止汽車行駛，經過九次公投先解禁。', cat: '奇怪法律', level: 3, src: 'https://en.wikipedia.org/wiki/Grisons_automobile_ban' },
  { term: '代謝症候群法', explain: '日本2008年起要求醫療保險機構為四十至七十四歲投保人每年做特定健診，包括量腰圍，常被誤傳成「肥胖犯法」。', cat: '奇怪法律', level: 2, src: 'https://ja.wikipedia.org/wiki/%E7%89%B9%E5%AE%9A%E5%81%A5%E8%A8%BA%E3%83%BB%E7%89%B9%E5%AE%9A%E4%BF%9D%E5%81%A5%E6%8C%87%E5%B0%8E' },
  { term: '德國廣播費', explain: '德國自2013年起，每個住戶都要繳公共廣播費，不論屋企有冇電視或收音機。', cat: '奇怪法律', level: 2, src: 'https://en.wikipedia.org/wiki/ARD_ZDF_Deutschlandradio_Beitragsservice' },
  { term: '郵寄兒童', explain: '1913年美國開辦包裹郵政時有法律空隙，真係有家長將細路仔當包裹寄，之後郵局明令禁止寄人。', cat: '奇怪法律', level: 1, src: 'https://en.wikipedia.org/wiki/Human_mail' },
  { term: '斷線權', explain: '法國由2017年起，五十人以上嘅公司要同員工商討下班後唔使回覆電郵同訊息嘅規則。', cat: '奇怪法律', level: 2, src: 'https://en.wikipedia.org/wiki/Right_to_disconnect' },
  { term: '硬幣二十枚規定', explain: '日本法律規定，同一面額硬幣，對方只有義務收最多二十枚，例如一円硬幣最多強制收二十個。', cat: '奇怪法律', level: 2, src: 'https://ja.wikipedia.org/wiki/%E6%97%A5%E6%9C%AC%E3%81%AE%E7%A1%AC%E8%B2%A8' },
  { term: '帛琉誓言', explain: '帛琉要求所有旅客入境時，喺入境處職員面前簽署一份環保承諾書，先可以入境。', cat: '奇怪法律', level: 3, src: 'https://www.nationalgeographic.com/travel/article/passport-stamp-ecotourism-pledge' },
  { term: '羊毛帽法', explain: '1571年英國法例要求六歲以上平民（貴族同紳士除外）週日同假日戴本地羊毛帽，用嚟支持羊毛業，1597年廢除。', cat: '奇怪法律', level: 3, src: 'https://en.wikipedia.org/wiki/Caps_Act_1571' },
  { term: '日罰金', explain: '芬蘭超速罰款按收入計，超速21公里或以上就用日罰金，有商人曾因此被罰超過十一萬歐元。', cat: '奇怪法律', level: 3, src: 'https://en.wikipedia.org/wiki/Day-fine' },
  { term: '日本跳舞禁令', explain: '日本風營法曾禁止細過66平方米或凌晨一點後營業嘅夜店容許客人跳舞，2014年內閣同意解禁，2016年修法放寬。', cat: '奇怪法律', level: 2, src: 'https://en.wikipedia.org/wiki/Fueiho' },
  { term: '西班牙階梯罰款', explain: '羅馬自2019年7月起，坐喺西班牙階梯上會被罰250歐元，弄污或損壞階梯就最高罰400歐元。', cat: '奇怪法律', level: 2, src: 'https://en.wikipedia.org/wiki/Spanish_Steps' },
  // ---------------------------------------------------------- 香港冷知識
  { term: '啟德', explain: '名字由何啟同區德各取一字而來，兩人合資成立啟德營業有限公司，喺九龍灣北岸填海發展。', cat: '香港冷知識', level: 2, src: 'https://zh.wikipedia.org/wiki/%E5%95%9F%E5%BE%B7' },
  { term: '黃埔船塢', explain: '紅磡昔日嘅大船塢，公司收購咗廣州黃埔嘅船塢而得名，原址而家係黃埔花園。', cat: '香港冷知識', level: 2, src: 'https://zh.wikipedia.org/wiki/%E9%BB%83%E5%9F%94%E8%88%B9%E5%A1%A2' },
  { term: '添馬', explain: '金鐘政府總部一帶嘅地名，舊稱添馬艦，來自昔日駐港英國皇家海軍嘅軍艦。', cat: '香港冷知識', level: 2, src: 'https://zh.wikipedia.org/wiki/%E6%B7%BB%E9%A6%AC%E8%89%A6' },
  { term: '卑路乍街', explain: '以1841年測量維港嘅英國海軍軍官愛德華·卑路乍命名，佢喺港島東西兩邊各建一座炮台。', cat: '香港冷知識', level: 3, src: 'https://zh.wikipedia.org/wiki/%E5%8D%91%E8%B7%AF%E4%B9%8D%E8%A1%97' },
  { term: '屯門', explain: '意思係「屯兵之門」，唐朝設有屯門軍鎮，係中國歷史文獻最早出現嘅香港地名。', cat: '香港冷知識', level: 2, src: 'https://zh.wikipedia.org/wiki/%E5%B1%AF%E9%96%80' },
  { term: '芒角', explain: '旺角嘅舊稱，因為古時芒草叢生、地形似牛角伸入海；後來變成「望角」，1887年政府已用「旺角」。', cat: '香港冷知識', level: 2, src: 'https://zh.wikipedia.org/wiki/%E6%97%BA%E8%A7%92' },
  { term: '鹽船灣', explain: '銅鑼灣嘅古稱；而家個名係因為未填海前，維多利亞公園東西兩邊海岸線形似銅鑼。', cat: '香港冷知識', level: 3, src: 'https://zh.wikipedia.org/wiki/%E9%8A%85%E9%91%BC%E7%81%A3' },
  { term: '鴨巴甸', explain: '香港仔曾被政府命名為「鴨巴甸」，英文名 Aberdeen 係紀念當時英國外交大臣阿伯丁勳爵。', cat: '香港冷知識', level: 2, src: 'https://zh.wikipedia.org/wiki/%E9%A6%99%E6%B8%AF%E4%BB%94' },
  { term: '鰂魚涌', explain: '名字來自早年溪流有好多鰂魚；英文名 Quarry Bay 就因為19世紀一帶有花崗岩礦場。', cat: '香港冷知識', level: 2, src: 'https://zh.wikipedia.org/wiki/%E9%B0%82%E9%AD%9A%E6%B6%8C' },
  { term: '油麻地', explain: '原本叫「蔴地」，漁民喺度晾曬船上麻纜；1875年左右多咗賣桐油同麻纜嘅店，先改稱油蔴地。', cat: '香港冷知識', level: 1, src: 'https://zh.wikipedia.org/wiki/%E6%B2%B9%E9%BA%BB%E5%9C%B0' },
  { term: '赤柱', explain: '以前有好多木棉樹，鮮紅嘅花喺日出陽光下好似赤紅色嘅柱，因而得名。', cat: '香港冷知識', level: 1, src: 'https://zh.wikipedia.org/wiki/%E8%B5%A4%E6%9F%B1' },
  { term: '石塘咀', explain: '採石場開採完後留低凹陷嘅大石塘，向海一段又尖又窄似鳥咀，所以叫石塘咀。', cat: '香港冷知識', level: 2, src: 'https://zh.wikipedia.org/wiki/%E7%9F%B3%E5%A1%98%E5%92%80' },
  { term: '雪廠街', explain: '中環街道，名字來自1845年設立、儲存由北美洲運來天然冰塊嘅冰庫。', cat: '香港冷知識', level: 2, src: 'https://zh.wikipedia.org/wiki/%E9%9B%AA%E5%BB%A0%E8%A1%97' },
  { term: '蘇杭街', explain: '上環 Jervois Street 嘅中文名，因為街上舖頭多數賣蘇州、杭州嘅布疋絲綢。', cat: '香港冷知識', level: 2, src: 'https://zh.wikipedia.org/wiki/%E8%98%87%E6%9D%AD%E8%A1%97' },
  { term: '洗衣街', explain: '旺角街道，前身係灌溉用嘅小水溪；1920年代附近婦女接街坊洗衣服，居民就叫溪邊小徑做洗衣街。', cat: '香港冷知識', level: 2, src: 'https://zh.wikipedia.org/wiki/%E6%B4%97%E8%A1%A3%E8%A1%97' },
  { term: '茶果嶺', explain: '山上有好多茶果樹而得名，「茶果樹」其實係血桐，因為蒸茶果時要用大量血桐葉。', cat: '香港冷知識', level: 2, src: 'https://zh.wikipedia.org/wiki/%E8%8C%B6%E6%9E%9C%E5%B6%BA' },
  { term: '太子', explain: '1922年英國王儲愛德華王子到訪香港，參觀過嘅主要道路後來命名為太子道，地區就因而叫太子。', cat: '香港冷知識', level: 1, src: 'https://zh.wikipedia.org/wiki/%E5%A4%AA%E5%AD%90_(%E9%A6%99%E6%B8%AF)' },
  { term: '協調道', explain: '啟德一條街道，連接世運道同承啟道，名字取自 Concorde 超音速客機。', cat: '香港冷知識', level: 2, src: 'https://zh.wikipedia.org/wiki/%E5%8D%94%E8%AA%BF%E9%81%93' },
  { term: '都爹利街', explain: '中環小街，石階旁嘅煤氣街燈係全港僅餘，1979年列為法定古蹟。', cat: '香港冷知識', level: 2, src: 'https://zh.wikipedia.org/wiki/%E9%83%BD%E7%88%B9%E5%88%A9%E8%A1%97' },
  { term: '宋王臺', explain: '九龍城嘅石刻，相傳紀念南宋端宗南逃至此；碑記指「王」係沿《宋史》之誤，街道同車站就叫宋皇臺。', cat: '香港冷知識', level: 2, src: 'https://zh.wikipedia.org/wiki/%E5%AE%8B%E7%8E%8B%E8%87%BA' },
  { term: '自梳', explain: '舊時廣東女子自行梳起髮髻，表示終身不嫁；1930年代絲業崩潰後，不少自梳女到港做住家女傭「媽姐」。', cat: '香港冷知識', level: 1, src: 'https://zh.wikipedia.org/wiki/%E8%87%AA%E6%A2%B3' },
  { term: '南北行', explain: '昔日香港嘅貿易行業，經營東南亞同中國內地貨物，聚集喺上環文咸東街同文咸西街，兼營找換同匯款。', cat: '香港冷知識', level: 2, src: 'https://zh.wikipedia.org/wiki/%E5%8D%97%E5%8C%97%E8%A1%8C' },
  { term: '金山莊', explain: '二戰前香港嘅商行，主要做同舊金山等北美洲之間嘅貿易同華工出洋，同買辦、南北行並稱三大華商行業。', cat: '香港冷知識', level: 3, src: 'https://zh.wikipedia.org/wiki/%E9%87%91%E5%B1%B1%E8%8E%8A_(%E9%A6%99%E6%B8%AF)' },
  { term: '買辦', explain: '舊時外國洋行僱用嘅華人中間人，英文 comprador 源自葡萄牙文，解作「買方」。', cat: '香港冷知識', level: 2, src: 'https://zh.wikipedia.org/wiki/%E8%B2%B7%E8%BE%A6' },
  { term: '大笪地', explain: '粵語指「一大塊空地」，最初指上環嘅露天夜市，賣平貨兼有表演，俗稱「平民夜總會」。', cat: '香港冷知識', level: 2, src: 'https://zh.wikipedia.org/wiki/%E5%A4%A7%E7%AC%AA%E5%9C%B0' },
  { term: '二叔公', explain: '粵港地區對當舖嘅舊稱，傳統當舖行業分為典、當、按、押四類。', cat: '香港冷知識', level: 2, src: 'https://zh.wikipedia.org/wiki/%E5%85%B8%E7%95%B6%E6%A5%AD' },
  { term: '雞公碗', explain: '印有大公雞圖案嘅傳統瓷碗，據載最早喺明朝成化年間出現，1960年代香港好多家庭都有。', cat: '香港冷知識', level: 1, src: 'https://zh.wikipedia.org/wiki/%E9%9B%9E%E5%85%AC%E7%A2%97' },
  { term: '深水埗', explain: '「埗」同「埔」「埠」相通，都解作碼頭，意思係深水而無淺灘嘅海灣；舊時亦寫作深水埔。', cat: '香港冷知識', level: 1, src: 'https://zh.wikipedia.org/wiki/%E6%B7%B1%E6%B0%B4%E5%9F%97' },
  { term: '九龍塘', explain: '「塘」指水塘：19世紀末淺灣中築咗海堤連接深水埗，海灣變成水塘，九龍塘因而得名。', cat: '香港冷知識', level: 2, src: 'https://zh.wikipedia.org/wiki/%E4%B9%9D%E9%BE%8D%E5%A1%98' },
  { term: '荷李活道', explain: '同美國荷里活電影無關，1841年命名時荷里活仲未成電影中心；一般相信來自附近冬青樹（holly）成林（wood）。', cat: '香港冷知識', level: 1, src: 'https://zh.wikipedia.org/wiki/%E8%8D%B7%E6%9D%8E%E6%B4%BB%E9%81%93' },
  { term: '鑽石山', explain: '山上並冇鑽石；一般接受嘅講法係「鑽」係動詞，因為山上有石礦場，要鑽開岩石。', cat: '香港冷知識', level: 1, src: 'https://zh.wikipedia.org/wiki/%E9%91%BD%E7%9F%B3%E5%B1%B1' },
  { term: '筲箕灣', explain: '原本係個好圓嘅海灣，形似一個大筲箕（竹篩），因而得名；明朝萬曆年間嘅《粵大記》已有記載。', cat: '香港冷知識', level: 1, src: 'https://zh.wikipedia.org/wiki/%E7%AD%B2%E7%AE%95%E7%81%A3' },
  { term: '紅磡', explain: '「磡」指突出嘅小岩崖或者船隻泊岸嘅凹入處；1856年前海邊全係紅色岩石，所以叫紅磡。', cat: '香港冷知識', level: 1, src: 'https://zh.wikipedia.org/wiki/%E7%B4%85%E7%A3%A1' },
  { term: '大牌檔', explain: '「大牌」係固定小販牌照，要裱起掛喺檔位當眼處，所以持牌嘅街頭熟食檔就叫大牌檔。', cat: '香港冷知識', level: 1, src: 'https://zh.wikipedia.org/wiki/%E5%A4%A7%E6%8E%92%E6%AA%94' },
  { term: '藍田', explain: '舊名「咸田」，因為近海、泥土鹹；1970年諮詢居民後改名藍田，取「藍田生玉」之意。', cat: '香港冷知識', level: 3, src: 'https://zh.wikipedia.org/wiki/%E8%97%8D%E7%94%B0_(%E9%A6%99%E6%B8%AF)' },
  { term: '彌敦道', explain: '原名羅便臣道，1909年改叫彌敦道；擴闊成六線大道時九龍人煙稀少，曾被取笑為「彌敦的蠢事」。', cat: '香港冷知識', level: 1, src: 'https://zh.wikipedia.org/wiki/%E5%BD%8C%E6%95%A6%E9%81%93' },
  { term: '鯉魚門', explain: '一般認為因為海峽形似魚口而得名，「門」指海峽；鯉魚跳龍門嘅傳說就欠缺歷史根據。', cat: '香港冷知識', level: 2, src: 'https://zh.wikipedia.org/wiki/%E9%AF%89%E9%AD%9A%E9%96%80' },
  { term: '冰室', explain: '香港冰室原本只賣冰飲同小食、唔賣主食，因為佢哋持嘅係「小食食肆」牌照，而唔係普通食肆牌照。', cat: '香港冷知識', level: 1, src: 'https://zh.wikipedia.org/wiki/%E5%86%B0%E5%AE%A4' },
  { term: '香埗頭', explain: '尖沙咀嘅舊稱，因為東莞出產嘅莞香木喺度嘅碼頭轉運而得名。', cat: '香港冷知識', level: 2, src: 'https://zh.wikipedia.org/wiki/%E5%B0%96%E6%B2%99%E5%92%80' },
  // ---------------------------------------------------------- 食物名稱由來
  { term: '竹昇麵', explain: '用竹竿壓出嚟嘅麵；廣東人覺得「竿」同「降」諧音唔吉利，所以改叫「昇」。', cat: '食物名稱由來', level: 2, src: 'https://zh.wikipedia.org/wiki/%E7%AB%B9%E6%98%87%E9%BA%B5' },
  { term: '雞尾包', explain: '一般講法係餡料用舊麵包、砂糖同椰絲混合而成，好似雞尾酒混合唔同酒品，因而得名。', cat: '食物名稱由來', level: 1, src: 'https://zh.wikipedia.org/wiki/%E9%9B%9E%E5%B0%BE%E5%8C%85' },
  { term: '伊麵', explain: '相傳清代官員伊秉綬為減輕家廚負擔，叫人將蛋麵炸乾保存，後人因而叫伊府麵、伊麵。', cat: '食物名稱由來', level: 2, src: 'https://zh.wikipedia.org/wiki/%E4%BC%8A%E9%BA%B5' },
  { term: '宮保雞丁', explain: '相傳由四川總督丁寶楨發明，佢官銜係太子少保，俗稱「丁宮保」，菜式因而得名。', cat: '食物名稱由來', level: 1, src: 'https://zh.wikipedia.org/wiki/%E5%AE%AE%E4%BF%9D%E9%9B%9E%E4%B8%81' },
  { term: '麻婆豆腐', explain: '「麻」係指清代成都發明者陳劉氏臉上嘅麻點，唔係指花椒嘅麻味。', cat: '食物名稱由來', level: 1, src: 'https://zh.wikipedia.org/wiki/%E9%BA%BB%E5%A9%86%E8%B1%86%E8%85%90' },
  { term: '部隊鍋', explain: '韓國火鍋，「部隊」指軍營；約韓戰時期出現，用午餐肉、腸仔等加工食品煮成。', cat: '食物名稱由來', level: 1, src: 'https://en.wikipedia.org/wiki/Budae-jjigae' },
  { term: 'ナポリタン（naporitan）', explain: '日本自創嘅茄汁炒意粉，名字借用拿坡里，但拿坡里冇呢款菜；一般認為源自橫濱 Hotel New Grand。', cat: '食物名稱由來', level: 2, src: 'https://ja.wikipedia.org/wiki/%E3%83%8A%E3%83%9D%E3%83%AA%E3%82%BF%E3%83%B3' },
  { term: '他人丼', explain: '用豬肉或牛肉加蛋嘅日式飯，對比用雞同蛋嘅「親子丼」，肉同蛋唔係親屬，所以叫「他人」。', cat: '食物名稱由來', level: 1, src: 'https://ja.wikipedia.org/wiki/%E4%BB%96%E4%BA%BA%E4%B8%BC' },
  { term: 'もんじゃ焼き（monjayaki）', explain: '名字來自江戶至明治時期嘅「文字燒」，小朋友用甜麵糊喺鐵板上寫字玩嘅零食。', cat: '食物名稱由來', level: 2, src: 'https://ja.wikipedia.org/wiki/%E3%82%82%E3%82%93%E3%81%98%E3%82%83%E7%84%BC%E3%81%8D' },
  { term: 'ラムネ（ramune）', explain: '日本玻璃珠汽水，名字係英文 lemonade 嘅轉音，1884年由蘇格蘭藥劑師 Alexander Sim 引入神戶。', cat: '食物名稱由來', level: 2, src: 'https://en.wikipedia.org/wiki/Ramune' },
  { term: '金平糖（konpeito）', explain: '日本嘅星形糖粒，名字來自葡萄牙文 confeito，十六世紀由葡萄牙商人傳入。', cat: '食物名稱由來', level: 2, src: 'https://en.wikipedia.org/wiki/Konpeit%C5%8D' },
  { term: 'カルピス（Calpis）', explain: '日本乳酸飲品，名字由 calcium 嘅「cal」加梵文 sarpiṣ（酥油）嘅「pis」合成。', cat: '食物名稱由來', level: 2, src: 'https://en.wikipedia.org/wiki/Calpis' },
  { term: '養樂多（Yakult）', explain: '名字取自世界語 jahurto，意思係乳酪（yogurt）。', cat: '食物名稱由來', level: 1, src: 'https://en.wikipedia.org/wiki/Yakult' },
  { term: 'ポッキー（Pocky）', explain: '日本長條餅乾，名字來自折斷餅乾時發出嘅日文擬聲詞。', cat: '食物名稱由來', level: 1, src: 'https://en.wikipedia.org/wiki/Pocky' },
  { term: '羊羹（yokan）', explain: '源自中國嘅羊肉羹；日本冇食肉習慣，改用小麥粉或紅豆粉做，後來先演變成甜點。', cat: '食物名稱由來', level: 2, src: 'https://en.wikipedia.org/wiki/Y%C5%8Dkan' },
  { term: 'おでん（oden）', explain: '關東煮嘅名字，原本係宮廷女性用語，即係「田楽」加敬語「お」；江戶時代起專指燉煮版本。', cat: '食物名稱由來', level: 2, src: 'https://ja.wikipedia.org/wiki/%E3%81%8A%E3%81%A7%E3%82%93' },
  { term: 'ひつまぶし（hitsumabushi）', explain: '名古屋鰻魚飯，一般講法係名字來自盛飯嘅木「櫃」（ohitsu）加「まぶす」（鋪上去）。', cat: '食物名稱由來', level: 3, src: 'https://ja.wikipedia.org/wiki/%E3%81%B2%E3%81%A4%E3%81%BE%E3%81%B6%E3%81%97' },
  { term: 'わんこそば（wanko soba）', explain: '岩手縣嘅蕎麥麵，「わんこ」係當地方言「碗」，用細碗盛住，食完即時添。', cat: '食物名稱由來', level: 3, src: 'https://en.wikipedia.org/wiki/Wanko_soba' },
  { term: 'ジンギスカン（jingisukan）', explain: '日本烤羊肉，名字取自成吉思汗，用中間凸起嘅鍋燒；邊度係發源地仍有爭議。', cat: '食物名稱由來', level: 2, src: 'https://en.wikipedia.org/wiki/Jingisukan' },
  { term: '出前一丁', explain: '日文原意係「外賣一份」，1968年喺日本發售，翌年進入香港市場。', cat: '食物名稱由來', level: 1, src: 'https://zh.wikipedia.org/wiki/%E5%87%BA%E5%89%8D%E4%B8%80%E4%B8%81' },
  { term: '凱撒沙律', explain: '同羅馬凱撒大帝無關，1924年由意大利移民餐廳老闆 Caesar Cardini 喺墨西哥蒂華納整出嚟。', cat: '食物名稱由來', level: 1, src: 'https://en.wikipedia.org/wiki/Caesar_salad' },
  { term: '巴甫洛娃（Pavlova）', explain: '澳洲同新西蘭嘅蛋白餅甜品，名字取自俄羅斯芭蕾舞者安娜·巴甫洛娃。', cat: '食物名稱由來', level: 2, src: 'https://en.wikipedia.org/wiki/Pavlova_(cake)' },
  { term: 'Tarte Tatin', explain: '以 Tatin 姊妹命名嘅反轉蘋果撻，相傳係佢哋喺法國經營嘅酒店廚房失手整出嚟。', cat: '食物名稱由來', level: 3, src: 'https://en.wikipedia.org/wiki/Tarte_Tatin' },
  { term: 'Nachos', explain: '名字來自1943年墨西哥一間餐廳嘅領班 Ignacio「Nacho」Anaya，佢用手邊材料即興整出呢道小食。', cat: '食物名稱由來', level: 2, src: 'https://en.wikipedia.org/wiki/Nachos' },
  { term: '夏威夷薄餅', explain: '唔係喺夏威夷發明，1962年由加拿大一間餐廳嘅希臘裔老闆整出嚟，名字來自用咗 Hawaiian 牌罐頭菠蘿。', cat: '食物名稱由來', level: 1, src: 'https://en.wikipedia.org/wiki/Hawaiian_pizza' },
  { term: '夫妻肺片', explain: '1930年代成都郭朝華、張田政夫婦創製，原名「燴片」或「廢片」；而家嘅版本其實唔用肺。', cat: '食物名稱由來', level: 2, src: 'https://zh.wikipedia.org/wiki/%E5%A4%AB%E5%A6%BB%E8%82%BA%E7%89%87' },
  { term: '左宗棠雞', explain: '同湖南名將左宗棠冇歷史關係，係事後先用佢命名；彭長貴話1950年代喺台灣創製，另有廚師話1972年喺紐約發明。', cat: '食物名稱由來', level: 1, src: 'https://en.wikipedia.org/wiki/General_Tso%27s_chicken' },
  { term: 'Pad Thai（泰式炒河粉）', explain: '二戰時泰國米荒，總理鑾披汶推廣食米粉，炒河粉成為建立泰國民族身份嘅菜式。', cat: '食物名稱由來', level: 2, src: 'https://en.wikipedia.org/wiki/Pad_thai' },
  { term: 'カステラ（castella）', explain: '長崎蛋糕，名字源自葡萄牙文 Bolo de Castela，意思係「卡斯蒂利亞（西班牙王國）嘅蛋糕」。', cat: '食物名稱由來', level: 2, src: 'https://en.wikipedia.org/wiki/Castella' },
  { term: '天ぷら（tempura）', explain: '名字一說源自葡萄牙文 tempero（調味），或拉丁文 tempora（齋戒期）；16世紀末由傳教士傳入長崎。', cat: '食物名稱由來', level: 2, src: 'https://en.wikipedia.org/wiki/Tempura' },
  { term: '大福（daifuku）', explain: '原本叫「腹太餅」，因為日文「腹」同「福」同音，後來改叫「大福」，取其吉利。', cat: '食物名稱由來', level: 3, src: 'https://en.wikipedia.org/wiki/Daifuku' },
  { term: '幸運餅乾（fortune cookie）', explain: '唔係中國發明，一般認為源自日本移民喺美國加州整嘅餅乾，二戰前後先變成華人餐館常見嘅食物。', cat: '食物名稱由來', level: 1, src: 'https://en.wikipedia.org/wiki/Fortune_cookie' },
  { term: 'Peach Melba', explain: '1892年前後法國名廚 Escoffier 喺倫敦 Savoy 酒店，為澳洲女高音 Nellie Melba 創作嘅雪糕甜品。', cat: '食物名稱由來', level: 2, src: 'https://en.wikipedia.org/wiki/Peach_Melba' },
  // ---------------------------------------------------------- 冷門運動同遊戲術語
  { term: '藤球（sepak takraw）', explain: '東南亞嘅排球式運動，用藤編球，球員唔可以用手，只可以用腳、膝、頭等部位。', cat: '冷門運動同遊戲術語', level: 1, src: 'https://en.wikipedia.org/wiki/Sepak_takraw' },
  { term: '卡巴迪（kabaddi）', explain: '南亞嘅團體運動，攻方一人入對方半場拍人，期間要一口氣不斷喊「kabaddi」。', cat: '冷門運動同遊戲術語', level: 1, src: 'https://en.wikipedia.org/wiki/Kabaddi' },
  { term: '巧固球（tchoukball）', explain: '1970年代由瑞士人 Hermann Brandt 發明，為減少運動傷害而設計嘅無身體碰撞球類運動。', cat: '冷門運動同遊戲術語', level: 2, src: 'https://en.wikipedia.org/wiki/Tchoukball' },
  { term: '合球（korfball）', explain: '1902年荷蘭人 Nico Broekhuysen 發明嘅男女混合球類運動，每隊場上四男四女。', cat: '冷門運動同遊戲術語', level: 3, src: 'https://en.wikipedia.org/wiki/Korfball' },
  { term: 'Kin-Ball', explain: '加拿大魁北克1986年發明，三隊同場比賽，用直徑約1.2米嘅巨型球。', cat: '冷門運動同遊戲術語', level: 3, src: 'https://en.wikipedia.org/wiki/Kin-Ball' },
  { term: '槌球（gateball）', explain: '1947年由日本北海道嘅鈴木和伸發明，因為當時橡膠短缺，佢改用木材做球同球槌。', cat: '冷門運動同遊戲術語', level: 3, src: 'https://en.wikipedia.org/wiki/Gateball' },
  { term: 'Mölkky', explain: '芬蘭擲木棍遊戲，要啱啱好得50分先贏，超過就要扣返去25分。', cat: '冷門運動同遊戲術語', level: 2, src: 'https://en.wikipedia.org/wiki/M%C3%B6lkky' },
  { term: 'Kubb', explain: '瑞典嘅「維京棋」，用木棒擲倒對方嘅木塊，最後再擲倒中間嘅「國王」先贏。', cat: '冷門運動同遊戲術語', level: 3, src: 'https://en.wikipedia.org/wiki/Kubb' },
  { term: '回力球（jai alai）', explain: '巴斯克運動，名字意思係「歡樂節慶」，用籃狀手套擲球，球速驚人，被巴斯克政府宣傳為最快嘅運動。', cat: '冷門運動同遊戲術語', level: 2, src: 'https://en.wikipedia.org/wiki/Jai_alai' },
  { term: '法式滾球（pétanque）', explain: '名字源自普羅旺斯語「腳固定」，因為投球時雙腳要企穩喺圈入面。', cat: '冷門運動同遊戲術語', level: 2, src: 'https://en.wikipedia.org/wiki/P%C3%A9tanque' },
  { term: '水下曲棍球', explain: '1954年英國 Southsea 潛水會嘅會員發明，英國叫 Octopush，原意係令會員冬天都保持活躍。', cat: '冷門運動同遊戲術語', level: 2, src: 'https://en.wikipedia.org/wiki/Underwater_hockey' },
  { term: '棋拳（chessboxing）', explain: '輪流打西洋棋同拳擊嘅比賽，可以將死對手或者擊倒對手獲勝。', cat: '冷門運動同遊戲術語', level: 2, src: 'https://en.wikipedia.org/wiki/Chess_boxing' },
  { term: '匹克球嘅「廚房」', explain: '匹克球近網約2.1米嘅範圍，球員企喺入面唔可以凌空打球，要等球彈地先可以打。', cat: '冷門運動同遊戲術語', level: 2, src: 'https://en.wikipedia.org/wiki/Pickleball' },
  { term: '橫綱', explain: '相撲最高等級，名字嘅「綱」係指力士腰間嗰條代表身份嘅粗繩。', cat: '冷門運動同遊戲術語', level: 1, src: 'https://en.wikipedia.org/wiki/Yokozuna_(sumo)' },
  { term: '金星（相撲）', explain: '相撲術語，地位較低嘅平幕力士擊敗橫綱所得嘅特別勝利記號。', cat: '冷門運動同遊戲術語', level: 3, src: 'https://en.wikipedia.org/wiki/Kinboshi' },
  { term: '甲子園', explain: '阪神甲子園球場1924年啟用，名字來自當年係干支紀年嘅「甲子」年。', cat: '冷門運動同遊戲術語', level: 1, src: 'https://en.wikipedia.org/wiki/Koshien_Stadium' },
  { term: '駅伝（ekiden）', explain: '日本嘅公路接力賽跑，名字來自古代用驛站接力傳遞消息嘅制度。', cat: '冷門運動同遊戲術語', level: 2, src: 'https://en.wikipedia.org/wiki/Ekiden' },
  { term: '划艇嘅 catch a crab', explain: '划艇術語，槳葉離唔開水面，變成煞車咁拖慢船，嚴重時可以將划手彈出艇外。', cat: '冷門運動同遊戲術語', level: 3, src: 'https://en.wikipedia.org/wiki/Glossary_of_rowing_terms' },
  { term: 'Golden duck', explain: '板球術語，打擊手第一球就出局，一分未得。', cat: '冷門運動同遊戲術語', level: 2, src: 'https://en.wikipedia.org/wiki/Glossary_of_cricket_terms' },
  { term: 'Nightwatchman', explain: '板球術語，日落前派較弱嘅打擊手先上場撐住，保護主力打擊手留待翌日。', cat: '冷門運動同遊戲術語', level: 3, src: 'https://en.wikipedia.org/wiki/Nightwatchman_(cricket)' },
  { term: 'Maiden over', explain: '板球術語，投手喺一個 over（六球）入面冇失一分，係出色表現。', cat: '冷門運動同遊戲術語', level: 3, src: 'https://en.wikipedia.org/wiki/Maiden_(cricket)' },
  { term: 'Googly', explain: '板球投球術語，腕旋投手投出嘅球，手勢似普通旋球，但球彈地後轉向相反方向。', cat: '冷門運動同遊戲術語', level: 2, src: 'https://en.wikipedia.org/wiki/Glossary_of_cricket_terms' },
  { term: 'Mulligan', explain: '高爾夫球術語，休閒賽中容許重打一桿而唔計桿數，正式比賽唔准用。', cat: '冷門運動同遊戲術語', level: 1, src: 'https://en.wikipedia.org/wiki/Glossary_of_golf' },
  { term: '攀石嘅 beta', explain: '攀石術語，指一條路線點樣爬嘅資訊，例如手腳點同發力次序。', cat: '冷門運動同遊戲術語', level: 2, src: 'https://en.wikipedia.org/wiki/Glossary_of_climbing_terms' },
  { term: '攀石嘅 crux', explain: '攀石術語，指一條路線入面最困難嘅一段。', cat: '冷門運動同遊戲術語', level: 2, src: 'https://en.wikipedia.org/wiki/Glossary_of_climbing_terms' },
  { term: 'Ollie', explain: '滑板基本跳躍動作，名字來自1970年代首創相近動作嘅滑手 Alan Gelfand 嘅花名。', cat: '冷門運動同遊戲術語', level: 2, src: 'https://en.wikipedia.org/wiki/Ollie_(skateboarding)' },
  { term: 'Goofy（單板滑雪）', explain: '單板滑雪嘅站姿，右腳喺前面；左腳喺前面就叫 regular。', cat: '冷門運動同遊戲術語', level: 2, src: 'https://en.wikipedia.org/wiki/Footedness' },
  { term: 'Garryowen（橄欖球）', explain: '橄欖球術語，將球高高踢起令隊友追落點爭球，名字來自愛爾蘭利莫瑞克嘅 Garryowen 球會。', cat: '冷門運動同遊戲術語', level: 3, src: 'https://en.wikipedia.org/wiki/Bomb_(kick)' },
  { term: 'Nine-darter', explain: '飛鏢501比賽中只用九枝鏢完成，係理論上最少嘅支數，被視為完美。', cat: '冷門運動同遊戲術語', level: 3, src: 'https://en.wikipedia.org/wiki/Nine-dart_finish' },
  { term: 'Spirit of the Game', explain: '極限飛盤傳統上冇裁判，球員自己叫犯規，靠呢種運動精神維持公平。', cat: '冷門運動同遊戲術語', level: 2, src: 'https://en.wikipedia.org/wiki/Ultimate_(sport)' },
  { term: '草地滾球嘅 jack', explain: '草地滾球入面嘅小球，參賽者要將大球盡量滾近佢，又叫 kitty。', cat: '冷門運動同遊戲術語', level: 2, src: 'https://en.wikipedia.org/wiki/Bowls' },
  { term: '冰壺嘅 hammer', explain: '冰壺術語，指一局最後一粒擲出嘅石壺；擁有佢嘅隊伍佔優勢。', cat: '冷門運動同遊戲術語', level: 3, src: 'https://en.wikipedia.org/wiki/Curling' },
  { term: 'Meeple', explain: '桌遊入面嘅人形木製棋子，名字係2000年有玩家玩 Carcassonne 時，將「my people」讀快咗而成。', cat: '冷門運動同遊戲術語', level: 2, src: 'https://en.wikipedia.org/wiki/Meeple' },
  { term: 'Kingmaking', explain: '多人遊戲術語，指自己已無機會贏嘅玩家，反而可以決定邊個對手贏。', cat: '冷門運動同遊戲術語', level: 3, src: 'https://en.wikipedia.org/wiki/Kingmaker_scenario' },
  { term: 'Rubber banding', explain: '賽車遊戲設計，電腦對手落後時會突然變快、領先時變慢，令比賽保持緊張。', cat: '冷門運動同遊戲術語', level: 3, src: 'https://en.wikipedia.org/wiki/Dynamic_game_difficulty_balancing' },
  { term: 'Coyote time', explain: '平台遊戲設計，角色走出邊緣後短時間內仍可起跳，名字來自卡通郊狼跑出懸崖後懸空嘅橋段。', cat: '冷門運動同遊戲術語', level: 3, src: 'https://en.wikipedia.org/wiki/Glossary_of_video_game_terms' },
  { term: 'i-frame', explain: '遊戲術語「無敵幀」，指翻滾、閃避等動作期間，角色短暫唔會受傷害。', cat: '冷門運動同遊戲術語', level: 3, src: 'https://en.wikipedia.org/wiki/Glossary_of_video_game_terms' },
  { term: 'Atari', explain: '遊戲公司名取自圍棋術語 atari，意思係「擊中目標」，即下一手就可以提走對方棋子。', cat: '冷門運動同遊戲術語', level: 1, src: 'https://en.wikipedia.org/wiki/Atari' },
  { term: '花札嘅 koi-koi', explain: '日文「こいこい」解作「來吧」，組成牌型後可以喊呢句繼續玩，搏更高分。', cat: '冷門運動同遊戲術語', level: 3, src: 'https://en.wikipedia.org/wiki/Koi-Koi' },
  { term: '貼目（komi）', explain: '圍棋規則，白棋後行，所以計算勝負時要加返分數補償黑棋嘅先行優勢。', cat: '冷門運動同遊戲術語', level: 3, src: 'https://en.wikipedia.org/wiki/Komi_(Go)' },
  { term: '白臉將', explain: '象棋殺法，利用「將帥唔可以同線無阻對面」嘅規則，用車等棋子將對方將死。', cat: '冷門運動同遊戲術語', level: 2, src: 'https://zh.wikipedia.org/wiki/%E5%B8%A5_(%E4%B8%AD%E5%9C%8B%E8%B1%A1%E6%A3%8B)' },
  { term: '九子連環', explain: '香港麻雀極罕有嘅牌型，門前清集齊同一花色 1112345678999，再加任何一隻同花色嘅牌食糊。', cat: '冷門運動同遊戲術語', level: 2, src: 'https://zh.wikipedia.org/zh-hk/%E9%A6%99%E6%B8%AF%E9%BA%BB%E9%9B%80%E5%B8%B8%E7%94%A8%E7%95%AA%E7%A8%AE' },
  { term: '十八羅漢', explain: '麻雀牌型，四組槓加一對將，食糊時合共十八隻牌，因而得名。', cat: '冷門運動同遊戲術語', level: 2, src: 'https://zh.wikipedia.org/zh-hk/%E5%9B%9B%E6%A7%93' },
  { term: 'Zugzwang', explain: '西洋棋術語，德文解作「被迫行棋」，輪到邊方行棋，局面就變得更差。', cat: '冷門運動同遊戲術語', level: 2, src: 'https://en.wikipedia.org/wiki/Zugzwang' },
  { term: 'Fianchetto', explain: '西洋棋術語，意大利文解作「小側翼」，指將主教移到 b2 或 g2（黑方 b7、g7）控制長斜線。', cat: '冷門運動同遊戲術語', level: 3, src: 'https://en.wikipedia.org/wiki/Fianchetto' },
  { term: '撲克嘅 muck', explain: '撲克術語，棄牌，或者唔亮牌就將手牌放入棄牌堆。', cat: '冷門運動同遊戲術語', level: 3, src: 'https://en.wikipedia.org/wiki/Glossary_of_poker_terms' },
  { term: '撲克嘅 rake', explain: '撲克室喺每手底池抽走嘅佣金，係撲克室嘅主要收入來源。', cat: '冷門運動同遊戲術語', level: 3, src: 'https://en.wikipedia.org/wiki/Glossary_of_poker_terms' },
  { term: '撲克嘅 bubble', explain: '撲克錦標賽入面，仲差一個淘汰就入錢圈嘅階段，大家都會打得好保守。', cat: '冷門運動同遊戲術語', level: 2, src: 'https://en.wikipedia.org/wiki/Glossary_of_poker_terms' },
  { term: '大富翁（Monopoly）', explain: '前身係1904年 Elizabeth Magie 設計嘅「地主遊戲」，原意係教人認識土地壟斷嘅問題。', cat: '冷門運動同遊戲術語', level: 1, src: 'https://en.wikipedia.org/wiki/The_Landlord%27s_Game' },
  { term: 'Cluedo', explain: '名字係 clue 加 Ludo（拉丁文「我玩」）合成，美國版就叫 Clue。', cat: '冷門運動同遊戲術語', level: 2, src: 'https://en.wikipedia.org/wiki/Cluedo' },
  { term: 'Mafia（派對遊戲）', explain: '1986年由莫斯科大學一位心理系學生設計嘅派對遊戲，玩家分成平民同黑幫，後來先演變出狼人版本。', cat: '冷門運動同遊戲術語', level: 3, src: 'https://en.wikipedia.org/wiki/Mafia_(party_game)' },
  { term: 'Jenga', explain: '疊木塊再逐塊抽走嘅遊戲，名字來自斯瓦希里文 kujenga，意思係「建造」。', cat: '冷門運動同遊戲術語', level: 2, src: 'https://en.wikipedia.org/wiki/Jenga' },
  { term: 'Tetris', explain: '名字由希臘文 tetra（四）加創作者 Alexey Pajitnov 最鍾意嘅運動 tennis 合成。', cat: '冷門運動同遊戲術語', level: 1, src: 'https://en.wikipedia.org/wiki/Tetris' },
  { term: '數獨（Sudoku）', explain: '名字來自日文「数字は独身に限る」（數字要單獨），由出版社 Nikoli 縮短成 Sudoku。', cat: '冷門運動同遊戲術語', level: 1, src: 'https://en.wikipedia.org/wiki/Sudoku' },
  { term: '長曲棍球（lacrosse）', explain: '1637年法國耶穌會傳教士見到休倫人玩呢種球類運動，用法文 la crosse（彎杖）稱呼，名字沿用至今。', cat: '冷門運動同遊戲術語', level: 3, src: 'https://en.wikipedia.org/wiki/Lacrosse' },
  { term: 'Slalom', explain: '迴旋滑雪，名字源自挪威方言 slalåm：sla 解斜坡，låm 解滑雪板留低嘅軌跡。', cat: '冷門運動同遊戲術語', level: 3, src: 'https://en.wikipedia.org/wiki/Slalom_skiing' },
  { term: 'Caddie', explain: '高爾夫球童，字源係法文 cadet（學員軍官），17世紀蘇格蘭文 caddie 先指做雜工嘅人，後來變成揹球桿嘅人。', cat: '冷門運動同遊戲術語', level: 3, src: 'https://en.wikipedia.org/wiki/Caddie' },
  { term: 'Bogey（高爾夫）', explain: '約1890年英國 Great Yarmouth 球會創出，原指好球手每洞應打嘅桿數，球員同想像對手「Colonel Bogey」比賽。', cat: '冷門運動同遊戲術語', level: 2, src: 'https://en.wikipedia.org/wiki/Bogey_(golf)' },
  { term: 'Hat-trick', explain: '源自1858年板球，H. H. Stephenson 連續三球取三名打擊手出局，球迷籌款買咗頂帽送俾佢。', cat: '冷門運動同遊戲術語', level: 1, src: 'https://en.wikipedia.org/wiki/Hat-trick' },
  { term: 'Gambit', explain: '西洋棋棄子開局，字源係意大利文 gambetto（用腳絆人），1561年起用嚟形容棄子爭先嘅開局。', cat: '冷門運動同遊戲術語', level: 2, src: 'https://en.wikipedia.org/wiki/Gambit' },
];
